const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/(marketing)/changelog/page.tsx":"\"use client\";\nimport { useRef } from \"react\";\nimport { motion, useInView } from \"framer-motion\";\nimport { Zap, Package, CreditCard, BarChart2, Shield, Star } from \"lucide-react\";\n\nfunction FadeUp({ children, delay = 0, className = \"\" }: any) {\n  const ref = useRef(null);\n  const inView = useInView(ref, { once: true, margin: \"-60px\" });\n  return (\n    <motion.div ref={ref} initial={{ opacity: 0, y: 30 }} animate={inView ? { opacity: 1, y: 0 } : {}}\n      transition={{ duration: 0.6, delay, ease: [0.22, 1, 0.36, 1] }} className={className}>\n      {children}\n    </motion.div>\n  );\n}\n\nconst changelog = [\n  {\n    version: \"v1.3.0\", date: \"March 2025\", badge: \"Latest\",\n    icon: Zap, color: \"#c9a84c\",\n    updates: [\n      { type: \"new\",  text: \"Inventory management page with low-stock alerts\" },\n      { type: \"new\",  text: \"Order invoice PDF - download from any order\" },\n      { type: \"new\",  text: \"Customer reviews dashboard - approve or reject\" },\n      \n      \n      \n    ],\n  },\n  {\n    version: \"v1.2.0\", date: \"February 2025\", badge: \"Stable\",\n    icon: Package, color: \"#7c3aed\",\n    updates: [\n      { type: \"new\",  text: \"Store customization - fonts, colors, border radius\" },\n      { type: \"new\",  text: \"Coupon engine with % and fixed discount types\" },\n      { type: \"new\",  text: \"Shipping zones by country with free thresholds\" },\n      { type: \"new\",  text: \"Sales reports with CSV export\" },\n      { type: \"new\",  text: \"Product reviews with star ratings on storefronts\" },\n      { type: \"impr\", text: \"Improved dashboard analytics with revenue charts\" },\n    ],\n  },\n  {\n    version: \"v1.1.0\", date: \"January 2025\", badge: null,\n    icon: CreditCard, color: \"#10b981\",\n    updates: [\n      { type: \"new\",  text: \"Paystack and Flutterwave payment gateway support\" },\n      { type: \"new\",  text: \"Payment confirmation and order status emails\" },\n      { type: \"new\",  text: \"Store onboarding wizard for new users\" },\n      { type: \"new\",  text: \"Subscription billing UI with plan comparison\" },\n      \n      { type: \"impr\", text: \"Faster product image uploads with Cloudinary\" },\n    ],\n  },\n  {\n    version: \"v1.0.0\", date: \"December 2024\", badge: \"Launch\",\n    icon: Star, color: \"#f59e0b\",\n    updates: [\n      { type: \"new\",  text: \"Initial public launch of DropOS\" },\n      { type: \"new\",  text: \"Multi-tenant store management\" },\n      { type: \"new\",  text: \"Product catalog with variants and inventory\" },\n      { type: \"new\",  text: \"Order management with status tracking\" },\n      { type: \"new\",  text: \"Stripe payments integration\" },\n      { type: \"new\",  text: \"Admin panel for platform management\" },\n    ],\n  },\n];\n\nconst typeBadge: Record<string, string> = {\n  new:  \"bg-emerald-500/10 text-emerald-400 border-emerald-500/20\",\n  fix:  \"bg-red-500/10 text-red-400 border-red-500/20\",\n  impr: \"bg-blue-500/10 text-blue-400 border-blue-500/20\",\n};\nconst typeLabel: Record<string, string> = { new: \"New\", fix: \"Fix\", impr: \"Improved\" };\n\nexport default function ChangelogPage() {\n  return (\n      <section className=\"pt-40 pb-24 px-6 relative overflow-hidden\">\n        <div className=\"absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] rounded-full pointer-events-none\"\n          style={{ background: \"radial-gradient(circle, rgba(196,168,76,0.05) 0%, transparent 70%)\" }} />\n        <div className=\"max-w-3xl mx-auto relative z-10\">\n          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }} className=\"text-center mb-16\">\n            <span className=\"text-amber-400 text-xs font-bold tracking-widest uppercase\">Changelog</span>\n            <h1 className=\"text-5xl md:text-6xl font-black text-[var(--text-primary)] tracking-tight mt-4 mb-4\">\n              What's{\" \"}\n              <span style={{ background: \"linear-gradient(135deg,#c9a84c,#f0c040)\", WebkitBackgroundClip: \"text\", WebkitTextFillColor: \"transparent\" }}>\n                new\n              </span>\n            </h1>\n            <p className=\"text-[var(--text-secondary)] text-lg\">Every update, improvement and fix - in one place.</p>\n          </motion.div>\n\n          <div className=\"relative\">\n            {/* Timeline line */}\n            <div className=\"absolute left-6 top-0 bottom-0 w-px bg-gradient-to-b from-amber-400/20 via-white/5 to-transparent\" />\n\n            <div className=\"space-y-12\">\n              {changelog.map((release, i) => (\n                <FadeUp key={i} delay={i * 0.1}>\n                  <div className=\"relative pl-16\">\n                    {/* Icon dot */}\n                    <div className=\"absolute left-0 w-12 h-12 rounded-xl flex items-center justify-center border\"\n                      style={{ background: `${release.color}15`, borderColor: `${release.color}30` }}>\n                      <release.icon size={18} style={{ color: release.color }} />\n                    </div>\n\n                    <div className=\"flex items-center gap-3 mb-4\">\n                      <span className=\"text-[var(--text-primary)] font-black text-xl\">{release.version}</span>\n                      {release.badge && (\n                        <span className=\"text-[10px] font-black px-2 py-0.5 rounded-full border\"\n                          style={{ color: release.color, background: `${release.color}15`, borderColor: `${release.color}30` }}>\n                          {release.badge}\n                        </span>\n                      )}\n                      <span className=\"text-[var(--text-tertiary)] text-sm ml-auto\">{release.date}</span>\n                    </div>\n\n                    <div className=\"space-y-2.5\">\n                      {release.updates.map((u, j) => (\n                        <div key={j} className=\"flex items-start gap-3\">\n                          <span className={`text-[10px] font-black px-2 py-0.5 rounded-full border flex-shrink-0 mt-0.5 ${typeBadge[u.type]}`}>\n                            {typeLabel[u.type]}\n                          </span>\n                          <span className=\"text-[var(--text-secondary)] text-sm leading-relaxed\">{u.text}</span>\n                        </div>\n                      ))}\n                    </div>\n                  </div>\n                </FadeUp>\n              ))}\n            </div>\n          </div>\n        </div>\n      </section>\n  );\n}\n","frontend/src/app/(marketing)/privacy/page.tsx":"import Link from \"next/link\";\n\nconst C = { navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.55)\", border:\"rgba(107,53,232,0.1)\" };\n\nfunction Section({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div style={{ marginBottom: 40 }}>\n      <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize: 22, fontWeight: 500, color: C.navy, letterSpacing:\"-0.02em\", margin: \"0 0 14px\" }}>\n        {title}\n      </h2>\n      <div style={{ fontSize: 15, color: C.muted, lineHeight: 1.75 }}>{children}</div>\n    </div>\n  );\n}\n\nexport default function PrivacyPage() {\n  return (\n    <div style={{ background: \"#F4F2FB\", minHeight: \"100vh\", paddingTop: 100, fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');`}</style>\n\n      <div style={{ maxWidth: 720, margin: \"0 auto\", padding: \"0 24px 80px\" }}>\n        {/* Header */}\n        <div style={{ marginBottom: 48 }}>\n          <p style={{ fontSize: 11, fontWeight: 700, letterSpacing: \"0.12em\", color: C.purple, marginBottom: 12, textTransform:\"uppercase\" }}>LEGAL</p>\n          <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize: \"clamp(36px,6vw,52px)\", fontWeight: 500, letterSpacing:\"-0.04em\", color: C.navy, margin:\"0 0 16px\", lineHeight:1.08 }}>\n            Privacy <em style={{ fontStyle:\"italic\", color: C.purple }}>Policy</em>\n          </h1>\n          <p style={{ fontSize: 14, color: C.muted }}>Last updated: 1 June 2026 · Effective immediately</p>\n        </div>\n\n        <div style={{ background:\"#fff\", borderRadius: 20, padding: \"40px 40px\", border:`1px solid ${C.border}`, boxShadow:\"0 2px 20px rgba(107,53,232,0.05)\" }}>\n          <Section title=\"Who we are\">\n            <p>DropOS (\"we\", \"us\", \"our\") is a SaaS dropshipping platform operated by DropOS Ltd. Our registered address and contact email is <a href=\"mailto:hello@droposhq.com\" style={{ color: C.purple }}>hello@droposhq.com</a>.</p>\n            <p style={{ marginTop: 12 }}>This privacy policy explains how we collect, use, store and protect your personal data when you use our platform at <strong>droposhq.com</strong> and related services.</p>\n          </Section>\n\n          <Section title=\"What data we collect\">\n            <p><strong>Account data:</strong> Name, email address, phone number, and password hash when you create an account.</p>\n            <p style={{ marginTop: 10 }}><strong>Store data:</strong> Products, orders, customers, and store settings you create on the platform.</p>\n            <p style={{ marginTop: 10 }}><strong>Payment data:</strong> We do not store card numbers. Payments are processed by Paystack and Stripe — please review their privacy policies.</p>\n            <p style={{ marginTop: 10 }}><strong>Usage data:</strong> Pages visited, features used, browser type, IP address, and device information via analytics tools.</p>\n            <p style={{ marginTop: 10 }}><strong>Communications:</strong> Any messages you send to our support team.</p>\n          </Section>\n\n          <Section title=\"How we use your data\">\n            <ul style={{ paddingLeft: 20, margin: 0 }}>\n              {[\"Provide, operate and improve the DropOS platform\", \"Process payments and prevent fraud\", \"Send transactional emails (receipts, order confirmations)\", \"Send product updates and news (you can opt out anytime)\", \"Respond to support requests\", \"Comply with legal obligations\"].map(i => (\n                <li key={i} style={{ marginBottom: 8 }}>{i}</li>\n              ))}\n            </ul>\n          </Section>\n\n          <Section title=\"Legal basis for processing (GDPR)\">\n            <p>We process your data on the following legal bases:</p>\n            <ul style={{ paddingLeft: 20, margin: \"10px 0 0\" }}>\n              <li style={{ marginBottom: 8 }}><strong>Contract:</strong> Processing necessary to fulfil our agreement with you</li>\n              <li style={{ marginBottom: 8 }}><strong>Legitimate interests:</strong> Analytics and fraud prevention</li>\n              <li style={{ marginBottom: 8 }}><strong>Consent:</strong> Marketing communications and optional cookies</li>\n              <li style={{ marginBottom: 8 }}><strong>Legal obligation:</strong> Compliance with applicable laws</li>\n            </ul>\n          </Section>\n\n          <Section title=\"Data sharing\">\n            <p>We do not sell your data. We share it only with:</p>\n            <ul style={{ paddingLeft: 20, margin: \"10px 0 0\" }}>\n              <li style={{ marginBottom: 8 }}><strong>Paystack / Stripe</strong> — payment processing</li>\n              <li style={{ marginBottom: 8 }}><strong>Resend</strong> — transactional emails</li>\n              <li style={{ marginBottom: 8 }}><strong>KIRO AI engine</strong> — powers AI features. Your messages are processed to generate responses and are not stored for training purposes</li>\n              <li style={{ marginBottom: 8 }}><strong>Cloud infrastructure providers</strong> — secure hosting and data storage</li>\n              <li style={{ marginBottom: 8 }}><strong>Law enforcement</strong> — when legally required</li>\n            </ul>\n          </Section>\n\n          <Section title=\"Data retention\">\n            <p>We retain your account data for as long as your account is active. If you delete your account, your personal data is deleted within 30 days. Order and transaction records may be retained for up to 7 years for legal and accounting purposes.</p>\n          </Section>\n\n          <Section title=\"Your rights\">\n            <p>Under GDPR and applicable data protection laws, you have the right to:</p>\n            <ul style={{ paddingLeft: 20, margin: \"10px 0 0\" }}>\n              {[\"Access your personal data\", \"Correct inaccurate data\", \"Delete your data ('right to be forgotten')\", \"Export your data in a portable format\", \"Object to or restrict certain processing\", \"Withdraw consent at any time\"].map(r => (\n                <li key={r} style={{ marginBottom: 8 }}>{r}</li>\n              ))}\n            </ul>\n            <p style={{ marginTop: 12 }}>To exercise any of these rights, email <a href=\"mailto:privacy@droposhq.com\" style={{ color: C.purple }}>privacy@droposhq.com</a>.</p>\n          </Section>\n\n          <Section title=\"Cookies\">\n            <p>We use essential cookies to keep you logged in and remember your preferences. We also use optional analytics cookies to understand how the platform is used. See our <Link href=\"/cookies\" style={{ color: C.purple }}>Cookie Policy</Link> for full details.</p>\n          </Section>\n\n          <Section title=\"Security\">\n            <p>We use industry-standard security measures including encryption in transit (TLS), hashed passwords, and access controls. No system is 100% secure — please use a strong, unique password.</p>\n          </Section>\n\n          <Section title=\"Children\">\n            <p>DropOS is not intended for users under 16 years old. If you believe a child has provided us with personal data, please contact us immediately.</p>\n          </Section>\n\n          <Section title=\"Changes to this policy\">\n            <p>We may update this policy periodically. We will notify you of significant changes by email or a prominent notice on the platform.</p>\n          </Section>\n\n          <Section title=\"Contact us\">\n            <p>For any privacy-related questions: <a href=\"mailto:privacy@droposhq.com\" style={{ color: C.purple }}>privacy@droposhq.com</a><br/>\n            For general queries: <a href=\"mailto:hello@droposhq.com\" style={{ color: C.purple }}>hello@droposhq.com</a></p>\n          </Section>\n        </div>\n\n        <div style={{ marginTop: 32, display:\"flex\", gap: 16, flexWrap:\"wrap\" }}>\n          <Link href=\"/terms\" style={{ fontSize:13, color: C.purple, fontWeight:600, textDecoration:\"none\" }}>Terms of Use →</Link>\n          <Link href=\"/cookies\" style={{ fontSize:13, color: C.purple, fontWeight:600, textDecoration:\"none\" }}>Cookie Policy →</Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/contact/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { Zap, Mail, MessageSquare, ArrowRight, Check, Loader2 } from \"lucide-react\";\n\nconst API = process.env.NEXT_PUBLIC_API_URL || \"\";\n\nexport default function ContactPage() {\n  const [form, setForm]   = useState({ name: \"\", email: \"\", subject: \"general\", message: \"\" });\n  const [status, setStatus] = useState<\"idle\"|\"loading\"|\"success\"|\"error\">(\"idle\");\n\n  const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));\n\n  const submit = async () => {\n    if (!form.name || !form.email || !form.message) return;\n    setStatus(\"loading\");\n    try {\n      await fetch(`${API}/contact`, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(form),\n      });\n      setStatus(\"success\");\n    } catch {\n      setStatus(\"error\");\n    }\n  };\n\n  const inp = \"w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm text-white placeholder-white/25 outline-none focus:border-violet-500/60 transition-all\";\n\n  return (\n    <div style={{ background: \"#F4F2FB\", color: \"#130D2E\", fontFamily: \"'Plus Jakarta Sans', system-ui, sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n<div className=\"max-w-4xl mx-auto px-6 py-20\">\n        <div className=\"text-center mb-14\">\n          <p className=\"text-xs font-bold tracking-widest uppercase mb-3\" style={{ color: \"#8B5CF6\" }}>Contact</p>\n          <h1 className=\"font-black text-4xl sm:text-5xl mb-4\" style={{ letterSpacing: \"-2px\" }}>Get in touch</h1>\n          <p className=\"text-base\" style={{ color:\"rgba(19,13,46,0.5)\" }}>We reply within 24 hours. For urgent issues, message KIRO in your dashboard.</p>\n        </div>\n\n        <div className=\"grid md:grid-cols-3 gap-10\">\n          {/* Contact options */}\n          <div className=\"space-y-4\">\n            {[\n              { icon: MessageSquare, label: \"General questions\", desc: \"Product, pricing, plans\", color: \"#8B5CF6\" },\n              { icon: Zap,           label: \"Technical support\", desc: \"Bugs, errors, help\",       color: \"#06B6D4\" },\n              { icon: Mail,          label: \"Enterprise\",        desc: \"Custom plans, API access\", color: \"#10B981\" },\n            ].map(c => (\n              <div key={c.label} className=\"p-4 rounded-2xl\" style={{ background: \"rgba(107,53,232,0.03)\", border: \"1px solid rgba(107,53,232,0.08)\" }}>\n                <div className=\"w-9 h-9 rounded-xl flex items-center justify-center mb-3\" style={{ background: `${c.color}15` }}>\n                  <c.icon size={16} style={{ color: c.color }} />\n                </div>\n                <h3 className=\"font-bold text-sm text-white mb-1\">{c.label}</h3>\n                <p className=\"text-xs\" style={{ color:\"rgba(19,13,46,0.5)\" }}>{c.desc}</p>\n              </div>\n            ))}\n            <div className=\"p-4 rounded-2xl\" style={{ background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n              <p className=\"text-xs font-semibold mb-1\" style={{ color: \"#A78BFA\" }}>Fastest response</p>\n              <p className=\"text-xs\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Message KIRO in your dashboard. It knows every feature and can fix most issues instantly.</p>\n              <Link href=\"/auth/login\" className=\"inline-flex items-center gap-1.5 mt-2 text-xs font-bold\" style={{ color: \"#A78BFA\" }}>\n                Open KIRO <ArrowRight size={10} />\n              </Link>\n            </div>\n          </div>\n\n          {/* Form */}\n          <div className=\"md:col-span-2\">\n            {status === \"success\" ? (\n              <div className=\"p-8 rounded-2xl text-center\" style={{ background: \"rgba(16,185,129,0.08)\", border: \"1px solid rgba(16,185,129,0.25)\" }}>\n                <Check size={40} className=\"mx-auto mb-4\" style={{ color: \"#10B981\" }} />\n                <h3 className=\"font-bold text-lg text-white mb-2\">Message sent</h3>\n                <p style={{ color:\"rgba(19,13,46,0.5)\" }}>We'll reply within 24 hours.</p>\n              </div>\n            ) : (\n              <div className=\"space-y-4\">\n                <div className=\"grid grid-cols-2 gap-4\">\n                  <div>\n                    <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Name</label>\n                    <input value={form.name} onChange={e => set(\"name\", e.target.value)} placeholder=\"Your name\" className={inp} />\n                  </div>\n                  <div>\n                    <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Email</label>\n                    <input value={form.email} onChange={e => set(\"email\", e.target.value)} type=\"email\" placeholder=\"you@example.com\" className={inp} />\n                  </div>\n                </div>\n                <div>\n                  <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Subject</label>\n                  <select value={form.subject} onChange={e => set(\"subject\", e.target.value)} className={inp} style={{ cursor: \"pointer\" }}>\n                    <option value=\"general\">General question</option>\n                    <option value=\"support\">Technical support</option>\n                    <option value=\"billing\">Billing issue</option>\n                    <option value=\"enterprise\">Enterprise enquiry</option>\n                    <option value=\"partnership\">Partnership</option>\n                  </select>\n                </div>\n                <div>\n                  <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Message</label>\n                  <textarea value={form.message} onChange={e => set(\"message\", e.target.value)} rows={5} placeholder=\"How can we help?\" className={inp} style={{ resize: \"none\" }} />\n                </div>\n                <button onClick={submit} disabled={!form.name||!form.email||!form.message||status===\"loading\"}\n                  className=\"w-full flex items-center justify-center gap-2 py-3 rounded-xl text-sm font-bold text-white transition-all disabled:opacity-50\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  {status===\"loading\" ? <><Loader2 size={14} className=\"animate-spin\" />Sending</> : \"Send message\"}\n                </button>\n                {status===\"error\" && <p className=\"text-xs text-center text-red-400\">Something went wrong. Try again or email hello@droposhq.com</p>}\n              </div>\n            )}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/(public)/kiro/page.tsx":"\"use client\";\nimport { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport Link from \"next/link\";\nimport dynamic from \"next/dynamic\";\nimport { useAuthStore } from \"../../../store/auth.store\";\n\nconst BASE    = process.env.NEXT_PUBLIC_API_URL || \"\";\nconst ACCENT  = \"#7C3AED\";\nconst ACCENT_D = \"#5B21B6\";\n\nconst KIROChatFull = dynamic(() => import(\"../../../components/kai/KIROChat\"), {\n  ssr: false, loading: () => <Loader />,\n});\n\nconst TL = {\n  bg:\"#F4F2FB\", s1:\"#FAFAFC\", s2:\"#EEEAF8\", s3:\"#E5E0F5\",\n  text:\"#130D2E\", sub:\"rgba(19,13,46,0.6)\", muted:\"rgba(19,13,46,0.38)\",\n  border:\"rgba(100,70,200,0.1)\", borderH:\"rgba(107,53,232,0.3)\",\n  accent:ACCENT, accentD:ACCENT_D, accentBg:ACCENT+\"12\",\n  shadow:\"0 1px 4px rgba(45,27,105,0.06),0 4px 20px rgba(45,27,105,0.04)\",\n  green:\"#059669\", amber:\"#D97706\", red:\"#DC2626\",\n};\nconst TD = {\n  bg:\"#0D0D14\",s1:\"#13131F\",s2:\"#1A1A2A\",s3:\"#232338\",\n  text:\"#F9F8FF\",sub:\"#A0A0C0\",muted:\"#606080\",\n  border:\"rgba(255,255,255,0.07)\",borderH:\"rgba(255,255,255,0.16)\",\n  accent:\"#9061F9\",accentD:ACCENT,accentBg:ACCENT+\"18\",\n  shadow:\"0 1px 4px rgba(0,0,0,0.4)\",\n  green:\"#10B981\",amber:\"#F59E0B\",red:\"#EF4444\",\n};\n\nconst FONTS = `\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n@keyframes spin{to{transform:rotate(360deg)}}\n@keyframes kping{0%,100%{transform:scale(1);opacity:.5}60%{transform:scale(2.4);opacity:0}}\n@keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n@keyframes voicePulse{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.8)}}\n*{box-sizing:border-box}\n::-webkit-scrollbar{width:3px}\n::-webkit-scrollbar-thumb{background:rgba(124,58,237,0.2);border-radius:2px}\n::selection{background:rgba(124,58,237,0.18)}\n`;\n\n// ── History (DB-backed, falls back to localStorage for guests) ──\ninterface Session { id: string; title: string; ts: number; pinned?: boolean; }\nfunction genId() { return Math.random().toString(36).slice(2,10); }\nfunction timeAgo(ts: number) {\n  const d = (Date.now()-ts)/1000;\n  if (d<60) return \"just now\";\n  if (d<3600) return Math.floor(d/60)+\"m ago\";\n  if (d<86400) return Math.floor(d/3600)+\"h ago\";\n  return Math.floor(d/86400)+\"d ago\";\n}\n// localStorage fallbacks for guests\nfunction loadHist(): Session[] {\n  try { return JSON.parse(localStorage.getItem(\"kiro_hist\")||\"[]\"); } catch { return []; }\n}\n// DB-backed helpers (for authed users)\nasync function dbLoadHist(token: string): Promise<Session[]> {\n  try {\n    const r = await fetch(`${BASE}/kai/conversations`, {\n      headers: { \"Authorization\": `Bearer ${token}` }\n    });\n    if (!r.ok) return loadHist();\n    const { data } = await r.json();\n    return (data||[]).map((c: any) => ({\n      id: c.id, title: c.title || \"Untitled\", ts: new Date(c.updatedAt).getTime(), pinned: c.pinned\n    }));\n  } catch { return loadHist(); }\n}\nasync function dbDeleteHist(id: string, token: string) {\n  try { await fetch(`${BASE}/kai/conversations/${id}`, { method: \"DELETE\", headers: { \"Authorization\": `Bearer ${token}` } }); } catch {}\n}\nasync function dbRenameHist(id: string, title: string, token: string) {\n  try { await fetch(`${BASE}/kai/conversations/${id}`, { method: \"PATCH\", headers: { \"Authorization\": `Bearer ${token}`, \"Content-Type\": \"application/json\" }, body: JSON.stringify({ title }) }); } catch {}\n}\nasync function dbPinHist(id: string, pinned: boolean, token: string) {\n  try { await fetch(`${BASE}/kai/conversations/${id}`, { method: \"PATCH\", headers: { \"Authorization\": `Bearer ${token}`, \"Content-Type\": \"application/json\" }, body: JSON.stringify({ pinned }) }); } catch {}\n}\nfunction pushHist(id: string, title: string) {\n  const h = loadHist().filter(x=>x.id!==id);\n  h.unshift({ id, title: title.slice(0,54), ts: Date.now() });\n  localStorage.setItem(\"kiro_hist\", JSON.stringify(h.slice(0,20)));\n}\nfunction delHist(id: string) {\n  localStorage.setItem(\"kiro_hist\", JSON.stringify(loadHist().filter(x=>x.id!==id)));\n}\n\n// ── Primitives ─────────────────────────────────────────────────\nfunction Loader() {\n  return (\n    <div style={{flex:1,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",background:\"#F7F6F3\"}}>\n      <div style={{width:24,height:24,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.8s linear infinite\"}}/>\n    </div>\n  );\n}\n\nfunction Logo({ size=28 }: { size?: number }) {\n  return (\n    <div style={{width:size,height:size,borderRadius:Math.round(size*.27),background:`linear-gradient(145deg,${ACCENT},${ACCENT_D})`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,boxShadow:`0 2px 8px ${ACCENT}40`}}>\n      <svg width={size*.44} height={size*.44} viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\" fillOpacity={.95}/>\n      </svg>\n    </div>\n  );\n}\n\nfunction PulseDot() {\n  return (\n    <span style={{position:\"relative\",display:\"inline-flex\",width:8,height:8,flexShrink:0}}>\n      <span style={{position:\"absolute\",inset:0,borderRadius:\"50%\",background:\"#10B981\",animation:\"kping 1.6s ease-in-out infinite\"}}/>\n      <span style={{width:8,height:8,borderRadius:\"50%\",background:\"#10B981\",position:\"relative\"}}/>\n    </span>\n  );\n}\n\nfunction ModeBtn({ mode, toggle, T }: { mode:\"light\"|\"dark\"; toggle:()=>void; T:typeof TL }) {\n  return (\n    <button onClick={toggle}\n      style={{width:32,height:32,borderRadius:8,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:14,flexShrink:0}}\n      onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n      onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n      {mode===\"light\"\n        ? <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\n        : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>\n      }\n    </button>\n  );\n}\n\n// ── Voice input ────────────────────────────────────────────────\nfunction VoiceBtn({ onTranscript, T }: { onTranscript:(t:string)=>void; T:typeof TL }) {\n  const [state, setState] = useState<\"idle\"|\"recording\"|\"processing\">(\"idle\");\n  const [interim, setInterim] = useState(\"\");\n  const recogRef = useRef<any>(null);\n\n  function start() {\n    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SpeechRecognition) { alert(\"Voice not supported in this browser\"); return; }\n    const r = new SpeechRecognition();\n    r.continuous = true;\n    r.interimResults = true;\n    r.lang = \"en-NG\";\n    r.onstart = () => setState(\"recording\");\n    r.onresult = (e: any) => {\n      let interim = \"\", final = \"\";\n      for (let i = e.resultIndex; i < e.results.length; i++) {\n        const t = e.results[i][0].transcript;\n        if (e.results[i].isFinal) final += t;\n        else interim += t;\n      }\n      setInterim(interim);\n      if (final) { onTranscript(final); stop(); }\n    };\n    r.onerror = () => stop();\n    r.onend   = () => setState(\"idle\");\n    recogRef.current = r;\n    r.start();\n  }\n\n  function stop() {\n    recogRef.current?.stop();\n    setState(\"idle\");\n    setInterim(\"\");\n  }\n\n  const isRec = state === \"recording\";\n\n  return (\n    <div style={{position:\"relative\",display:\"flex\",alignItems:\"center\",gap:6}}>\n      {/* live transcript bubble */}\n      <AnimatePresence>\n        {isRec && interim && (\n          <motion.div initial={{opacity:0,y:4,scale:.96}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}}\n            style={{position:\"absolute\",bottom:\"calc(100% + 8px)\",right:0,background:T.s1,border:`1px solid ${T.border}`,borderRadius:10,padding:\"7px 12px\",fontSize:12,color:T.text,whiteSpace:\"nowrap\",maxWidth:220,overflow:\"hidden\",textOverflow:\"ellipsis\",boxShadow:T.shadow,zIndex:10}}>\n            <span style={{color:\"rgba(240,236,255,0.5)\",fontSize:10,display:\"block\",marginBottom:2}}>Listening…</span>\n            {interim}\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      {/* recording bars */}\n      {isRec && (\n        <div style={{display:\"flex\",alignItems:\"center\",gap:2}}>\n          {[0,1,2,3,4].map(i=>(\n            <div key={i} style={{width:3,height:14,borderRadius:99,background:ACCENT,animation:`voicePulse 0.6s ease-in-out ${i*0.1}s infinite`}}/>\n          ))}\n        </div>\n      )}\n\n      <button\n        onClick={isRec ? stop : start}\n        title={isRec ? \"Stop recording\" : \"Voice input\"}\n        style={{width:30,height:30,borderRadius:8,border:`1px solid ${isRec?\"#EF4444\":T.border}`,background:isRec?\"rgba(239,68,68,0.1)\":\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,transition:\"all 0.2s\"}}>\n        {isRec\n          ? <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"#EF4444\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/></svg>\n          : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={T.sub} strokeWidth=\"2\" strokeLinecap=\"round\">\n              <path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"/>\n              <path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/>\n              <line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"/>\n              <line x1=\"8\"  y1=\"23\" x2=\"16\" y2=\"23\"/>\n            </svg>\n        }\n      </button>\n    </div>\n  );\n}\n\n// ── Auth dropdown ──────────────────────────────────────────────\nfunction AuthDropdown({ T, onLogin, onLoggedOut }: { T:typeof TL; onLogin:()=>void; onLoggedOut:()=>void }) {\n  const { user, logout } = useAuthStore();\n  const [open, setOpen]  = useState(false);\n  const ref = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };\n    document.addEventListener(\"mousedown\", h);\n    return () => document.removeEventListener(\"mousedown\", h);\n  }, []);\n\n  async function handleLogout() {\n    setOpen(false);\n    try { await logout(); } catch {}\n    [\"kiro_sid\",\"accessToken\",\"dropos-refresh-token\"].forEach(k => localStorage.removeItem(k));\n    onLoggedOut(); // <-- returns to guest view\n  }\n\n  if (!user) {\n    return (\n      <button onClick={onLogin}\n        style={{padding:\"6px 16px\",borderRadius:8,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:13,fontWeight:600,cursor:\"pointer\",fontFamily:\"inherit\",whiteSpace:\"nowrap\",boxShadow:`0 2px 10px ${ACCENT}30`}}>\n        Get started free\n      </button>\n    );\n  }\n\n  const initials = (user.name||user.email||\"U\").slice(0,2).toUpperCase();\n  const first    = user.name?.split(\" \")[0] || user.email?.split(\"@\")[0] || \"User\";\n\n  return (\n    <div ref={ref} style={{position:\"relative\",flexShrink:0}}>\n      <button onClick={() => setOpen(o=>!o)}\n        style={{display:\"flex\",alignItems:\"center\",gap:7,padding:\"4px 10px 4px 4px\",borderRadius:9,border:`1px solid ${T.border}`,background:T.s2,cursor:\"pointer\",fontFamily:\"inherit\",flexShrink:0,transition:\"border-color .15s\"}}\n        onMouseEnter={e=>(e.currentTarget.style.borderColor=T.border)}\n        onMouseLeave={e=>(e.currentTarget.style.borderColor=T.border)}>\n        <div style={{width:28,height:28,borderRadius:8,background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:11,fontWeight:800,color:\"#fff\",flexShrink:0}}>{initials}</div>\n        <span style={{fontSize:12,fontWeight:600,color:T.text,maxWidth:72,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\"}}>{first}</span>\n        <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={\"rgba(240,236,255,0.5)\"} strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg>\n      </button>\n\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{opacity:0,y:5,scale:.96}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:4,scale:.96}} transition={{duration:.13}}\n            style={{position:\"absolute\",right:0,top:\"calc(100% + 7px)\",minWidth:185,borderRadius:13,background:T.s1,border:`1px solid ${T.border}`,boxShadow:T.shadow,overflow:\"hidden\",zIndex:300}}>\n            <div style={{padding:\"11px 14px\",borderBottom:`1px solid ${T.border}`}}>\n              <p style={{fontSize:12,fontWeight:700,color:T.text}}>{user.name||\"User\"}</p>\n              <p style={{fontSize:11,color:\"rgba(240,236,255,0.5)\",marginTop:1}}>{user.email}</p>\n            </div>\n            <Link href=\"/dashboard\" style={{textDecoration:\"none\"}}>\n              <button style={{width:\"100%\",padding:\"10px 14px\",display:\"flex\",alignItems:\"center\",gap:9,background:\"none\",border:\"none\",cursor:\"pointer\",textAlign:\"left\",fontFamily:\"inherit\",transition:\"background .12s\"}}\n                onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n                onMouseLeave={e=>(e.currentTarget.style.background=\"none\")}>\n                <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={T.accent} strokeWidth=\"2\" strokeLinecap=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/></svg>\n                <span style={{fontSize:13,fontWeight:600,color:T.text}}>Dashboard</span>\n              </button>\n            </Link>\n            <button onClick={handleLogout}\n              style={{width:\"100%\",padding:\"10px 14px\",display:\"flex\",alignItems:\"center\",gap:9,background:\"none\",border:\"none\",borderTop:`1px solid ${T.border}`,cursor:\"pointer\",textAlign:\"left\",fontFamily:\"inherit\",transition:\"background .12s\"}}\n              onMouseEnter={e=>(e.currentTarget.style.background=\"rgba(220,38,38,.07)\")}\n              onMouseLeave={e=>(e.currentTarget.style.background=\"none\")}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\n              <span style={{fontSize:13,fontWeight:600,color:\"#DC2626\"}}>Log out</span>\n            </button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}\n\n// ── History item with context menu ──────────────────────────────\nfunction HistoryItem({ s, activeId, onSelect, onDelete, onRename, onPin, T }:\n  { s:Session; activeId:string; onSelect:(id:string)=>void; onDelete:(id:string)=>void; onRename:(id:string,title:string)=>void; onPin:(id:string)=>void; T:typeof TL }) {\n  const [menu, setMenu] = useState(false);\n  const [editing, setEditing] = useState(false);\n  const [editVal, setEditVal] = useState(s.title||\"New conversation\");\n  const [hover, setHover] = useState(false);\n  const menuRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    const h = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenu(false); };\n    if (menu) document.addEventListener(\"mousedown\", h);\n    return () => document.removeEventListener(\"mousedown\", h);\n  }, [menu]);\n\n  function commitRename() {\n    const v = editVal.trim();\n    if (v && v !== s.title) onRename(s.id, v);\n    setEditing(false);\n  }\n\n  return (\n    <div\n      onClick={() => !editing && onSelect(s.id)}\n      style={{display:\"flex\",alignItems:\"center\",gap:7,padding:\"7px 10px\",borderRadius:9,marginBottom:2,background:s.id===activeId?T.accentBg:hover?T.s2:\"transparent\",cursor:\"pointer\",transition:\"background .14s\",position:\"relative\"}}\n      onMouseEnter={() => setHover(true)}\n      onMouseLeave={() => setHover(false)}>\n\n      {/* Pin indicator */}\n      {s.pinned && <svg width=\"8\" height=\"8\" viewBox=\"0 0 24 24\" fill={T.accent} style={{flexShrink:0}}><path d=\"M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6z\"/></svg>}\n\n      {/* Icon */}\n      <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={s.id===activeId?T.accent:\"rgba(240,236,255,0.5)\"} strokeWidth=\"2\" strokeLinecap=\"round\" style={{flexShrink:0}}>\n        <path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/>\n      </svg>\n\n      {/* Title / edit input */}\n      <div style={{flex:1,minWidth:0}}>\n        {editing ? (\n          <input autoFocus value={editVal} onChange={e=>setEditVal(e.target.value)}\n            onBlur={commitRename} onKeyDown={e=>{if(e.key===\"Enter\")commitRename();if(e.key===\"Escape\")setEditing(false);}}\n            onClick={e=>e.stopPropagation()}\n            style={{width:\"100%\",fontSize:12,fontWeight:600,color:T.text,background:T.s3,border:`1px solid ${T.accent}`,borderRadius:5,padding:\"2px 6px\",outline:\"none\",fontFamily:\"inherit\"}}/>\n        ) : (\n          <>\n            <p style={{fontSize:12,fontWeight:600,color:s.id===activeId?T.accent:T.text,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\"}}>{s.title||\"New conversation\"}</p>\n            <p style={{fontSize:10,color:\"rgba(240,236,255,0.5)\",marginTop:1}}>{timeAgo(s.ts)}</p>\n          </>\n        )}\n      </div>\n\n      {/* Context menu trigger */}\n      <button onClick={e=>{e.stopPropagation();setMenu(m=>!m);}}\n        style={{flexShrink:0,width:20,height:20,borderRadius:5,border:\"none\",background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",color:\"rgba(240,236,255,0.5)\",opacity:menu||hover?1:0,transition:\"opacity .15s\"}}>\n        <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><circle cx=\"5\" cy=\"12\" r=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/><circle cx=\"19\" cy=\"12\" r=\"2\"/></svg>\n      </button>\n\n      {/* Dropdown menu */}\n      {menu && (\n        <div ref={menuRef} onClick={e=>e.stopPropagation()}\n          style={{position:\"absolute\",right:8,top:\"100%\",zIndex:200,background:T.s1,border:`1px solid ${T.border}`,borderRadius:10,boxShadow:T.shadow,minWidth:140,overflow:\"hidden\",marginTop:4}}>\n          {[\n            { label: s.pinned?\"Unpin\":\"Pin to top\", icon:\"M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6z\", action:()=>{onPin(s.id);setMenu(false);}, fill:true },\n            { label:\"Rename\", icon:\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\", action:()=>{setEditVal(s.title||\"New conversation\");setEditing(true);setMenu(false);}, fill:false },\n            { label:\"Delete\", icon:\"M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6\", action:()=>{onDelete(s.id);setMenu(false);}, fill:false, danger:true },\n          ].map(item => (\n            <button key={item.label} onClick={item.action}\n              style={{width:\"100%\",padding:\"9px 14px\",border:\"none\",background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",gap:9,fontSize:12,fontWeight:500,color:item.danger?\"#EF4444\":T.text,fontFamily:\"inherit\",textAlign:\"left\"}}\n              onMouseEnter={e=>(e.currentTarget.style.background=T.s2)}\n              onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill={item.fill?\"currentColor\":\"none\"} stroke={item.fill?\"none\":\"currentColor\"} strokeWidth=\"2\" strokeLinecap=\"round\" color={item.danger?\"#EF4444\":\"rgba(240,236,255,0.5)\"}>\n                <path d={item.icon}/>\n              </svg>\n              {item.label}\n            </button>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n// chat menu visibility handled via inline opacity\n// ── History sidebar ────────────────────────────────────────────\nfunction Sidebar({ history, activeId, onSelect, onNew, onDelete, onRename, onPin, open, onClose, T }:\n  { history:Session[]; activeId:string; onSelect:(id:string)=>void; onNew:()=>void; onDelete:(id:string)=>void; onRename:(id:string,title:string)=>void; onPin:(id:string)=>void; open:boolean; onClose:()=>void; T:typeof TL }) {\n  return (\n    <>\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}\n            style={{position:\"fixed\",inset:0,background:\"rgba(0,0,0,0.3)\",zIndex:90,backdropFilter:\"blur(2px)\"}}\n            onClick={onClose}/>\n        )}\n      </AnimatePresence>\n      <motion.div animate={{x:open?0:-280}} initial={{x:-280}} transition={{type:\"spring\",stiffness:340,damping:34}}\n        style={{position:\"fixed\",left:0,top:0,bottom:0,width:260,background:T.s1,borderRight:`1px solid ${T.border}`,zIndex:100,display:\"flex\",flexDirection:\"column\",boxShadow:T.shadow}}>\n\n        <div style={{padding:\"13px 14px\",borderBottom:`1px solid ${T.border}`,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",flexShrink:0}}>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:8}}><Logo size={22}/><span style={{fontSize:13,fontWeight:700,color:T.text}}>Chat history</span></div>\n          <button onClick={onClose}\n            style={{width:26,height:26,borderRadius:6,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",color:\"rgba(240,236,255,0.5)\"}}\n            onMouseEnter={e=>(e.currentTarget.style.background=T.s2)} onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n            <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n          </button>\n        </div>\n\n        <div style={{padding:\"10px 10px 6px\",flexShrink:0}}>\n          <button onClick={onNew}\n            style={{width:\"100%\",padding:\"8px 0\",borderRadius:9,border:`1.5px dashed ${T.border}`,background:T.accentBg,color:T.accent,fontWeight:600,fontSize:12,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",gap:7,justifyContent:\"center\",fontFamily:\"inherit\",transition:\"opacity .15s\"}}\n            onMouseEnter={e=>(e.currentTarget.style.opacity=\"0.75\")} onMouseLeave={e=>(e.currentTarget.style.opacity=\"1\")}>\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>\n            New chat\n          </button>\n        </div>\n\n        <div style={{flex:1,overflowY:\"auto\",padding:\"4px 8px 16px\"}}>\n          {history.length===0 && (\n            <div style={{textAlign:\"center\",marginTop:32,padding:\"0 12px\"}}>\n              <div style={{fontSize:24,marginBottom:8}}>💬</div>\n              <p style={{fontSize:12,color:\"rgba(240,236,255,0.5)\",lineHeight:1.7}}>No chats yet.<br/>Start a conversation<br/>and it'll appear here.</p>\n            </div>\n          )}\n          {[...history].sort((a,b) => (b.pinned?1:0)-(a.pinned?1:0)).map(s => (\n            <HistoryItem key={s.id} s={s} activeId={activeId} onSelect={onSelect} onDelete={onDelete} onRename={onRename} onPin={onPin} T={T}/>\n          ))}\n        </div>\n      </motion.div>\n    </>\n  );\n}\n\n// ── Auth modal ─────────────────────────────────────────────────\nfunction AuthModal({ onClose, onSuccess, T }: { onClose:()=>void; onSuccess:(sid:string)=>void; T:typeof TL }) {\n  const [tab, setTab]   = useState<\"register\"|\"login\">(\"register\");\n  const [name, setName] = useState(\"\"); const [email, setEmail] = useState(\"\"); const [pass, setPass] = useState(\"\");\n  const [err, setErr]   = useState(\"\"); const [busy, setBusy]   = useState(false);\n  const inp: React.CSSProperties = { width:\"100%\",padding:\"10px 14px\",borderRadius:9,border:`1px solid ${T.border}`,background:T.s2,color:T.text,fontSize:14,fontFamily:\"'Inter',sans-serif\",outline:\"none\",transition:\"border-color 0.15s,box-shadow 0.15s\" };\n  const focus = (e: React.FocusEvent<HTMLInputElement>) => { e.currentTarget.style.borderColor=ACCENT; e.currentTarget.style.boxShadow=`0 0 0 3px ${ACCENT}15`; };\n  const blur  = (e: React.FocusEvent<HTMLInputElement>, T: typeof TL) => { e.currentTarget.style.borderColor=T.border; e.currentTarget.style.boxShadow=\"none\"; };\n\n  async function submit() {\n    if (!email||!pass) return; setBusy(true); setErr(\"\");\n    try {\n      const body = tab===\"register\" ? {name,email,password:pass} : {email,password:pass};\n      const res  = await fetch(`${BASE}/auth/${tab}`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)});\n      const d    = await res.json();\n      if (!res.ok) { setErr(d.message||\"Something went wrong\"); setBusy(false); return; }\n      const { accessToken, refreshToken:rt, user } = d.data||{};\n      if (rt) localStorage.setItem(\"dropos-refresh-token\", rt);\n      if (accessToken) {\n        try {\n          const { useAuthStore } = await import(\"../../../store/auth.store\");\n          useAuthStore.getState().setUser(user);\n          useAuthStore.getState().setAccessToken(accessToken);\n        } catch {}\n        onSuccess(user?.stores?.[0]?.id||\"\");\n      }\n    } catch { setErr(\"Connection error\"); } finally { setBusy(false); }\n  }\n\n  return (\n    <div style={{position:\"fixed\",inset:0,zIndex:500,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",padding:16,background:\"rgba(0,0,0,0.45)\",backdropFilter:\"blur(10px)\"}}\n      onClick={e=>e.target===e.currentTarget&&onClose()}>\n      <motion.div initial={{opacity:0,y:10,scale:.97}} animate={{opacity:1,y:0,scale:1}} transition={{type:\"spring\",stiffness:320,damping:28}}\n        style={{width:\"100%\",maxWidth:350,borderRadius:18,background:T.s1,border:`1px solid ${T.border}`,padding:\"26px 22px\",boxShadow:T.shadow}}>\n        <div style={{textAlign:\"center\",marginBottom:20}}>\n          <div style={{display:\"flex\",justifyContent:\"center\",marginBottom:12}}><Logo size={38}/></div>\n          <h2 style={{fontSize:19,fontWeight:700,color:T.text,margin:\"0 0 4px\",letterSpacing:\"-0.3px\"}}>{tab===\"register\"?\"Create account\":\"Welcome back\"}</h2>\n          <p style={{fontSize:12,color:\"rgba(240,236,255,0.5)\"}}>{tab===\"register\"?\"Free · No card needed\":\"Sign in to KIRO\"}</p>\n        </div>\n        <div style={{display:\"flex\",gap:2,padding:3,borderRadius:9,background:T.s2,marginBottom:16}}>\n          {([\"register\",\"login\"] as const).map(m=>(\n            <button key={m} onClick={()=>{setTab(m);setErr(\"\");}}\n              style={{flex:1,padding:\"6px\",borderRadius:7,border:\"none\",cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",fontSize:12,fontWeight:500,transition:\"all 0.15s\",background:tab===m?T.s1:\"transparent\",color:tab===m?T.text:\"rgba(240,236,255,0.5)\",boxShadow:tab===m?T.shadow:\"none\"}}>\n              {m===\"register\"?\"Sign up\":\"Sign in\"}\n            </button>\n          ))}\n        </div>\n        <div style={{display:\"flex\",flexDirection:\"column\",gap:9}}>\n          {tab===\"register\"&&<input value={name} onChange={e=>setName(e.target.value)} placeholder=\"Full name\" autoFocus style={inp} onFocus={focus} onBlur={e=>blur(e,T)}/>}\n          <input value={email} onChange={e=>setEmail(e.target.value)} placeholder=\"Email\" type=\"email\" autoFocus={tab===\"login\"} style={inp} onFocus={focus} onBlur={e=>blur(e,T)}/>\n          <input value={pass}  onChange={e=>setPass(e.target.value)}  placeholder=\"Password\" type=\"password\" style={inp} onFocus={focus} onBlur={e=>blur(e,T)} onKeyDown={e=>e.key===\"Enter\"&&submit()}/>\n          {err && <p style={{fontSize:12,color:\"#DC2626\",textAlign:\"center\",margin:0}}>{err}</p>}\n          <button onClick={submit} disabled={busy||!email||!pass}\n            style={{padding:\"11px\",borderRadius:9,border:\"none\",cursor:busy||!email||!pass?\"not-allowed\":\"pointer\",fontFamily:\"'Inter',sans-serif\",fontSize:14,fontWeight:600,marginTop:2,background:busy||!email||!pass?T.s3:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:busy||!email||!pass?\"rgba(240,236,255,0.5)\":\"#fff\",transition:\"all 0.2s\",boxShadow:!busy&&email&&pass?`0 4px 14px ${ACCENT}30`:\"none\"}}>\n            {busy?\"…\":tab===\"register\"?\"Create account →\":\"Sign in →\"}\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\n// ── Demo chat (guest) ──────────────────────────────────────────\ntype Msg = { id:string; role:\"user\"|\"ai\"; text:string; streaming?:boolean };\nconst STARTERS = [\"What can KIRO do?\",\"I sell fashion in Lagos\",\"Find trending products\",\"How to import from AliExpress?\"];\n\nfunction DemoChat({ T, onAuthNeeded }: { T:typeof TL; onAuthNeeded:()=>void }) {\n  const [msgs,    setMsgs]    = useState<Msg[]>([{id:\"0\",role:\"ai\",text:\"I'm KIRO — your AI business partner. I help African dropshippers source products, write ads, fulfill orders, and understand their market. What do you sell?\"}]);\n  const [input,   setInput]   = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [count,   setCount]   = useState(0);\n  const endRef = useRef<HTMLDivElement>(null);\n  const taRef  = useRef<HTMLTextAreaElement>(null);\n\n  useEffect(() => { endRef.current?.scrollIntoView({behavior:\"smooth\"}); }, [msgs]);\n\n  const send = useCallback(async (text?: string) => {\n    const msg = (text||input).trim(); if (!msg||loading) return;\n    setInput(\"\"); if (taRef.current) taRef.current.style.height=\"auto\";\n    const n = count+1; setCount(n);\n    if (n>=5) { setMsgs(p=>[...p,{id:`u${Date.now()}`,role:\"user\",text:msg}]); setTimeout(onAuthNeeded,200); return; }\n    const kid = `k${Date.now()}`;\n    setMsgs(p=>[...p,{id:`u${Date.now()}`,role:\"user\",text:msg},{id:kid,role:\"ai\",text:\"\",streaming:true}]);\n    setLoading(true);\n    try {\n      const res = await fetch(`${BASE}/kai/public-chat`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({message:msg})});\n      if (!res.ok||!res.body) throw new Error();\n      const reader = res.body.getReader(); const dec = new TextDecoder(); let full=\"\";\n      while (true) {\n        const {done,value}=await reader.read(); if (done) break;\n        for (const line of dec.decode(value,{stream:true}).split(\"\\n\")) {\n          if (!line.startsWith(\"data: \")) continue;\n          try { const p=JSON.parse(line.slice(6)); if(p.token){full+=p.token;setMsgs(m=>m.map(x=>x.id===kid?{...x,text:full}:x));endRef.current?.scrollIntoView({behavior:\"smooth\"});} } catch {}\n        }\n      }\n      setMsgs(m=>m.map(x=>x.id===kid?{...x,streaming:false,text:full||\"Create a free account to unlock the full KIRO experience.\"}:x));\n    } catch {\n      setMsgs(m=>m.map(x=>x.id===kid?{...x,streaming:false,text:\"Create a free account to get started with KIRO.\"}:x));\n    } finally { setLoading(false); }\n  }, [input,loading,count,onAuthNeeded]);\n\n  return (\n    <div style={{display:\"flex\",flexDirection:\"column\",height:\"100%\",minHeight:0}}>\n      <div style={{flex:1,overflowY:\"auto\",padding:\"16px 16px 8px\",minHeight:0}}>\n        {msgs.map(msg=>(\n          <motion.div key={msg.id} initial={{opacity:0,y:5}} animate={{opacity:1,y:0}} transition={{duration:0.2}}\n            style={{display:\"flex\",flexDirection:msg.role===\"user\"?\"row-reverse\":\"row\",gap:7,alignItems:\"flex-end\",marginBottom:12}}>\n            {msg.role===\"ai\"&&<Logo size={22}/>}\n            <div style={{maxWidth:\"82%\",padding:msg.role===\"user\"?\"9px 14px\":\"0\",borderRadius:msg.role===\"user\"?\"16px 16px 4px 16px\":\"0\",background:msg.role===\"user\"?`linear-gradient(145deg,${ACCENT},${ACCENT_D})`:\"transparent\",color:msg.role===\"user\"?\"#fff\":T.text,fontSize:14,lineHeight:1.68,boxShadow:msg.role===\"user\"?`0 2px 8px ${ACCENT}28`:\"none\"}}>\n              {msg.streaming&&!msg.text\n                ? <div style={{display:\"flex\",gap:4,padding:\"3px 0\"}}>{[0,1,2].map(i=><motion.div key={i} style={{width:5,height:5,borderRadius:\"50%\",background:\"rgba(240,236,255,0.5)\"}} animate={{y:[0,-4,0],opacity:[0.4,1,0.4]}} transition={{duration:0.6,repeat:Infinity,delay:i*0.12}}/>)}</div>\n                : <span>{msg.text}{msg.streaming&&<motion.span animate={{opacity:[1,0]}} transition={{duration:0.5,repeat:Infinity}} style={{display:\"inline-block\",width:2,height:13,background:\"rgba(240,236,255,0.5)\",marginLeft:1,verticalAlign:\"text-bottom\"}}/>}</span>\n              }\n            </div>\n          </motion.div>\n        ))}\n        {count>=2&&(\n          <motion.div initial={{opacity:0,y:6}} animate={{opacity:1,y:0}}\n            style={{margin:\"4px 0 10px\",padding:\"12px 14px\",borderRadius:11,background:T.accentBg,border:`1px solid ${T.border}`}}>\n            <p style={{fontSize:13,fontWeight:600,color:T.text,margin:\"0 0 3px\"}}>KIRO is better with your store</p>\n            <p style={{fontSize:12,color:\"rgba(240,236,255,0.5)\",margin:\"0 0 8px\"}}>Free account unlocks full product import, analytics, and AI actions.</p>\n            <button onClick={onAuthNeeded} style={{padding:\"6px 14px\",borderRadius:7,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:12,fontWeight:600,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\"}}>Start free →</button>\n          </motion.div>\n        )}\n        <div ref={endRef}/>\n      </div>\n      {msgs.length<=1&&(\n        <div style={{padding:\"0 16px 8px\",display:\"flex\",gap:6,flexWrap:\"wrap\"}}>\n          {STARTERS.map(s=>(\n            <button key={s} onClick={()=>send(s)}\n              style={{padding:\"5px 11px\",borderRadius:99,border:`1px solid ${T.border}`,background:\"transparent\",color:T.sub,fontSize:12,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",transition:\"all 0.15s\",whiteSpace:\"nowrap\"}}\n              onMouseEnter={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.text;}}\n              onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.sub;}}>\n              {s}\n            </button>\n          ))}\n        </div>\n      )}\n      <div style={{padding:\"8px 14px 14px\",flexShrink:0}}>\n        <div style={{display:\"flex\",gap:8,alignItems:\"flex-end\",borderRadius:12,border:`1px solid ${T.border}`,background:T.s1,padding:\"7px 9px\",boxShadow:T.shadow,transition:\"border-color 0.15s\"}}\n          onFocusCapture={e=>(e.currentTarget as HTMLDivElement).style.borderColor=ACCENT}\n          onBlurCapture={e=>(e.currentTarget as HTMLDivElement).style.borderColor=T.border}>\n          <textarea ref={taRef} value={input}\n            onChange={e=>{setInput(e.target.value);e.target.style.height=\"auto\";e.target.style.height=Math.min(e.target.scrollHeight,90)+\"px\";}}\n            onKeyDown={e=>{if(e.key===\"Enter\"&&!e.shiftKey){e.preventDefault();send();}}}\n            placeholder=\"Ask KIRO anything…\" rows={1}\n            style={{flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:T.text,fontSize:14,fontFamily:\"'Inter',sans-serif\",lineHeight:1.5,resize:\"none\",maxHeight:90,overflowY:\"auto\",padding:\"2px 0\"}}/>\n          <VoiceBtn T={T} onTranscript={t=>{setInput(p=>p?p+\" \"+t:t);}}/>\n          <motion.button onClick={()=>send()} whileTap={{scale:.88}} disabled={loading||!input.trim()}\n            style={{width:28,height:28,borderRadius:8,border:\"none\",cursor:input.trim()&&!loading?\"pointer\":\"not-allowed\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,transition:\"all 0.18s\",background:input.trim()&&!loading?`linear-gradient(135deg,${ACCENT},${ACCENT_D})`:T.s3,opacity:input.trim()&&!loading?1:0.45}}>\n            {loading\n              ? <div style={{width:11,height:11,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.7s linear infinite\"}}/>\n              : <svg width={11} height={11} viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z\" stroke=\"white\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>\n            }\n          </motion.button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// ── Auto-login helper ──────────────────────────────────────────\nasync function tryAutoLogin() {\n  if (typeof window===\"undefined\") return null;\n  const r = localStorage.getItem(\"dropos-refresh-token\"); if (!r) return null;\n  try {\n    const res = await fetch(`${BASE}/auth/refresh`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({refreshToken:r})});\n    if (!res.ok) return null;\n    const {data} = await res.json(); if (!data?.accessToken) return null;\n    if (data.refreshToken) localStorage.setItem(\"dropos-refresh-token\", data.refreshToken);\n    try {\n      const {useAuthStore} = await import(\"../../../store/auth.store\");\n      useAuthStore.getState().setUser(data.user);\n      useAuthStore.getState().setAccessToken(data.accessToken);\n    } catch {}\n    return { storeId: data.user?.stores?.[0]?.id||\"\" };\n  } catch { return null; }\n}\n\nconst CAPS = [\n  {icon:\"🌐\",text:\"Import from any website\"},\n  {icon:\"📊\",text:\"Live store analytics\"},\n  {icon:\"⚡\",text:\"Actions from chat\"},\n  {icon:\"intel\",text:\"Market intelligence\"},\n  {icon:\"📣\",text:\"AI ad copy\"},\n  {icon:\"goals\",text:\"Goals & pulse alerts\"},\n];\n\n// ── Main ───────────────────────────────────────────────────────\nexport default function KIROPage() {\n  const { user } = useAuthStore();\n  const [authState, setAuthState] = useState<\"checking\"|\"authed\"|\"guest\">(\"checking\");\n  const [storeId,   setStoreId]   = useState(\"\");\n  const [showAuth,  setShowAuth]  = useState(false);\n  const [history,   setHistory]   = useState<Session[]>([]);\n  const [sessionId, setSessionId] = useState(\"\");\n  const [sidebarOpen, setSidebarOpen] = useState(false);\n  const firstMsgRef = useRef<string>(\"\");\n  // KIRO is always light mode — inherits auth page color system\n  const T = TL;\n\n  // History helpers\n  const getToken = () => {\n    try {\n      const { useAuthStore: store } = require(\"../../../store/auth.store\");\n      return store.getState().accessToken || \"\";\n    } catch { return \"\"; }\n  };\n\n  const refreshHist = useCallback(async () => {\n    const token = getToken();\n    if (token && authState === \"authed\") {\n      const sessions = await dbLoadHist(token);\n      setHistory(sessions);\n    } else {\n      setHistory(loadHist());\n    }\n  }, [authState]);\n  const newSession  = useCallback(() => {\n    const id = genId();\n    setSessionId(id);\n    setSidebarOpen(false);\n    refreshHist();\n  }, [refreshHist]);\n  const pickSession = useCallback((id: string) => {\n    setSessionId(id);\n    setSidebarOpen(false);\n  }, []);\n  const removeSession = useCallback(async (id: string) => {\n    const token = getToken();\n    if (token && authState === \"authed\") {\n      await dbDeleteHist(id, token);\n    } else {\n      delHist(id);\n    }\n    refreshHist();\n    if (id===sessionId) newSession();\n  }, [sessionId, newSession, refreshHist]);\n\n  const renameSession = useCallback(async (id: string, title: string) => {\n    const token = getToken();\n    if (token && authState === \"authed\") {\n      await dbRenameHist(id, title, token);\n    } else {\n      const h = loadHist().map((s: Session) => s.id === id ? { ...s, title } : s);\n      localStorage.setItem(\"kiro_hist\", JSON.stringify(h));\n    }\n    refreshHist();\n  }, [refreshHist, authState]);\n\n  const pinSession = useCallback(async (id: string) => {\n    const token = getToken();\n    const current = history.find(s => s.id === id);\n    const newPinned = !current?.pinned;\n    if (token && authState === \"authed\") {\n      await dbPinHist(id, newPinned, token);\n    } else {\n      const h = loadHist().map((s: Session) => s.id === id ? { ...s, pinned: newPinned } : s);\n      localStorage.setItem(\"kiro_hist\", JSON.stringify(h));\n    }\n    refreshHist();\n  }, [refreshHist, authState, history]);\n\n  // Re-load history from DB once authed\n  useEffect(() => {\n    if (authState === \"authed\") refreshHist();\n  }, [authState]);\n  const recordChat = useCallback((firstMsg: string) => {\n    if (sessionId) { pushHist(sessionId, firstMsg); refreshHist(); }\n  }, [sessionId, refreshHist]);\n\n  useEffect(() => {\n    const id = genId(); setSessionId(id);\n    refreshHist();\n    tryAutoLogin().then(r => {\n      if (r) { setStoreId(r.storeId); setAuthState(\"authed\"); }\n      else setAuthState(\"guest\");\n    });\n  }, []);\n\n  // ── Logged in: auth success\n  const handleAuth = (sid: string) => {\n    setStoreId(sid); setAuthState(\"authed\"); setShowAuth(false);\n    const id = genId(); setSessionId(id); refreshHist();\n  };\n\n  // ── Logout: go back to guest\n  const handleLogout = () => {\n    setAuthState(\"guest\");\n    setSessionId(genId());\n    setSidebarOpen(false);\n  };\n\n  // ── Checking splash\n  if (authState===\"checking\") return (\n    <div style={{height:\"100dvh\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",background:TL.bg}}>\n      <style>{FONTS}</style>\n      <div style={{width:26,height:26,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.8s linear infinite\"}}/>\n    </div>\n  );\n\n  // ── Authed: full chat\n  if (authState===\"authed\") return (\n    <div style={{height:\"100dvh\",display:\"flex\",flexDirection:\"column\",background:T.s2,overflow:\"hidden\",fontFamily:\"'Inter',sans-serif\"}}>\n      <style>{FONTS+`body,html{background:${T.s2}}`}</style>\n\n      <Sidebar\n        history={history} activeId={sessionId}\n        onSelect={pickSession} onNew={newSession} onDelete={removeSession}\n        onRename={renameSession} onPin={pinSession}\n        open={sidebarOpen} onClose={()=>setSidebarOpen(false)} T={T}/>\n\n      <header style={{height:48,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"0 16px\",borderBottom:`1px solid ${T.border}`,background:T.s1,flexShrink:0,boxShadow:T.shadow,gap:10}}>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:8,minWidth:0}}>\n          <button onClick={()=>setSidebarOpen(o=>!o)}\n            style={{width:30,height:30,borderRadius:7,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",color:T.sub,flexShrink:0,transition:\"background .15s\"}}\n            onMouseEnter={e=>(e.currentTarget.style.background=T.s2)}\n            onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M3 12h18M3 6h18M3 18h18\"/></svg>\n          </button>\n          <Logo size={24}/>\n          <span style={{fontSize:14,fontWeight:700,color:T.text,flexShrink:0}}>KIRO</span>\n          <PulseDot/>\n          {/* current session title */}\n          {history.find(h=>h.id===sessionId) && (\n            <span style={{fontSize:11,color:\"rgba(240,236,255,0.5)\",overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\",maxWidth:160}}>\n              {history.find(h=>h.id===sessionId)?.title}\n            </span>\n          )}\n        </div>\n        <div style={{display:\"flex\",gap:8,alignItems:\"center\",flexShrink:0}}>\n          <AuthDropdown T={T} onLogin={()=>setShowAuth(true)} onLoggedOut={handleLogout}/>\n        </div>\n      </header>\n\n      {/* key={sessionId} forces full remount on new chat */}\n      <div style={{flex:1,overflow:\"hidden\",minHeight:0}} key={sessionId}>\n        <KIROChatFull\n          storeId={storeId}\n          conversationId={history.find(h=>h.id===sessionId)?.id === sessionId && sessionId.length > 8 ? sessionId : undefined}\n          onFirstMessage={(text) => { firstMsgRef.current = text; }}\n          onConversationCreated={(convId) => {\n            const title = firstMsgRef.current || \"KIRO conversation\";\n            pushHist(convId, title);\n            setSessionId(convId);\n            refreshHist();\n          }}\n        />\n      </div>\n\n      {showAuth && <AuthModal T={T} onClose={()=>setShowAuth(false)} onSuccess={handleAuth}/>}\n    </div>\n  );\n\n  // ── Guest: marketing + demo\n  return (\n    <div style={{height:\"100dvh\",display:\"flex\",flexDirection:\"column\",background:T.s2,overflow:\"hidden\",fontFamily:\"'Inter',sans-serif\",transition:\"background 0.25s\"}}>\n      <style>{FONTS+`body,html{background:${T.s2}}`}</style>\n      {showAuth && <AuthModal T={T} onClose={()=>setShowAuth(false)} onSuccess={handleAuth}/>}\n\n      <nav style={{height:52,display:\"flex\",alignItems:\"center\",padding:\"0 20px\",borderBottom:`1px solid ${T.border}`,background:T.s1,flexShrink:0,boxShadow:T.shadow,gap:8}}>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:8,flex:1,minWidth:0}}>\n          <Logo size={26}/>\n          <span style={{fontSize:15,fontWeight:700,color:T.text,flexShrink:0}}>KIRO</span>\n          <span style={{fontSize:9,padding:\"2px 6px\",borderRadius:4,background:T.accentBg,color:T.accent,fontWeight:700,letterSpacing:\"0.07em\",textTransform:\"uppercase\",border:`1px solid ${T.border}`,flexShrink:0}}>Beta</span>\n        </div>\n        <div style={{display:\"flex\",gap:8,alignItems:\"center\",flexShrink:0}}>\n          <button onClick={()=>setShowAuth(true)}\n            style={{padding:\"6px 14px\",borderRadius:8,border:`1px solid ${T.border}`,background:\"transparent\",color:T.sub,fontSize:13,fontWeight:500,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",transition:\"all 0.15s\",whiteSpace:\"nowrap\"}}\n            onMouseEnter={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.text;}}\n            onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.sub;}}>Sign in</button>\n          <button onClick={()=>setShowAuth(true)}\n            style={{padding:\"6px 16px\",borderRadius:8,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:13,fontWeight:600,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",whiteSpace:\"nowrap\",boxShadow:`0 2px 10px ${ACCENT}30`}}>\n            Get started free\n          </button>\n        </div>\n      </nav>\n\n      <div style={{flex:1,display:\"grid\",gridTemplateColumns:\"360px 1fr\",minHeight:0,overflow:\"hidden\"}} className=\"kiro-grid\">\n        <div style={{borderRight:`1px solid ${T.border}`,display:\"flex\",flexDirection:\"column\",justifyContent:\"space-between\",padding:\"32px 24px\",overflow:\"hidden\"}} className=\"kiro-left\">\n          <div>\n            <motion.div initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} transition={{delay:.05}}>\n              <p style={{fontSize:10,fontWeight:700,color:\"rgba(240,236,255,0.5)\",letterSpacing:\"0.1em\",textTransform:\"uppercase\",marginBottom:10}}>For African dropshippers</p>\n              <h1 style={{fontSize:30,fontWeight:700,color:T.text,lineHeight:1.18,letterSpacing:\"-0.5px\",marginBottom:12}}>Your AI<br/>commerce<br/>partner.</h1>\n              <p style={{fontSize:14,color:T.sub,lineHeight:1.7,marginBottom:24,maxWidth:270}}>Import products, write ad copy, manage orders, and understand your market — all from one conversation.</p>\n            </motion.div>\n            <div style={{display:\"flex\",flexDirection:\"column\",gap:6}}>\n              {CAPS.map((c,i)=>(\n                <motion.div key={c.text} initial={{opacity:0,x:-8}} animate={{opacity:1,x:0}} transition={{delay:.15+i*.05}}\n                  style={{display:\"flex\",alignItems:\"center\",gap:9,padding:\"8px 10px\",borderRadius:9,background:T.s1,border:`1px solid ${T.border}`}}>\n                  <span style={{fontSize:14,flexShrink:0}}>{c.icon}</span>\n                  <span style={{fontSize:12,fontWeight:500,color:T.text}}>{c.text}</span>\n                </motion.div>\n              ))}\n            </div>\n          </div>\n          <motion.div initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.5}}\n            style={{padding:\"13px 14px\",borderRadius:11,background:T.s1,border:`1px solid ${T.border}`,marginTop:20}}>\n            <p style={{fontSize:13,color:T.sub,lineHeight:1.6,fontStyle:\"italic\",marginBottom:6}}>\"KIRO found me 3 winning products and wrote all my TikTok scripts. First ₦100k month done.\"</p>\n            <p style={{fontSize:11,color:\"rgba(240,236,255,0.5)\",fontWeight:600}}>Adaeze O. · Lagos, Nigeria</p>\n          </motion.div>\n        </div>\n\n        <div style={{display:\"flex\",flexDirection:\"column\",minHeight:0,overflow:\"hidden\"}}>\n          <div style={{height:42,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"0 18px\",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>\n            <div style={{display:\"flex\",alignItems:\"center\",gap:6}}>\n              <div style={{width:6,height:6,borderRadius:\"50%\",background:T.green,boxShadow:`0 0 6px ${T.green}`}}/>\n              <span style={{fontSize:12,fontWeight:500,color:T.sub}}>Live demo</span>\n            </div>\n            <button onClick={()=>setShowAuth(true)}\n              style={{fontSize:12,fontWeight:600,color:T.accent,background:\"transparent\",border:\"none\",cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",padding:\"3px 8px\",borderRadius:5,transition:\"background 0.15s\"}}\n              onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n              onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n              Get full access →\n            </button>\n          </div>\n          <div style={{flex:1,minHeight:0,overflow:\"hidden\"}}>\n            <DemoChat T={T} onAuthNeeded={()=>setShowAuth(true)}/>\n          </div>\n        </div>\n      </div>\n\n      <style>{`@media(max-width:660px){.kiro-grid{grid-template-columns:1fr!important}.kiro-left{display:none!important}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/auth/login/page.tsx":"\"use client\";\nimport { Suspense, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useForm } from \"react-hook-form\";\nimport { zodResolver } from \"@hookform/resolvers/zod\";\nimport { z } from \"zod\";\nimport { Eye, EyeOff, ArrowRight, Mail, Lock, Check } from \"lucide-react\";\nimport { useLogin } from \"../../../hooks/useAuth\";\nimport { useSearchParams } from \"next/navigation\";\n\nconst schema = z.object({\n  email:    z.string().email(\"Enter a valid email\"),\n  password: z.string().min(1, \"Password required\"),\n});\ntype Form = z.infer<typeof schema>;\n\nfunction GoogleIcon() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\">\n      <path d=\"M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z\" fill=\"#4285F4\"/>\n      <path d=\"M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z\" fill=\"#34A853\"/>\n      <path d=\"M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z\" fill=\"#FBBC05\"/>\n      <path d=\"M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z\" fill=\"#EA4335\"/>\n    </svg>\n  );\n}\n\nfunction LoginInner() {\n  const [show, setShow] = useState(false);\n  const login  = useLogin();\n  const params = useSearchParams();\n  const justRegistered = params.get(\"registered\");\n\n  const { register, handleSubmit, formState: { errors } } = useForm<Form>({\n    resolver: zodResolver(schema),\n  });\n\n  const onSubmit = (data: Form) => login.mutate(data);\n\n  const handleGoogle = () => {\n    const base = process.env.NEXT_PUBLIC_API_URL?.replace(\"/api\", \"\") || \"\";\n    window.location.href = `${base}/api/auth/google`;\n  };\n\n  return (\n    <div style={{ minHeight: \"100vh\", display: \"flex\", background: \"#F4F2FB\", fontFamily: \"'Plus Jakarta Sans', system-ui, -apple-system, sans-serif\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@400;500;600;700;800;900&display=swap');\n        .auth-input { transition: all 0.15s ease; }\n        .auth-input:focus { border-color: #6B35E8 !important; box-shadow: 0 0 0 3px rgba(107,53,232,0.08); outline: none; }\n        .auth-input::placeholder { color: rgba(19,13,46,0.3); }\n        @media (max-width: 768px) {\n          .auth-visual { display: none !important; }\n          .auth-form-pane { width: 100% !important; }\n        }\n      `}</style>\n\n      {/* LEFT — visual panel (hidden on mobile) */}\n      <div className=\"auth-visual\" style={{\n        width: \"44%\",\n        position: \"relative\", overflow: \"hidden\",\n        display: \"flex\", flexDirection: \"column\", justifyContent: \"space-between\",\n        padding: \"48px 56px\",\n        background: \"linear-gradient(160deg, #2D1B69 0%, #1A0B4A 60%, #0D0625 100%)\",\n      }}>\n        {/* Ambient glow */}\n        <div style={{\n          position: \"absolute\", top: \"-200px\", right: \"-150px\",\n          width: 600, height: 600, borderRadius: \"50%\",\n          background: \"radial-gradient(circle, rgba(167,139,250,0.4) 0%, transparent 60%)\",\n          filter: \"blur(80px)\", pointerEvents: \"none\",\n        }}/>\n        <div style={{\n          position: \"absolute\", bottom: \"-100px\", left: \"-50px\",\n          width: 400, height: 400, borderRadius: \"50%\",\n          background: \"radial-gradient(circle, rgba(124,58,237,0.25) 0%, transparent 60%)\",\n          filter: \"blur(60px)\", pointerEvents: \"none\",\n        }}/>\n\n        {/* Logo */}\n        <div style={{ position: \"relative\", zIndex: 1, display: \"flex\", alignItems: \"center\", gap: 12 }}>\n          <div style={{\n            width: 36, height: 36, borderRadius: 10,\n            background: \"rgba(255,255,255,0.95)\",\n            display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n          }}>\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\">\n              <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"#2D1B69\"/>\n            </svg>\n          </div>\n          <span style={{ fontSize: 17, fontWeight: 800, color: \"#fff\", letterSpacing: \"-0.02em\" }}>DropOS</span>\n        </div>\n\n        {/* Hero text */}\n        <div style={{ position: \"relative\", zIndex: 1, maxWidth: 440 }}>\n          <h1 style={{\n            fontFamily: \"'Fraunces', Georgia, serif\",\n            fontSize: 44, fontWeight: 500, letterSpacing: \"-0.03em\",\n            color: \"#fff\", margin: \"0 0 18px\", lineHeight: 1.08,\n          }}>\n            Welcome back to <em style={{ fontStyle: \"italic\", fontWeight: 400, color: \"#C4B5FD\" }}>commerce</em>.\n          </h1>\n          <p style={{ fontSize: 15, lineHeight: 1.55, color: \"rgba(255,255,255,0.65)\", margin: 0, maxWidth: 380 }}>\n            The AI-powered commerce platform built for African merchants.\n            Launch your store. Sell anywhere. Powered by KIRO.\n          </p>\n        </div>\n\n        {/* Footer */}\n        <div style={{ position: \"relative\", zIndex: 1, display: \"flex\", alignItems: \"center\", gap: 24 }}>\n          <span style={{ fontSize: 11, fontWeight: 500, color: \"rgba(255,255,255,0.4)\", letterSpacing: \"0.1em\" }}>\n            © 2026 DROPOS\n          </span>\n          <div style={{ width: 1, height: 12, background: \"rgba(255,255,255,0.15)\" }} />\n          <Link href=\"/privacy\" style={{ fontSize: 11, color: \"rgba(255,255,255,0.4)\", textDecoration: \"none\", letterSpacing: \"0.05em\" }}>\n            Privacy\n          </Link>\n          <Link href=\"/terms\" style={{ fontSize: 11, color: \"rgba(255,255,255,0.4)\", textDecoration: \"none\", letterSpacing: \"0.05em\" }}>\n            Terms\n          </Link>\n        </div>\n      </div>\n\n      {/* RIGHT — form pane */}\n      <div className=\"auth-form-pane\" style={{\n        width: \"56%\",\n        display: \"flex\", flexDirection: \"column\",\n        alignItems: \"center\", justifyContent: \"center\",\n        padding: \"48px 24px\",\n        background: \"#FAFAFC\",\n      }}>\n        <div style={{ width: \"100%\", maxWidth: 380 }}>\n\n          {/* Mobile logo */}\n          <div className=\"lg:hidden\" style={{ display: \"flex\", alignItems: \"center\", gap: 10, marginBottom: 28 }}>\n            <div style={{ width: 32, height: 32, borderRadius: 8, background: \"#2D1B69\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n                <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"#fff\"/>\n              </svg>\n            </div>\n            <span style={{ fontSize: 15, fontWeight: 800, color: \"#130D2E\", letterSpacing: \"-0.02em\" }}>DropOS</span>\n          </div>\n\n          {/* Header */}\n          <h2 style={{\n            fontFamily: \"'Fraunces', Georgia, serif\",\n            fontSize: 32, fontWeight: 500, letterSpacing: \"-0.025em\",\n            color: \"#130D2E\", margin: \"0 0 6px\", lineHeight: 1.15,\n          }}>\n            Sign in\n          </h2>\n          <p style={{ fontSize: 14, color: \"rgba(19,13,46,0.55)\", margin: \"0 0 28px\" }}>\n            New to DropOS? <Link href=\"/auth/register\" style={{ color: \"#6B35E8\", fontWeight: 600, textDecoration: \"none\" }}>Create an account</Link>\n          </p>\n\n          {/* Just registered notice */}\n          {justRegistered && (\n            <div style={{\n              padding: \"12px 14px\", borderRadius: 12, marginBottom: 16,\n              background: \"rgba(16,185,129,0.06)\", border: \"1px solid rgba(16,185,129,0.15)\",\n              display: \"flex\", alignItems: \"center\", gap: 8,\n            }}>\n              <Check size={14} style={{ color: \"#10B981\", flexShrink: 0 }}/>\n              <p style={{ fontSize: 12.5, color: \"#065F46\", margin: 0, fontWeight: 500 }}>\n                Account created. Sign in to continue.\n              </p>\n            </div>\n          )}\n\n          {/* Google */}\n          <button onClick={handleGoogle} type=\"button\"\n            style={{\n              width: \"100%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n              gap: 10, padding: \"13px 16px\", borderRadius: 12,\n              background: \"#fff\", border: \"1px solid rgba(19,13,46,0.08)\",\n              fontSize: 14, fontWeight: 600, color: \"#130D2E\",\n              cursor: \"pointer\", fontFamily: \"inherit\",\n              transition: \"all 0.15s ease\",\n            }}\n            onMouseEnter={e => { e.currentTarget.style.borderColor = \"rgba(19,13,46,0.16)\"; e.currentTarget.style.transform = \"translateY(-1px)\"; e.currentTarget.style.boxShadow = \"0 4px 12px rgba(19,13,46,0.04)\"; }}\n            onMouseLeave={e => { e.currentTarget.style.borderColor = \"rgba(19,13,46,0.08)\"; e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"none\"; }}>\n            <GoogleIcon /> Continue with Google\n          </button>\n\n          {/* Divider */}\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, margin: \"20px 0\" }}>\n            <div style={{ flex: 1, height: 1, background: \"rgba(19,13,46,0.08)\" }} />\n            <span style={{ fontSize: 11, color: \"rgba(19,13,46,0.4)\", fontWeight: 500, letterSpacing: \"0.05em\" }}>OR</span>\n            <div style={{ flex: 1, height: 1, background: \"rgba(19,13,46,0.08)\" }} />\n          </div>\n\n          {/* Form */}\n          <form onSubmit={handleSubmit(onSubmit)}>\n            {/* Email */}\n            <div style={{ marginBottom: 14 }}>\n              <label style={{ display: \"block\", fontSize: 12, fontWeight: 600, color: \"#130D2E\", marginBottom: 6 }}>\n                Email\n              </label>\n              <div style={{ position: \"relative\" }}>\n                <Mail size={14} style={{ position: \"absolute\", left: 14, top: \"50%\", transform: \"translateY(-50%)\", color: \"rgba(19,13,46,0.35)\" }}/>\n                <input {...register(\"email\")} type=\"email\"\n                  className=\"auth-input\"\n                  placeholder=\"you@example.com\"\n                  style={{\n                    width: \"100%\", padding: \"13px 14px 13px 40px\",\n                    borderRadius: 12, border: \"1px solid rgba(19,13,46,0.1)\",\n                    background: \"#fff\", fontSize: 14, color: \"#130D2E\",\n                    fontFamily: \"inherit\",\n                  }}\n                />\n              </div>\n              {errors.email && <p style={{ fontSize: 11.5, color: \"#EF4444\", marginTop: 5 }}>{errors.email.message}</p>}\n            </div>\n\n            {/* Password */}\n            <div style={{ marginBottom: 8 }}>\n              <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", marginBottom: 6 }}>\n                <label style={{ fontSize: 12, fontWeight: 600, color: \"#130D2E\" }}>Password</label>\n                <Link href=\"/auth/forgot-password\" style={{ fontSize: 12, color: \"#6B35E8\", textDecoration: \"none\", fontWeight: 500 }}>\n                  Forgot?\n                </Link>\n              </div>\n              <div style={{ position: \"relative\" }}>\n                <Lock size={14} style={{ position: \"absolute\", left: 14, top: \"50%\", transform: \"translateY(-50%)\", color: \"rgba(19,13,46,0.35)\" }}/>\n                <input {...register(\"password\")} type={show ? \"text\" : \"password\"}\n                  className=\"auth-input\"\n                  placeholder=\"Enter your password\"\n                  style={{\n                    width: \"100%\", padding: \"13px 44px 13px 40px\",\n                    borderRadius: 12, border: \"1px solid rgba(19,13,46,0.1)\",\n                    background: \"#fff\", fontSize: 14, color: \"#130D2E\",\n                    fontFamily: \"inherit\",\n                  }}\n                />\n                <button type=\"button\" onClick={() => setShow(!show)}\n                  style={{ position: \"absolute\", right: 14, top: \"50%\", transform: \"translateY(-50%)\", background: \"none\", border: \"none\", color: \"rgba(19,13,46,0.4)\", cursor: \"pointer\", padding: 0 }}>\n                  {show ? <EyeOff size={14}/> : <Eye size={14}/>}\n                </button>\n              </div>\n              {errors.password && <p style={{ fontSize: 11.5, color: \"#EF4444\", marginTop: 5 }}>{errors.password.message}</p>}\n            </div>\n\n            {/* Submit */}\n            <button type=\"submit\" disabled={login.isPending}\n              style={{\n                width: \"100%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n                gap: 8, padding: \"14px 16px\", borderRadius: 12, marginTop: 20,\n                background: \"#130D2E\", color: \"#fff\",\n                fontSize: 14, fontWeight: 700, fontFamily: \"inherit\",\n                border: \"none\", cursor: login.isPending ? \"wait\" : \"pointer\",\n                opacity: login.isPending ? 0.7 : 1,\n                transition: \"all 0.15s ease\",\n                boxShadow: \"0 4px 16px rgba(19,13,46,0.15)\",\n              }}\n              onMouseEnter={e => { if (!login.isPending) { e.currentTarget.style.transform = \"translateY(-1px)\"; e.currentTarget.style.boxShadow = \"0 6px 24px rgba(19,13,46,0.22)\"; } }}\n              onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"0 4px 16px rgba(19,13,46,0.15)\"; }}>\n              {login.isPending ? \"Signing in…\" : \"Sign in\"}\n              {!login.isPending && <ArrowRight size={14}/>}\n            </button>\n          </form>\n\n          {/* Footer text */}\n          <p style={{ fontSize: 11, color: \"rgba(19,13,46,0.35)\", textAlign: \"center\", marginTop: 28, lineHeight: 1.5 }}>\n            By signing in, you agree to our{\" \"}\n            <Link href=\"/terms\" style={{ color: \"rgba(19,13,46,0.55)\", textDecoration: \"none\" }}>Terms</Link>\n            {\" \"}and{\" \"}\n            <Link href=\"/privacy\" style={{ color: \"rgba(19,13,46,0.55)\", textDecoration: \"none\" }}>Privacy Policy</Link>\n          </p>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport default function LoginPage() {\n  return (\n    <Suspense fallback={<div style={{ minHeight: \"100vh\", background: \"#F4F2FB\" }}/>}>\n      <LoginInner />\n    </Suspense>\n  );\n}\n","frontend/src/app/auth/register/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { useForm } from \"react-hook-form\";\nimport { zodResolver } from \"@hookform/resolvers/zod\";\nimport { z } from \"zod\";\nimport { Eye, EyeOff, ArrowRight, Check, Mail, Lock, User } from \"lucide-react\";\nimport { useRegister } from \"../../../hooks/useAuth\";\n\nconst schema = z.object({\n  name:     z.string().min(2, \"Name is too short\"),\n  email:    z.string().email(\"Enter a valid email\"),\n  password: z.string()\n    .min(8, \"At least 8 characters\")\n    .regex(/[A-Z]/, \"One uppercase letter\")\n    .regex(/[a-z]/, \"One lowercase letter\")\n    .regex(/\\d/, \"One number\"),\n});\ntype Form = z.infer<typeof schema>;\n\nconst pwChecks = [\n  { label: \"8+ characters\", test: (v: string) => v.length >= 8     },\n  { label: \"Uppercase\",     test: (v: string) => /[A-Z]/.test(v)   },\n  { label: \"Number\",        test: (v: string) => /\\d/.test(v)      },\n];\n\nfunction GoogleIcon() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\">\n      <path d=\"M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z\" fill=\"#4285F4\"/>\n      <path d=\"M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z\" fill=\"#34A853\"/>\n      <path d=\"M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z\" fill=\"#FBBC05\"/>\n      <path d=\"M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z\" fill=\"#EA4335\"/>\n    </svg>\n  );\n}\n\nexport default function RegisterPage() {\n  const [showPw, setShowPw] = useState(false);\n  const [pw, setPw]         = useState(\"\");\n  const reg = useRegister();\n\n  const { register, handleSubmit, formState: { errors } } = useForm<Form>({\n    resolver: zodResolver(schema),\n  });\n\n  const onSubmit = (data: Form) => reg.mutate(data);\n\n  const handleGoogle = () => {\n    const base = process.env.NEXT_PUBLIC_API_URL?.replace(\"/api\", \"\") || \"\";\n    window.location.href = `${base}/api/auth/google`;\n  };\n\n  return (\n    <div style={{ minHeight: \"100vh\", display: \"flex\", background: \"#F4F2FB\", fontFamily: \"'Plus Jakarta Sans', system-ui, -apple-system, sans-serif\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@400;500;600;700;800;900&display=swap');\n        .auth-input { transition: all 0.15s ease; }\n        .auth-input:focus { border-color: #6B35E8 !important; box-shadow: 0 0 0 3px rgba(107,53,232,0.08); outline: none; }\n        .auth-input::placeholder { color: rgba(19,13,46,0.3); }\n        @media (max-width: 768px) {\n          .auth-visual { display: none !important; }\n          .auth-form-pane { width: 100% !important; }\n        }\n      `}</style>\n\n      {/* LEFT — visual panel */}\n      <div className=\"auth-visual\" style={{\n        width: \"44%\",\n        position: \"relative\", overflow: \"hidden\",\n        display: \"flex\", flexDirection: \"column\", justifyContent: \"space-between\",\n        padding: \"48px 56px\",\n        background: \"linear-gradient(160deg, #2D1B69 0%, #1A0B4A 60%, #0D0625 100%)\",\n      }}>\n        <div style={{\n          position: \"absolute\", top: \"-200px\", right: \"-150px\",\n          width: 600, height: 600, borderRadius: \"50%\",\n          background: \"radial-gradient(circle, rgba(167,139,250,0.4) 0%, transparent 60%)\",\n          filter: \"blur(80px)\", pointerEvents: \"none\",\n        }}/>\n        <div style={{\n          position: \"absolute\", bottom: \"-100px\", left: \"-50px\",\n          width: 400, height: 400, borderRadius: \"50%\",\n          background: \"radial-gradient(circle, rgba(124,58,237,0.25) 0%, transparent 60%)\",\n          filter: \"blur(60px)\", pointerEvents: \"none\",\n        }}/>\n\n        <div style={{ position: \"relative\", zIndex: 1, display: \"flex\", alignItems: \"center\", gap: 12 }}>\n          <div style={{\n            width: 36, height: 36, borderRadius: 10,\n            background: \"rgba(255,255,255,0.95)\",\n            display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n          }}>\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\">\n              <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"#2D1B69\"/>\n            </svg>\n          </div>\n          <span style={{ fontSize: 17, fontWeight: 800, color: \"#fff\", letterSpacing: \"-0.02em\" }}>DropOS</span>\n        </div>\n\n        <div style={{ position: \"relative\", zIndex: 1, maxWidth: 440 }}>\n          <h1 style={{\n            fontFamily: \"'Fraunces', Georgia, serif\",\n            fontSize: 44, fontWeight: 500, letterSpacing: \"-0.03em\",\n            color: \"#fff\", margin: \"0 0 18px\", lineHeight: 1.08,\n          }}>\n            Start selling in <em style={{ fontStyle: \"italic\", fontWeight: 400, color: \"#C4B5FD\" }}>minutes</em>.\n          </h1>\n          <p style={{ fontSize: 15, lineHeight: 1.55, color: \"rgba(255,255,255,0.65)\", margin: 0, maxWidth: 380 }}>\n            Join African merchants building real businesses with AI.\n            Launch your store today. No credit card needed.\n          </p>\n        </div>\n\n        <div style={{ position: \"relative\", zIndex: 1, display: \"flex\", alignItems: \"center\", gap: 24 }}>\n          <span style={{ fontSize: 11, fontWeight: 500, color: \"rgba(255,255,255,0.4)\", letterSpacing: \"0.1em\" }}>\n            © 2026 DROPOS\n          </span>\n          <div style={{ width: 1, height: 12, background: \"rgba(255,255,255,0.15)\" }} />\n          <Link href=\"/privacy\" style={{ fontSize: 11, color: \"rgba(255,255,255,0.4)\", textDecoration: \"none\", letterSpacing: \"0.05em\" }}>\n            Privacy\n          </Link>\n          <Link href=\"/terms\" style={{ fontSize: 11, color: \"rgba(255,255,255,0.4)\", textDecoration: \"none\", letterSpacing: \"0.05em\" }}>\n            Terms\n          </Link>\n        </div>\n      </div>\n\n      {/* RIGHT — form pane */}\n      <div className=\"auth-form-pane\" style={{\n        width: \"56%\",\n        display: \"flex\", flexDirection: \"column\",\n        alignItems: \"center\", justifyContent: \"center\",\n        padding: \"48px 24px\",\n        background: \"#FAFAFC\",\n      }}>\n        <div style={{ width: \"100%\", maxWidth: 380 }}>\n\n          {/* Mobile logo */}\n          <div className=\"lg:hidden\" style={{ display: \"flex\", alignItems: \"center\", gap: 10, marginBottom: 28 }}>\n            <div style={{ width: 32, height: 32, borderRadius: 8, background: \"#2D1B69\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n                <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"#fff\"/>\n              </svg>\n            </div>\n            <span style={{ fontSize: 15, fontWeight: 800, color: \"#130D2E\", letterSpacing: \"-0.02em\" }}>DropOS</span>\n          </div>\n\n          <h2 style={{\n            fontFamily: \"'Fraunces', Georgia, serif\",\n            fontSize: 32, fontWeight: 500, letterSpacing: \"-0.025em\",\n            color: \"#130D2E\", margin: \"0 0 6px\", lineHeight: 1.15,\n          }}>\n            Create account\n          </h2>\n          <p style={{ fontSize: 14, color: \"rgba(19,13,46,0.55)\", margin: \"0 0 28px\" }}>\n            Already have an account? <Link href=\"/auth/login\" style={{ color: \"#6B35E8\", fontWeight: 600, textDecoration: \"none\" }}>Sign in</Link>\n          </p>\n\n          <button onClick={handleGoogle} type=\"button\"\n            style={{\n              width: \"100%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n              gap: 10, padding: \"13px 16px\", borderRadius: 12,\n              background: \"#fff\", border: \"1px solid rgba(19,13,46,0.08)\",\n              fontSize: 14, fontWeight: 600, color: \"#130D2E\",\n              cursor: \"pointer\", fontFamily: \"inherit\",\n              transition: \"all 0.15s ease\",\n            }}\n            onMouseEnter={e => { e.currentTarget.style.borderColor = \"rgba(19,13,46,0.16)\"; e.currentTarget.style.transform = \"translateY(-1px)\"; e.currentTarget.style.boxShadow = \"0 4px 12px rgba(19,13,46,0.04)\"; }}\n            onMouseLeave={e => { e.currentTarget.style.borderColor = \"rgba(19,13,46,0.08)\"; e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"none\"; }}>\n            <GoogleIcon /> Sign up with Google\n          </button>\n\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, margin: \"20px 0\" }}>\n            <div style={{ flex: 1, height: 1, background: \"rgba(19,13,46,0.08)\" }} />\n            <span style={{ fontSize: 11, color: \"rgba(19,13,46,0.4)\", fontWeight: 500, letterSpacing: \"0.05em\" }}>OR</span>\n            <div style={{ flex: 1, height: 1, background: \"rgba(19,13,46,0.08)\" }} />\n          </div>\n\n          <form onSubmit={handleSubmit(onSubmit)}>\n            {/* Name */}\n            <div style={{ marginBottom: 14 }}>\n              <label style={{ display: \"block\", fontSize: 12, fontWeight: 600, color: \"#130D2E\", marginBottom: 6 }}>\n                Full name\n              </label>\n              <div style={{ position: \"relative\" }}>\n                <User size={14} style={{ position: \"absolute\", left: 14, top: \"50%\", transform: \"translateY(-50%)\", color: \"rgba(19,13,46,0.35)\" }}/>\n                <input {...register(\"name\")} type=\"text\"\n                  className=\"auth-input\"\n                  placeholder=\"Olamide Sotunde\"\n                  style={{\n                    width: \"100%\", padding: \"13px 14px 13px 40px\",\n                    borderRadius: 12, border: \"1px solid rgba(19,13,46,0.1)\",\n                    background: \"#fff\", fontSize: 14, color: \"#130D2E\",\n                    fontFamily: \"inherit\",\n                  }}\n                />\n              </div>\n              {errors.name && <p style={{ fontSize: 11.5, color: \"#EF4444\", marginTop: 5 }}>{errors.name.message}</p>}\n            </div>\n\n            {/* Email */}\n            <div style={{ marginBottom: 14 }}>\n              <label style={{ display: \"block\", fontSize: 12, fontWeight: 600, color: \"#130D2E\", marginBottom: 6 }}>\n                Email\n              </label>\n              <div style={{ position: \"relative\" }}>\n                <Mail size={14} style={{ position: \"absolute\", left: 14, top: \"50%\", transform: \"translateY(-50%)\", color: \"rgba(19,13,46,0.35)\" }}/>\n                <input {...register(\"email\")} type=\"email\"\n                  className=\"auth-input\"\n                  placeholder=\"you@example.com\"\n                  style={{\n                    width: \"100%\", padding: \"13px 14px 13px 40px\",\n                    borderRadius: 12, border: \"1px solid rgba(19,13,46,0.1)\",\n                    background: \"#fff\", fontSize: 14, color: \"#130D2E\",\n                    fontFamily: \"inherit\",\n                  }}\n                />\n              </div>\n              {errors.email && <p style={{ fontSize: 11.5, color: \"#EF4444\", marginTop: 5 }}>{errors.email.message}</p>}\n            </div>\n\n            {/* Password */}\n            <div style={{ marginBottom: 12 }}>\n              <label style={{ display: \"block\", fontSize: 12, fontWeight: 600, color: \"#130D2E\", marginBottom: 6 }}>\n                Password\n              </label>\n              <div style={{ position: \"relative\" }}>\n                <Lock size={14} style={{ position: \"absolute\", left: 14, top: \"50%\", transform: \"translateY(-50%)\", color: \"rgba(19,13,46,0.35)\" }}/>\n                <input {...register(\"password\", { onChange: e => setPw(e.target.value) })}\n                  type={showPw ? \"text\" : \"password\"}\n                  className=\"auth-input\"\n                  placeholder=\"Create a strong password\"\n                  style={{\n                    width: \"100%\", padding: \"13px 44px 13px 40px\",\n                    borderRadius: 12, border: \"1px solid rgba(19,13,46,0.1)\",\n                    background: \"#fff\", fontSize: 14, color: \"#130D2E\",\n                    fontFamily: \"inherit\",\n                  }}\n                />\n                <button type=\"button\" onClick={() => setShowPw(!showPw)}\n                  style={{ position: \"absolute\", right: 14, top: \"50%\", transform: \"translateY(-50%)\", background: \"none\", border: \"none\", color: \"rgba(19,13,46,0.4)\", cursor: \"pointer\", padding: 0 }}>\n                  {showPw ? <EyeOff size={14}/> : <Eye size={14}/>}\n                </button>\n              </div>\n              {errors.password && <p style={{ fontSize: 11.5, color: \"#EF4444\", marginTop: 5 }}>{errors.password.message}</p>}\n            </div>\n\n            {/* Password strength indicators */}\n            {pw && (\n              <div style={{ display: \"flex\", gap: 12, marginBottom: 16, padding: \"10px 12px\", background: \"rgba(107,53,232,0.03)\", borderRadius: 10 }}>\n                {pwChecks.map(c => {\n                  const passed = c.test(pw);\n                  return (\n                    <div key={c.label} style={{ display: \"flex\", alignItems: \"center\", gap: 5 }}>\n                      <div style={{\n                        width: 14, height: 14, borderRadius: \"50%\",\n                        background: passed ? \"#10B981\" : \"rgba(19,13,46,0.08)\",\n                        display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n                        transition: \"all 0.2s\",\n                      }}>\n                        {passed && <Check size={9} color=\"#fff\" strokeWidth={3}/>}\n                      </div>\n                      <span style={{ fontSize: 11, color: passed ? \"#10B981\" : \"rgba(19,13,46,0.4)\", fontWeight: 500 }}>{c.label}</span>\n                    </div>\n                  );\n                })}\n              </div>\n            )}\n\n            <button type=\"submit\" disabled={reg.isPending}\n              style={{\n                width: \"100%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n                gap: 8, padding: \"14px 16px\", borderRadius: 12, marginTop: 16,\n                background: \"#130D2E\", color: \"#fff\",\n                fontSize: 14, fontWeight: 700, fontFamily: \"inherit\",\n                border: \"none\", cursor: reg.isPending ? \"wait\" : \"pointer\",\n                opacity: reg.isPending ? 0.7 : 1,\n                transition: \"all 0.15s ease\",\n                boxShadow: \"0 4px 16px rgba(19,13,46,0.15)\",\n              }}\n              onMouseEnter={e => { if (!reg.isPending) { e.currentTarget.style.transform = \"translateY(-1px)\"; e.currentTarget.style.boxShadow = \"0 6px 24px rgba(19,13,46,0.22)\"; } }}\n              onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"0 4px 16px rgba(19,13,46,0.15)\"; }}>\n              {reg.isPending ? \"Creating account…\" : \"Create account\"}\n              {!reg.isPending && <ArrowRight size={14}/>}\n            </button>\n          </form>\n\n          <p style={{ fontSize: 11, color: \"rgba(19,13,46,0.35)\", textAlign: \"center\", marginTop: 24, lineHeight: 1.5 }}>\n            By creating an account, you agree to our{\" \"}\n            <Link href=\"/terms\" style={{ color: \"rgba(19,13,46,0.55)\", textDecoration: \"none\" }}>Terms</Link>\n            {\" \"}and{\" \"}\n            <Link href=\"/privacy\" style={{ color: \"rgba(19,13,46,0.55)\", textDecoration: \"none\" }}>Privacy Policy</Link>\n          </p>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/backup/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Download, Package, ShoppingCart, Users, FileText, Shield, Check, Loader2, Clock } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\" };\n\nconst EXPORTS = [\n  { id:\"orders\",    icon:ShoppingCart, label:\"Orders\",        desc:\"All orders with customer details, items, status\" },\n  { id:\"products\",  icon:Package,      label:\"Products\",      desc:\"Full product catalogue with prices and inventory\" },\n  { id:\"customers\", icon:Users,        label:\"Customers\",     desc:\"Customer list with order history and spend\" },\n  { id:\"revenue\",   icon:FileText,     label:\"Revenue Report\",desc:\"Revenue, tax, and profit summary by period\" },\n];\n\nexport default function BackupPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card: isDark?\"#181230\":\"#fff\", border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text: isDark?\"#F0ECFF\":\"#130D2E\", muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint: isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [downloaded, setDownloaded] = useState<Set<string>>(new Set());\n  const [loading, setLoading] = useState<string|null>(null);\n\n  const exportData = async (type: string) => {\n    setLoading(type);\n    try {\n      const r = await api.get(`/reports/${storeId}/${type}`, { responseType: \"blob\" });\n      const url = window.URL.createObjectURL(new Blob([r.data]));\n      const a = document.createElement(\"a\");\n      a.href = url;\n      a.download = `dropos-${type}-${new Date().toISOString().slice(0,10)}.csv`;\n      a.click();\n      window.URL.revokeObjectURL(url);\n      setDownloaded(prev => new Set([...prev, type]));\n      toast.success(`${type} exported successfully`);\n    } catch {\n      toast.error(\"Export failed — try again\");\n    }\n    setLoading(null);\n  };\n\n  const lastBackup = new Date();\n  lastBackup.setDate(lastBackup.getDate() - 1);\n\n  return (\n    <div style={{ maxWidth: 700, margin: \"0 auto\" }}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Backup & Export</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Download your store data as CSV — works in Excel and Google Sheets</p>\n      </motion.div>\n\n      {/* Last backup info */}\n      <div style={{display:\"flex\",alignItems:\"center\",gap:10,padding:\"12px 16px\",borderRadius:12,background:\"rgba(16,185,129,0.06)\",border:\"1px solid rgba(16,185,129,0.2)\",marginBottom:20}}>\n        <Shield size={14} color={V.green} style={{flexShrink:0}}/>\n        <div style={{flex:1}}>\n          <p style={{fontSize:12,fontWeight:700,color:V.green,margin:\"0 0 1px\"}}>Your data is safe</p>\n          <p style={{fontSize:11,color:t.muted,margin:0}}>Stored securely with daily automated backups and encryption</p>\n        </div>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:5,flexShrink:0}}>\n          <Clock size={11} style={{color:t.muted}}/>\n          <span style={{fontSize:11,color:t.muted}}>{lastBackup.toLocaleDateString()}</span>\n        </div>\n      </div>\n\n      {/* Export options */}\n      <div style={{display:\"flex\",flexDirection:\"column\",gap:10}}>\n        {EXPORTS.map((exp, i) => {\n          const Icon = exp.icon;\n          const isDone = downloaded.has(exp.id);\n          const isLoading = loading === exp.id;\n          return (\n            <motion.div key={exp.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n              style={{display:\"flex\",alignItems:\"center\",gap:14,padding:16,borderRadius:16,background:t.card,border:`1px solid ${isDone?\"rgba(16,185,129,0.3)\":t.border}`}}>\n              <div style={{width:42,height:42,borderRadius:12,background:isDone?\"rgba(16,185,129,0.1)\":`${V.v400}10`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0}}>\n                <Icon size={17} color={isDone?V.green:V.v400}/>\n              </div>\n              <div style={{flex:1,minWidth:0}}>\n                <p style={{fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 3px\"}}>{exp.label}</p>\n                <p style={{fontSize:12,color:t.muted,margin:0}}>{exp.desc}</p>\n              </div>\n              <button onClick={() => exportData(exp.id)} disabled={isLoading}\n                style={{display:\"flex\",alignItems:\"center\",gap:6,padding:\"8px 16px\",borderRadius:10,border:`1px solid ${isDone?\"rgba(16,185,129,0.4)\":t.border}`,background:isDone?\"rgba(16,185,129,0.08)\":t.faint,cursor:isLoading?\"not-allowed\":\"pointer\",color:isDone?V.green:t.muted,fontSize:12,fontWeight:700,flexShrink:0}}>\n                {isLoading ? <Loader2 size={12} style={{animation:\"spin 1s linear infinite\"}}/> : isDone ? <Check size={12}/> : <Download size={12}/>}\n                {isLoading ? \"Exporting...\" : isDone ? \"Done\" : \"Export CSV\"}\n              </button>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      {/* Tip */}\n      <div style={{marginTop:20,padding:\"12px 16px\",borderRadius:12,background:t.faint,border:`1px solid ${t.border}`}}>\n        <p style={{fontSize:12,color:t.muted,margin:0,lineHeight:1.5}}>\n          💡 <strong style={{color:t.text}}>Tip:</strong> Export your data monthly and store it in Google Drive. If you ever migrate platforms, you'll have everything ready.\n        </p>\n      </div>\n\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/support/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { LifeBuoy, MessageSquare, Book, ExternalLink, Zap, Send, Loader2, Check, ChevronRight } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\n\nconst FAQS = [\n  { q:\"How do I connect Paystack?\",    a:\"Go to Settings → Payments and follow the Paystack setup steps. It takes about 2 minutes and your store will be ready to accept payments immediately.\" },\n  { q:\"How does dropshipping work?\",   a:\"You list products in your store. When a customer orders, KIRO automatically places the order with your supplier who ships directly to your customer. You keep the margin.\" },\n  { q:\"Can I use a custom domain?\",    a:\"Yes. Go to Settings > Domain. Enter your domain and add the CNAME record pointing to your CNAME target (provided in Settings). SSL is automatic.\" },\n  { q:\"How do I get paid?\",            a:\"Customers pay via Paystack or Stripe directly into your account. DropOS never holds your money. Payouts happen within 1-3 business days.\" },\n  { q:\"Why is KIRO not responding?\",   a:\"KIRO may be temporarily unavailable. Please wait a moment and try again. If the issue continues, contact our support team.\" },\n  { q:\"How do I import products?\",     a:\"Go to Import Products. Paste any AliExpress, CJ, or Zendrop product URL and KIRO will import it automatically with description and images.\" },\n];\n\nexport default function SupportPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n    input:  isDark ? \"rgba(255,255,255,0.05)\" : \"#F5F3FF\",\n  };\n  const user = useAuthStore(s => s.user);\n  const [subject, setSubject] = useState(\"\");\n  const [message, setMessage] = useState(\"\");\n  const [openFaq, setOpenFaq] = useState<number|null>(null);\n  const [sent, setSent] = useState(false);\n\n  const sendMut = useMutation({\n    mutationFn: () => api.post(\"/contact\", {\n      name: user?.name, email: user?.email,\n      subject, message,\n    }),\n    onSuccess: () => { setSent(true); toast.success(\"Message sent! We reply within 24 hours.\"); },\n    onError: () => toast.error(\"Failed to send - email us at hello@droposhq.com\"),\n  });\n\n  const inp = { width:\"100%\", padding:\"11px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.input, color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\" } as const;\n\n  return (\n    <div className=\"max-w-3xl mx-auto\">\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} className=\"mb-8\">\n        <h1 className=\"text-xl sm:text-2xl font-black tracking-tight mb-1\" style={{color:t.text}}>Support</h1>\n        <p className=\"text-sm\" style={{color:t.muted}}>We respond within 24 hours. Usually faster.</p>\n      </motion.div>\n\n      {/* Quick links */}\n      <div className=\"grid grid-cols-3 gap-3 mb-8\">\n        {[\n          { icon:\"📚\", label:\"Docs\",      href:\"https://docs.droposhq.com\",      desc:\"Full documentation\" },\n          { icon:\"💬\", label:\"Ask KIRO\",  href:\"/kiro\",                 desc:\"AI help instantly\"  },\n          { icon:\"📧\", label:\"Email\",     href:\"mailto:hello@droposhq.com\",       desc:\"hello@droposhq.com\" },\n        ].map(item => (\n          <a key={item.label} href={item.href} target={item.href.startsWith(\"http\") ? \"_blank\" : undefined}\n            className=\"flex flex-col items-center gap-2 p-4 rounded-2xl text-center transition-all hover:scale-102\"\n            style={{background:t.card,border:`1px solid ${t.border}`,textDecoration:\"none\"}}>\n            <span className=\"text-2xl\">{item.icon}</span>\n            <p className=\"text-sm font-bold\" style={{color:t.text}}>{item.label}</p>\n            <p className=\"text-xs\" style={{color:t.muted}}>{item.desc}</p>\n          </a>\n        ))}\n      </div>\n\n      {/* FAQ */}\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.08}}\n        className=\"rounded-2xl overflow-hidden mb-8\" style={{background:t.card,border:`1px solid ${t.border}`}}>\n        <div className=\"px-5 py-4\" style={{borderBottom:`1px solid ${t.border}`}}>\n          <p className=\"text-xs font-bold uppercase tracking-widest\" style={{color:t.muted}}>Frequently Asked</p>\n        </div>\n        {FAQS.map((faq, i) => (\n          <div key={i} style={{borderBottom:i<FAQS.length-1?`1px solid ${t.border}`:\"none\"}}>\n            <button onClick={() => setOpenFaq(openFaq===i?null:i)}\n              className=\"w-full flex items-center justify-between px-5 py-4 text-left\"\n              style={{background:\"transparent\",border:\"none\",cursor:\"pointer\"}}>\n              <span className=\"text-sm font-semibold pr-4\" style={{color:t.text}}>{faq.q}</span>\n              <ChevronRight size={14} style={{color:t.muted,flexShrink:0,transform:openFaq===i?\"rotate(90deg)\":\"rotate(0)\",transition:\"transform 0.2s\"}}/>\n            </button>\n            {openFaq === i && (\n              <div className=\"px-5 pb-4\">\n                <p className=\"text-sm leading-relaxed\" style={{color:t.muted}}>{faq.a}</p>\n              </div>\n            )}\n          </div>\n        ))}\n      </motion.div>\n\n      {/* Contact form */}\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.14}}\n        className=\"rounded-2xl overflow-hidden\" style={{background:t.card,border:`1px solid ${t.border}`}}>\n        <div className=\"px-5 py-4\" style={{borderBottom:`1px solid ${t.border}`}}>\n          <p className=\"text-xs font-bold uppercase tracking-widest\" style={{color:t.muted}}>Send a Message</p>\n        </div>\n        {sent ? (\n          <div className=\"p-10 text-center\">\n            <div className=\"w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-4\" style={{background:\"rgba(16,185,129,0.1)\"}}>\n              <Check size={28} color=\"#10B981\"/>\n            </div>\n            <p className=\"font-bold text-base mb-2\" style={{color:t.text}}>Message sent!</p>\n            <p className=\"text-sm\" style={{color:t.muted}}>We will reply to {user?.email} within 24 hours.</p>\n          </div>\n        ) : (\n          <div className=\"p-5 space-y-3\">\n            <input value={subject} onChange={e => setSubject(e.target.value)} placeholder=\"Subject\" style={inp}/>\n            <textarea value={message} onChange={e => setMessage(e.target.value)}\n              placeholder=\"Describe your issue or question...\" rows={5}\n              style={{...inp,resize:\"none\",display:\"block\"}}/>\n            <button onClick={() => sendMut.mutate()} disabled={!subject||!message||sendMut.isPending}\n              className=\"flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white\"\n              style={{background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",opacity:!subject||!message?0.6:1}}>\n              {sendMut.isPending ? <Loader2 size={13} style={{animation:\"spin 1s linear infinite\"}}/> : <Send size={13}/>}\n              {sendMut.isPending ? \"Sending...\" : \"Send Message\"}\n            </button>\n          </div>\n        )}\n      </motion.div>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/ad-spy/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Eye, Zap, Loader2, TrendingUp, DollarSign, Target } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\" };\n\nconst PLATFORMS = [\n  { id:\"tiktok\",    label:\"TikTok\",    emoji:\"🎵\", color:\"#FF0050\" },\n  { id:\"instagram\", label:\"Instagram\", emoji:\"📸\", color:\"#E1306C\" },\n  { id:\"facebook\",  label:\"Facebook\",  emoji:\"👥\", color:\"#1877F2\" },\n  { id:\"twitter\",   label:\"Twitter/X\", emoji:\"🐦\", color:\"#1DA1F2\" },\n];\n\nexport default function AdSpyPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card: isDark?\"#181230\":\"#fff\", border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text: isDark?\"#F0ECFF\":\"#130D2E\", muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint: isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [niche, setNiche] = useState(\"\");\n  const [platform, setPlatform] = useState(\"tiktok\");\n  const [result, setResult] = useState<string|null>(null);\n  const [loading, setLoading] = useState(false);\n\n  const analyse = async () => {\n    if (!niche || loading) return;\n    setLoading(true); setResult(null);\n    try {\n      const plat = PLATFORMS.find(p => p.id === platform);\n      const r = await api.post(\"/kai/smart-chat\", {\n        message: `You are an expert dropshipping ad spy analyst. For the niche \"${niche}\" on ${plat?.label}, give me:\n\n1. **Top 5 winning ad angles** currently working in this niche\n2. **Best hooks** (first 3 seconds) that stop the scroll\n3. **Winning product types** in this niche right now\n4. **Ad copy frameworks** that convert best\n5. **Targeting suggestions** (age, interests, behaviours)\n6. **Estimated CPM and CPC** benchmarks for Nigerian audience\n\nBe specific with examples. Format clearly with sections.`,\n        storeId,\n      });\n      setResult(r.data?.data?.reply || r.data?.reply || \"Analysis complete\");\n    } catch { toast.error(\"KIRO is temporarily unavailable. Please try again shortly.\"); }\n    setLoading(false);\n  };\n\n  const inp = {\n    flex: 1, padding: \"11px 16px\", borderRadius: 12,\n    border: `1px solid ${t.border}`, background: isDark ? \"rgba(255,255,255,0.05)\" : \"#F5F3FF\",\n    color: t.text, fontSize: 13, outline: \"none\", fontFamily: \"inherit\",\n  } as const;\n\n  return (\n    <div style={{ maxWidth: 860, margin: \"0 auto\" }}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Ad Spy</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>KIRO reverse-engineers winning ads in any niche for you</p>\n      </motion.div>\n\n      {/* Platform picker */}\n      <div style={{display:\"flex\",gap:8,marginBottom:14,flexWrap:\"wrap\"}}>\n        {PLATFORMS.map(p => (\n          <button key={p.id} onClick={() => setPlatform(p.id)}\n            style={{display:\"flex\",alignItems:\"center\",gap:7,padding:\"8px 14px\",borderRadius:12,border:`1px solid ${platform===p.id?p.color+\"60\":t.border}`,background:platform===p.id?p.color+\"12\":\"transparent\",cursor:\"pointer\",fontSize:13,fontWeight:600,color:platform===p.id?p.color:t.muted}}>\n            <span>{p.emoji}</span> {p.label}\n          </button>\n        ))}\n      </div>\n\n      {/* Input */}\n      <div style={{display:\"flex\",gap:10,marginBottom:20}}>\n        <input value={niche} onChange={e=>setNiche(e.target.value)} onKeyDown={e=>e.key===\"Enter\"&&analyse()}\n          placeholder=\"Enter niche (e.g. hair extensions, smart watches, skincare)\"\n          style={inp}/>\n        <button onClick={analyse} disabled={!niche||loading}\n          style={{padding:\"11px 22px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:niche&&!loading?\"pointer\":\"not-allowed\",color:\"#fff\",fontSize:13,fontWeight:700,display:\"flex\",alignItems:\"center\",gap:8,flexShrink:0,opacity:!niche||loading?0.6:1}}>\n          {loading ? <Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/> : <Eye size={14}/>}\n          {loading ? \"Spying...\" : \"Spy\"}\n        </button>\n      </div>\n\n      {/* Info cards when empty */}\n      {!result && !loading && (\n        <div style={{display:\"grid\",gridTemplateColumns:\"repeat(3,1fr)\",gap:12}}>\n          {[\n            {emoji:\"🎯\",title:\"Winning angles\",desc:\"See what message converts in your niche right now\"},\n            {emoji:\"✍️\",title:\"Copy frameworks\",desc:\"Get the exact hooks and CTAs that work\"},\n            {emoji:\"💰\",title:\"Budget benchmarks\",desc:\"Know what to spend before your first ad\"},\n          ].map((c,i) => (\n            <div key={i} style={{padding:16,borderRadius:14,background:t.faint,border:`1px solid ${t.border}`,textAlign:\"center\"}}>\n              <div style={{fontSize:28,marginBottom:8}}>{c.emoji}</div>\n              <p style={{fontSize:13,fontWeight:700,color:t.text,margin:\"0 0 4px\"}}>{c.title}</p>\n              <p style={{fontSize:12,color:t.muted,margin:0,lineHeight:1.4}}>{c.desc}</p>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {loading && (\n        <div style={{padding:\"60px 20px\",textAlign:\"center\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`}}>\n          <Loader2 size={28} style={{color:V.v400,margin:\"0 auto 12px\",animation:\"spin 1s linear infinite\"}}/>\n          <p style={{fontSize:13,color:t.muted,margin:0}}>KIRO is analysing winning ads in the {niche} niche...</p>\n        </div>\n      )}\n\n      {result && (\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}\n          style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:8,marginBottom:16}}>\n            <div style={{width:28,height:28,borderRadius:8,background:\"rgba(107,53,232,0.15)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}>\n              <Zap size={13} color={V.v400}/>\n            </div>\n            <span style={{fontSize:13,fontWeight:700,color:t.text}}>Ad Intelligence — {niche} on {PLATFORMS.find(p=>p.id===platform)?.label}</span>\n          </div>\n          <p style={{fontSize:13,lineHeight:1.8,color:t.muted,whiteSpace:\"pre-wrap\",margin:0}}>{result}</p>\n          <button onClick={analyse} style={{marginTop:16,display:\"flex\",alignItems:\"center\",gap:6,padding:\"8px 16px\",borderRadius:10,border:`1px solid ${t.border}`,background:t.faint,cursor:\"pointer\",color:t.muted,fontSize:12,fontWeight:600}}>\n            <Loader2 size={11}/> Refresh analysis\n          </button>\n        </motion.div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/virtual-account/page.tsx":"\"use client\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { Building2, Bell } from \"lucide-react\";\n\nexport default function VirtualAccountPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"rgba(255,255,255,0.03)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.12)\" : \"rgba(107,53,232,0.1)\",\n  };\n  return (\n    <div style={{ maxWidth: 520, margin: \"80px auto 0\", textAlign: \"center\", padding: \"0 24px\" }}>\n      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>\n        <div style={{ width: 80, height: 80, borderRadius: 24, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", margin: \"0 auto 24px\", boxShadow: \"0 8px 32px rgba(45,27,105,0.25)\" }}>\n          <Building2 size={34} color=\"#C4B5FD\"/>\n        </div>\n        <div style={{ display: \"inline-flex\", alignItems: \"center\", gap: 6, background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.15)\", borderRadius: 99, padding: \"5px 14px\", marginBottom: 20 }}>\n          <span style={{ fontSize: 11, fontWeight: 700, color: \"#8B5CF6\", letterSpacing: \"0.08em\" }}>COMING SOON</span>\n        </div>\n        <h1 style={{ fontFamily: \"'Fraunces',Georgia,serif\", fontSize: \"clamp(28px,5vw,38px)\", fontWeight: 500, color: t.text, margin: \"0 0 14px\", letterSpacing: \"-0.03em\", lineHeight: 1.15 }}>\n          Virtual Bank Account\n        </h1>\n        <p style={{ fontSize: 15, color: t.muted, lineHeight: 1.65, margin: \"0 0 36px\" }}>\n          Get your own dedicated account number for your store. We're working on it — it'll be ready soon.\n        </p>\n        <div style={{ padding: \"18px 20px\", borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, display: \"flex\", alignItems: \"center\", gap: 12, textAlign: \"left\" }}>\n          <div style={{ width: 36, height: 36, borderRadius: 10, background: \"rgba(107,53,232,0.08)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n            <Bell size={16} color=\"#8B5CF6\"/>\n          </div>\n          <p style={{ fontSize: 13, color: t.muted, margin: 0, lineHeight: 1.5 }}>\n            You'll be notified as soon as this goes live.\n          </p>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n","frontend/src/components/HomePage.tsx":"\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\nimport { motion, useScroll, useTransform, AnimatePresence } from \"framer-motion\";\nimport Link from \"next/link\";\nimport {\n  Zap, ArrowRight, Check, Store, Package, BarChart3,\n  ShoppingCart, Globe, Shield, TrendingUp, Sparkles,\n  ChevronRight, Star, Play, Menu, X, MessageSquare,\n} from \"lucide-react\";\n\n// ─── Brand colors (matches dashboard + auth) ─────────────────────────────────\nconst C = {\n  bg:      \"#F4F2FB\",\n  navy:    \"#130D2E\",\n  purple:  \"#6B35E8\",\n  violet:  \"#2D1B69\",\n  muted:   \"rgba(19,13,46,0.5)\",\n  faint:   \"rgba(107,53,232,0.06)\",\n  border:  \"rgba(107,53,232,0.1)\",\n};\n\nconst API = process.env.NEXT_PUBLIC_API_URL || \"\";\n\n// ─── Nav ──────────────────────────────────────────────────────────────────────\nfunction Nav() {\n  const [scrolled, setScrolled] = useState(false);\n  const [mobileOpen, setMobileOpen] = useState(false);\n\n  useEffect(() => {\n    const fn = () => setScrolled(window.scrollY > 20);\n    window.addEventListener(\"scroll\", fn);\n    return () => window.removeEventListener(\"scroll\", fn);\n  }, []);\n\n  return (\n    <>\n      <nav style={{\n        position: \"fixed\", top: 0, left: 0, right: 0, zIndex: 100,\n        padding: \"0 24px\",\n        height: 64,\n        display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\",\n        background: scrolled ? \"rgba(244,242,251,0.92)\" : \"transparent\",\n        backdropFilter: scrolled ? \"blur(20px)\" : \"none\",\n        borderBottom: scrolled ? `1px solid ${C.border}` : \"1px solid transparent\",\n        transition: \"all 0.3s ease\",\n      }}>\n        {/* Logo */}\n        <Link href=\"/\" style={{ display: \"flex\", alignItems: \"center\", gap: 10, textDecoration: \"none\" }}>\n          <div style={{\n            width: 32, height: 32, borderRadius: 9,\n            background: \"linear-gradient(145deg,#2D1B69,#0D0625)\",\n            display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n            boxShadow: \"0 4px 12px rgba(45,27,105,0.3)\",\n          }}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n              <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/>\n            </svg>\n          </div>\n          <span style={{ fontSize: 16, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n        </Link>\n\n        {/* Desktop nav */}\n        <div className=\"nav-links\" style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n          {[\n            { label: \"Features\",   href: \"/#features\"  },\n            { label: \"Pricing\",    href: \"/pricing\"    },\n            { label: \"How it works\", href: \"/how-it-works\" },\n          ].map(l => (\n            <Link key={l.label} href={l.href}\n              style={{ fontSize: 13, fontWeight: 500, color: C.muted, textDecoration: \"none\", padding: \"6px 12px\", borderRadius: 8, transition: \"all 0.15s\" }}\n              onMouseEnter={e => { e.currentTarget.style.color = C.navy; e.currentTarget.style.background = C.faint; }}\n              onMouseLeave={e => { e.currentTarget.style.color = C.muted; e.currentTarget.style.background = \"transparent\"; }}>\n              {l.label}\n            </Link>\n          ))}\n        </div>\n\n        {/* CTA */}\n        <div className=\"nav-cta\" style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <Link href=\"/auth/login\" style={{ fontSize: 13, fontWeight: 600, color: C.muted, textDecoration: \"none\", padding: \"8px 14px\", borderRadius: 8 }}>\n            Sign in\n          </Link>\n          <Link href=\"/auth/register\" style={{\n            fontSize: 13, fontWeight: 700, color: \"#fff\", textDecoration: \"none\",\n            padding: \"9px 18px\", borderRadius: 10,\n            background: C.navy,\n            boxShadow: \"0 4px 14px rgba(19,13,46,0.2)\",\n            display: \"flex\", alignItems: \"center\", gap: 6,\n          }}>\n            Start free <ArrowRight size={13}/>\n          </Link>\n        </div>\n\n        {/* Mobile hamburger */}\n        <button className=\"nav-mobile-btn\" onClick={() => setMobileOpen(!mobileOpen)}\n          style={{ display: \"none\", background: \"none\", border: \"none\", cursor: \"pointer\", color: C.navy, padding: 4 }}>\n          {mobileOpen ? <X size={22}/> : <Menu size={22}/>}\n        </button>\n      </nav>\n\n      {/* Mobile menu */}\n      <AnimatePresence>\n        {mobileOpen && (\n          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}\n            style={{\n              position: \"fixed\", top: 64, left: 0, right: 0, zIndex: 99,\n              background: \"rgba(244,242,251,0.98)\", backdropFilter: \"blur(20px)\",\n              borderBottom: `1px solid ${C.border}`, padding: \"16px 24px 24px\",\n              display: \"flex\", flexDirection: \"column\", gap: 4,\n            }}>\n            {[\"Features\", \"Pricing\", \"How it works\"].map(l => (\n              <Link key={l} href={`/${l.toLowerCase().replace(/ /g, \"-\")}`}\n                onClick={() => setMobileOpen(false)}\n                style={{ fontSize: 15, fontWeight: 600, color: C.navy, textDecoration: \"none\", padding: \"12px 0\", borderBottom: `1px solid ${C.border}` }}>\n                {l}\n              </Link>\n            ))}\n            <Link href=\"/auth/register\" onClick={() => setMobileOpen(false)}\n              style={{ marginTop: 12, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6, padding: \"14px 0\", borderRadius: 12, background: C.navy, color: \"#fff\", textDecoration: \"none\", fontSize: 15, fontWeight: 700 }}>\n              Start free <ArrowRight size={14}/>\n            </Link>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @media(max-width:768px){ .nav-links,.nav-cta{display:none!important;} .nav-mobile-btn{display:flex!important;} }\n      `}</style>\n    </>\n  );\n}\n\n// ─── Hero ─────────────────────────────────────────────────────────────────────\nfunction Hero() {\n  const [email, setEmail] = useState(\"\");\n  const [submitted, setSubmitted] = useState(false);\n  const [loading, setLoading] = useState(false);\n\n  const join = async () => {\n    if (!email || loading) return;\n    setLoading(true);\n    try {\n      await fetch(`${API}/waitlist`, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ email, source: \"homepage\" }),\n      });\n    } catch {}\n    setSubmitted(true);\n    setLoading(false);\n  };\n\n  return (\n    <section style={{\n      minHeight: \"100vh\",\n      display: \"flex\", flexDirection: \"column\", alignItems: \"center\", justifyContent: \"center\",\n      padding: \"120px 24px 80px\",\n      textAlign: \"center\",\n      position: \"relative\",\n      overflow: \"hidden\",\n    }}>\n      {/* Ambient background */}\n      <div style={{\n        position: \"absolute\", top: \"10%\", left: \"50%\", transform: \"translateX(-50%)\",\n        width: 700, height: 700, borderRadius: \"50%\",\n        background: \"radial-gradient(circle, rgba(107,53,232,0.08) 0%, transparent 65%)\",\n        filter: \"blur(60px)\", pointerEvents: \"none\",\n      }}/>\n\n      {/* Badge */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}\n        style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 8,\n          padding: \"6px 14px 6px 6px\", borderRadius: 99,\n          background: \"#fff\", border: `1px solid ${C.border}`,\n          marginBottom: 28, boxShadow: \"0 2px 12px rgba(107,53,232,0.08)\",\n        }}>\n        <span style={{\n          fontSize: 10, fontWeight: 800, letterSpacing: \"0.08em\",\n          background: C.navy, color: \"#fff\",\n          padding: \"3px 8px\", borderRadius: 99,\n        }}>NEW</span>\n        <span style={{ fontSize: 12, color: C.muted, fontWeight: 500 }}>\n          KIRO AI now has 22 smart commands\n        </span>\n        <ChevronRight size={12} style={{ color: C.muted }}/>\n      </motion.div>\n\n      {/* Headline */}\n      <motion.h1 initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.1 }}\n        style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(40px, 7vw, 76px)\",\n          fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, lineHeight: 1.04,\n          maxWidth: 800, margin: \"0 0 20px\",\n        }}>\n        The smarter way<br/>\n        <em style={{ fontStyle: \"italic\", color: C.purple }}>to dropship.</em>\n      </motion.h1>\n\n      {/* Subheading */}\n      <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.2 }}\n        style={{ fontSize: \"clamp(15px, 2.5vw, 18px)\", color: C.muted, maxWidth: 520, lineHeight: 1.6, marginBottom: 40 }}>\n        Launch your store in 60 seconds. Import from any supplier worldwide.\n        Let KIRO handle the copy, pricing, and sales — so you focus on growing.\n      </motion.p>\n\n      {/* CTA */}\n      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.3 }}\n        style={{ display: \"flex\", gap: 10, flexWrap: \"wrap\", justifyContent: \"center\" }}>\n        <Link href=\"/auth/register\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 15, fontWeight: 700,\n          boxShadow: \"0 8px 28px rgba(19,13,46,0.22)\",\n          letterSpacing: \"-0.01em\",\n          transition: \"all 0.15s\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; e.currentTarget.style.boxShadow = \"0 12px 36px rgba(19,13,46,0.3)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; e.currentTarget.style.boxShadow = \"0 8px 28px rgba(19,13,46,0.22)\"; }}>\n          Start for free <ArrowRight size={15}/>\n        </Link>\n        <Link href=\"/auth/login\" style={{\n          display: \"flex\", alignItems: \"center\", gap: 8,\n          padding: \"15px 28px\", borderRadius: 14,\n          background: \"#fff\", color: C.navy,\n          textDecoration: \"none\", fontSize: 15, fontWeight: 600,\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 2px 12px rgba(107,53,232,0.06)\",\n          transition: \"all 0.15s\",\n        }}>\n          Sign in\n        </Link>\n      </motion.div>\n\n      {/* Trust signals */}\n      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.5 }}\n        style={{ display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"center\", gap: \"8px 24px\", marginTop: 36 }}>\n        {[\n          \"No credit card required\",\n          \"Free plan available\",\n          \"Paystack + Stripe payments\",\n          \"29 store templates\",\n        ].map(f => (\n          <span key={f} style={{ display: \"flex\", alignItems: \"center\", gap: 6, fontSize: 12, color: C.muted }}>\n            <Check size={11} color={C.purple} strokeWidth={2.5}/>\n            {f}\n          </span>\n        ))}\n      </motion.div>\n\n      {/* Dashboard preview */}\n      <motion.div initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8, delay: 0.4 }}\n        style={{ width: \"100%\", maxWidth: 960, marginTop: 72, position: \"relative\" }}>\n        {/* Glow under the preview */}\n        <div style={{\n          position: \"absolute\", bottom: -40, left: \"10%\", right: \"10%\",\n          height: 80, borderRadius: \"50%\",\n          background: \"radial-gradient(ellipse, rgba(107,53,232,0.15), transparent)\",\n          filter: \"blur(20px)\",\n        }}/>\n        <div style={{\n          borderRadius: 20, overflow: \"hidden\",\n          border: `1px solid ${C.border}`,\n          boxShadow: \"0 32px 80px rgba(19,13,46,0.12), 0 2px 4px rgba(19,13,46,0.04)\",\n          background: \"#fff\",\n          position: \"relative\",\n        }}>\n          {/* Browser chrome */}\n          <div style={{\n            background: \"#F4F2FB\", padding: \"12px 16px\",\n            borderBottom: `1px solid ${C.border}`,\n            display: \"flex\", alignItems: \"center\", gap: 8,\n          }}>\n            <div style={{ display: \"flex\", gap: 5 }}>\n              {[\"#EF4444\",\"#F59E0B\",\"#10B981\"].map(c => (\n                <div key={c} style={{ width: 10, height: 10, borderRadius: \"50%\", background: c }}/>\n              ))}\n            </div>\n            <div style={{\n              flex: 1, maxWidth: 240, margin: \"0 auto\",\n              background: \"#fff\", borderRadius: 6, padding: \"4px 12px\",\n              fontSize: 11, color: C.muted, textAlign: \"center\", border: `1px solid ${C.border}`,\n            }}>\n              droposhq.com/dashboard\n            </div>\n          </div>\n          {/* Dashboard mock */}\n          <div style={{ background: \"#F4F2FB\", padding: 20, display: \"flex\", gap: 14, minHeight: 320 }}>\n            {/* Sidebar */}\n            <div style={{ width: 48, background: \"#fff\", borderRadius: 12, padding: \"16px 0\", display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 16, border: `1px solid ${C.border}` }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n              </div>\n              {[Zap, Package, ShoppingCart, BarChart3, Store].map((Icon, i) => (\n                <div key={i} style={{ width: 32, height: 32, borderRadius: 8, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: i === 0 ? \"rgba(107,53,232,0.1)\" : \"transparent\" }}>\n                  <Icon size={14} color={i === 0 ? C.purple : \"rgba(19,13,46,0.3)\"}/>\n                </div>\n              ))}\n            </div>\n            {/* Content */}\n            <div style={{ flex: 1, display: \"flex\", flexDirection: \"column\", gap: 12 }}>\n              {/* Stats row */}\n              <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 10 }}>\n                {[\n                  { label: \"Revenue\", value: \"₦284,000\", up: true },\n                  { label: \"Orders\",  value: \"42\",        up: true },\n                  { label: \"Products\",value: \"186\",       up: false },\n                  { label: \"Visitors\",value: \"1,240\",     up: true },\n                ].map(s => (\n                  <div key={s.label} style={{ background: \"#fff\", borderRadius: 12, padding: \"14px 12px\", border: `1px solid ${C.border}` }}>\n                    <p style={{ fontSize: 9, color: C.muted, margin: \"0 0 4px\", textTransform: \"uppercase\", letterSpacing: \"0.05em\" }}>{s.label}</p>\n                    <p style={{ fontSize: 17, fontWeight: 800, color: C.navy, margin: 0 }}>{s.value}</p>\n                    <p style={{ fontSize: 9, color: s.up ? \"#10B981\" : \"#EF4444\", margin: \"2px 0 0\" }}>{s.up ? \"↑\" : \"↓\"} this month</p>\n                  </div>\n                ))}\n              </div>\n              {/* KIRO chat */}\n              <div style={{ background: \"#fff\", borderRadius: 12, padding: 16, border: `1px solid ${C.border}`, flex: 1 }}>\n                <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 12 }}>\n                  <div style={{ width: 24, height: 24, borderRadius: 6, background: \"linear-gradient(145deg,#7c3aed,#4c1d95)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <Zap size={11} color=\"#fff\"/>\n                  </div>\n                  <span style={{ fontSize: 11, fontWeight: 700, color: C.navy }}>KIRO</span>\n                  <span style={{ fontSize: 9, color: \"#10B981\", background: \"rgba(16,185,129,0.1)\", padding: \"2px 6px\", borderRadius: 99 }}>● Ready</span>\n                </div>\n                <div style={{ background: \"#F4F2FB\", borderRadius: 10, padding: \"10px 14px\", marginBottom: 8 }}>\n                  <p style={{ fontSize: 11, color: C.navy, margin: 0 }}>Your store made ₦47,000 this week. Want me to run a flash sale to hit ₦100k by Sunday?</p>\n                </div>\n                <div style={{ display: \"flex\", gap: 6 }}>\n                  {[\"Yes, let's go\", \"Show me the plan\", \"Not now\"].map(a => (\n                    <button key={a} style={{ fontSize: 9, padding: \"5px 10px\", borderRadius: 6, border: `1px solid ${C.border}`, background: \"#fff\", color: C.muted, cursor: \"pointer\", fontFamily: \"inherit\" }}>{a}</button>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Features ─────────────────────────────────────────────────────────────────\nconst FEATURES = [\n  {\n    icon: Sparkles,\n    color: \"#7C3AED\",\n    title: \"KIRO AI — your commerce brain\",\n    desc: \"Import products, write descriptions, run flash sales, recover abandoned carts, and get daily insights — all from a single chat.\",\n    tags: [\"22 slash commands\", \"Proactive alerts\", \"Daily brief\"],\n  },\n  {\n    icon: Store,\n    color: \"#0EA5E9\",\n    title: \"29 store templates\",\n    desc: \"From fashion to food to electronics — pick a template that matches your brand. Customize colors, fonts, and layout in seconds.\",\n    tags: [\"Fashion\", \"Beauty\", \"Electronics\", \"+26 more\"],\n  },\n  {\n    icon: Package,\n    color: \"#10B981\",\n    title: \"One-click supplier import\",\n    desc: \"Paste any AliExpress, Temu, or Amazon link. KIRO scrapes it, scores it A–F, and sets a margin price that actually makes you money.\",\n    tags: [\"AliExpress\", \"Temu\", \"Amazon\", \"CJDropshipping\"],\n  },\n  {\n    icon: TrendingUp,\n    color: \"#F59E0B\",\n    title: \"Paystack + Stripe payments\",\n    desc: \"Accept Naira payments via Paystack. Accept global card payments via Stripe. Both wired in — no code needed.\",\n    tags: [\"Card\", \"Bank transfer\", \"USSD\", \"International\"],\n  },\n  {\n    icon: BarChart3,\n    color: \"#EF4444\",\n    title: \"Smart analytics\",\n    desc: \"Revenue, orders, conversion rate, top products. KIRO reads your numbers and tells you what to do about them.\",\n    tags: [\"Revenue\", \"Conversion\", \"Products\", \"Customers\"],\n  },\n  {\n    icon: MessageSquare,\n    color: \"#8B5CF6\",\n    title: \"Opportunity engine\",\n    desc: \"KIRO scans your store every 6 hours for price wins, bundle opportunities, abandoned cart value, and seasonal moments.\",\n    tags: [\"Pricing AI\", \"Bundle detection\", \"Win-back\", \"Seasonal\"],\n  },\n];\n\nfunction Features() {\n  return (\n    <section id=\"features\" style={{ padding: \"100px 24px\", maxWidth: 1080, margin: \"0 auto\" }}>\n      <div style={{ textAlign: \"center\", marginBottom: 64 }}>\n        <p style={{ fontSize: 12, fontWeight: 700, letterSpacing: \"0.12em\", color: C.purple, marginBottom: 12, textTransform: \"uppercase\" }}>\n          EVERYTHING YOU NEED\n        </p>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 5vw, 52px)\", fontWeight: 500, letterSpacing: \"-0.035em\",\n          color: C.navy, margin: \"0 0 16px\", lineHeight: 1.1,\n        }}>\n          Everything you need,<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>nothing you don't.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 480, margin: \"0 auto\", lineHeight: 1.6 }}>\n          Every feature is designed to help you sell more, work less, and grow faster.\n        </p>\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(3,1fr)\", gap: 16 }} className=\"feat-grid\">\n        {FEATURES.map((f, i) => {\n          const Icon = f.icon;\n          return (\n            <motion.div key={f.title}\n              initial={{ opacity: 0, y: 16 }} whileInView={{ opacity: 1, y: 0 }}\n              transition={{ delay: i * 0.08 }} viewport={{ once: true }}\n              style={{\n                background: \"#fff\", borderRadius: 20, padding: 24,\n                border: `1px solid ${C.border}`,\n                boxShadow: \"0 2px 12px rgba(107,53,232,0.05)\",\n                transition: \"all 0.2s\",\n              }}\n              whileHover={{ y: -4, boxShadow: \"0 8px 32px rgba(107,53,232,0.1)\" }}>\n              <div style={{\n                width: 44, height: 44, borderRadius: 12, marginBottom: 16,\n                background: `${f.color}12`,\n                display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n              }}>\n                <Icon size={20} color={f.color}/>\n              </div>\n              <h3 style={{ fontSize: 15, fontWeight: 700, color: C.navy, margin: \"0 0 8px\", letterSpacing: \"-0.02em\" }}>{f.title}</h3>\n              <p style={{ fontSize: 13, color: C.muted, lineHeight: 1.6, margin: \"0 0 16px\" }}>{f.desc}</p>\n              <div style={{ display: \"flex\", flexWrap: \"wrap\", gap: 6 }}>\n                {f.tags.map(t => (\n                  <span key={t} style={{ fontSize: 10, fontWeight: 600, padding: \"3px 9px\", borderRadius: 99, background: C.faint, color: C.purple, border: `1px solid ${C.border}` }}>\n                    {t}\n                  </span>\n                ))}\n              </div>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      <style>{`@media(max-width:768px){ .feat-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Location-aware Pricing Preview ──────────────────────────────────────────\nconst PRICING_BY_REGION: Record<string, {\n  symbol: string; free: string; growth: string; pro: string;\n  period: string; tagline: string; badge?: string;\n}> = {\n  NG: { symbol:\"₦\", free:\"₦0\",     growth:\"₦9,500\",  pro:\"₦25,000\", period:\"/mo\", tagline:\"Pay in Naira. No forex stress.\", badge:\"🇳🇬 Nigerian prices\" },\n  GH: { symbol:\"₵\", free:\"₵0\",     growth:\"₵89\",     pro:\"₵240\",    period:\"/mo\", tagline:\"Priced for Ghana. Accept GHS payments.\", badge:\"🇬🇭 Ghana prices\" },\n  KE: { symbol:\"KSh\",free:\"KSh 0\", growth:\"KSh 1,300\",pro:\"KSh 3,500\",period:\"/mo\", tagline:\"Priced for Kenya. M-Pesa friendly.\", badge:\"🇰🇪 Kenya prices\" },\n  ZA: { symbol:\"R\",  free:\"R 0\",   growth:\"R 180\",   pro:\"R 470\",   period:\"/mo\", tagline:\"Priced for South Africa.\", badge:\"🇿🇦 South Africa prices\" },\n  GB: { symbol:\"£\",  free:\"£0\",    growth:\"£5\",      pro:\"£14\",     period:\"/mo\", tagline:\"Priced for the UK. Accept GBP.\", badge:\"🇬🇧 UK prices\" },\n  US: { symbol:\"$\",  free:\"$0\",    growth:\"$6\",      pro:\"$16\",     period:\"/mo\", tagline:\"Accept USD payments globally.\", badge:\"🇺🇸 US prices\" },\n  DEFAULT: { symbol:\"$\", free:\"$0\", growth:\"$6\",     pro:\"$16\",     period:\"/mo\", tagline:\"Accept payments in 50+ currencies.\", },\n};\n\nfunction detectRegion(): string {\n  if (typeof window === \"undefined\") return \"DEFAULT\";\n  try {\n    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;\n    if (tz.includes(\"Lagos\") || tz.includes(\"Abuja\")) return \"NG\";\n    if (tz.includes(\"Accra\")) return \"GH\";\n    if (tz.includes(\"Nairobi\")) return \"KE\";\n    if (tz.includes(\"Johannesburg\") || tz.includes(\"Cape_Town\")) return \"ZA\";\n    if (tz.includes(\"London\")) return \"GB\";\n    if (tz.includes(\"New_York\") || tz.includes(\"Los_Angeles\") || tz.includes(\"Chicago\")) return \"US\";\n    const lang = navigator.language || \"\";\n    if (lang.includes(\"en-NG\")) return \"NG\";\n    if (lang.includes(\"en-GH\")) return \"GH\";\n    if (lang.includes(\"en-KE\")) return \"KE\";\n    if (lang.includes(\"en-ZA\")) return \"ZA\";\n    if (lang.includes(\"en-GB\")) return \"GB\";\n    if (lang.includes(\"en-US\")) return \"US\";\n  } catch {}\n  return \"DEFAULT\";\n}\n\nfunction PricingPreview() {\n  const [region, setRegion] = useState(\"DEFAULT\");\n  useEffect(() => { setRegion(detectRegion()); }, []);\n  const p = PRICING_BY_REGION[region] || PRICING_BY_REGION.DEFAULT;\n\n  const plans = [\n    { name: \"Free\",   price: p.free,   features: [\"1 store\", \"20 products\", \"KIRO — 10 msg/day\", \"Basic analytics\"], highlight: false },\n    { name: \"Growth\", price: p.growth, features: [\"5 stores\", \"Unlimited products\", \"KIRO — unlimited\", \"Custom domain\", \"Priority support\"], highlight: true },\n    { name: \"Pro\",    price: p.pro,    features: [\"Unlimited stores\", \"Everything in Growth\", \"API access\", \"Dedicated support\"], highlight: false },\n  ];\n\n  return (\n    <section style={{ padding:\"80px 24px\", background:\"linear-gradient(160deg,#2D1B69 0%,#0D0625 100%)\" }}>\n      <div style={{ maxWidth:960, margin:\"0 auto\", textAlign:\"center\" }}>\n        <p style={{ fontSize:12, fontWeight:700, letterSpacing:\"0.12em\", color:\"rgba(196,181,253,0.7)\", marginBottom:12, textTransform:\"uppercase\" }}>PRICING</p>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, letterSpacing:\"-0.03em\", color:\"#fff\", margin:\"0 0 10px\", lineHeight:1.1 }}>\n          Start free.<br/>\n          <em style={{ fontStyle:\"italic\", color:\"#C4B5FD\" }}>Scale when you're ready.</em>\n        </h2>\n\n        {/* Location badge */}\n        {p.badge && (\n          <div style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, margin:\"14px 0 32px\", padding:\"6px 14px\", borderRadius:99, background:\"rgba(255,255,255,0.08)\", border:\"1px solid rgba(255,255,255,0.12)\" }}>\n            <span style={{ fontSize:12, color:\"rgba(255,255,255,0.7)\", fontWeight:500 }}>{p.badge}</span>\n            <span style={{ fontSize:11, color:\"rgba(196,181,253,0.6)\" }}>· {p.tagline}</span>\n          </div>\n        )}\n        {!p.badge && <p style={{ fontSize:14, color:\"rgba(255,255,255,0.5)\", marginBottom:36 }}>{p.tagline}</p>}\n\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:14, marginBottom:36 }} className=\"price-grid\">\n          {plans.map(plan => (\n            <div key={plan.name} style={{\n              background: plan.highlight ? \"rgba(255,255,255,0.1)\" : \"rgba(255,255,255,0.04)\",\n              borderRadius:20, padding:\"28px 24px\",\n              border: plan.highlight ? \"1px solid rgba(196,181,253,0.35)\" : \"1px solid rgba(255,255,255,0.08)\",\n              position:\"relative\",\n            }}>\n              {plan.highlight && (\n                <div style={{ position:\"absolute\", top:-12, left:\"50%\", transform:\"translateX(-50%)\", background:\"#C4B5FD\", color:\"#130D2E\", fontSize:10, fontWeight:800, padding:\"4px 14px\", borderRadius:99, letterSpacing:\"0.06em\", whiteSpace:\"nowrap\" }}>\n                  MOST POPULAR\n                </div>\n              )}\n              <p style={{ fontSize:13, fontWeight:700, color:\"rgba(196,181,253,0.8)\", margin:\"0 0 8px\" }}>{plan.name}</p>\n              <div style={{ display:\"flex\", alignItems:\"baseline\", gap:4, marginBottom:20 }}>\n                <span style={{ fontSize:30, fontWeight:900, color:\"#fff\", letterSpacing:\"-0.03em\" }}>{plan.price}</span>\n                <span style={{ fontSize:12, color:\"rgba(255,255,255,0.4)\" }}>{p.period}</span>\n              </div>\n              {plan.features.map(f => (\n                <div key={f} style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:10 }}>\n                  <Check size={11} color=\"#A78BFA\" strokeWidth={2.5}/>\n                  <span style={{ fontSize:12, color:\"rgba(255,255,255,0.65)\" }}>{f}</span>\n                </div>\n              ))}\n            </div>\n          ))}\n        </div>\n\n        <p style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", marginBottom:24 }}>\n          2% transaction fee on all plans · Cancel anytime\n        </p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start for free <ArrowRight size={14}/>\n        </Link>\n      </div>\n      <style>{`@media(max-width:768px){ .price-grid{grid-template-columns:1fr!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── Social Proof ──────────────────────────────────────────────────────────────\nfunction SocialProof() {\n  const stats = [\n    { value: \"29\",   label: \"Store templates\" },\n    { value: \"60s\",  label: \"To launch a store\" },\n    { value: \"54+\",  label: \"Backend features\" },\n    { value: \"100%\", label: \"Uptime SLA\" },\n  ];\n\n  return (\n    <section style={{ padding: \"80px 24px\", maxWidth: 960, margin: \"0 auto\" }}>\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 24, textAlign: \"center\" }} className=\"stats-grid\">\n        {stats.map((s, i) => (\n          <motion.div key={s.label}\n            initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }}\n            transition={{ delay: i * 0.1 }} viewport={{ once: true }}>\n            <p style={{\n              fontFamily: \"'Fraunces', Georgia, serif\",\n              fontSize: \"clamp(36px, 6vw, 56px)\", fontWeight: 500,\n              color: C.navy, margin: \"0 0 6px\", letterSpacing: \"-0.04em\",\n              lineHeight: 1,\n            }}>{s.value}</p>\n            <p style={{ fontSize: 13, color: C.muted, margin: 0 }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n      <style>{`@media(max-width:768px){ .stats-grid{grid-template-columns:1fr 1fr!important; gap:32px!important;} }`}</style>\n    </section>\n  );\n}\n\n// ─── CTA ──────────────────────────────────────────────────────────────────────\nfunction FinalCTA() {\n  return (\n    <section style={{ padding: \"100px 24px\", textAlign: \"center\" }}>\n      <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>\n        <h2 style={{\n          fontFamily: \"'Fraunces', Georgia, serif\",\n          fontSize: \"clamp(32px, 6vw, 60px)\", fontWeight: 500, letterSpacing: \"-0.04em\",\n          color: C.navy, margin: \"0 0 18px\", lineHeight: 1.08,\n        }}>\n          Your store is<br/>\n          <em style={{ fontStyle: \"italic\", color: C.purple }}>60 seconds away.</em>\n        </h2>\n        <p style={{ fontSize: 16, color: C.muted, maxWidth: 400, margin: \"0 auto 40px\", lineHeight: 1.6 }}>\n          No inventory. No coding. Just KIRO and a product idea.\n          The rest takes care of itself.\n        </p>\n        <Link href=\"/auth/register\" style={{\n          display: \"inline-flex\", alignItems: \"center\", gap: 10,\n          padding: \"16px 36px\", borderRadius: 16,\n          background: C.navy, color: \"#fff\",\n          textDecoration: \"none\", fontSize: 16, fontWeight: 700,\n          boxShadow: \"0 8px 32px rgba(19,13,46,0.2)\",\n          letterSpacing: \"-0.01em\",\n        }}\n        onMouseEnter={e => { e.currentTarget.style.transform = \"translateY(-2px)\"; }}\n        onMouseLeave={e => { e.currentTarget.style.transform = \"translateY(0)\"; }}>\n          Launch your store free <ArrowRight size={16}/>\n        </Link>\n        <p style={{ fontSize: 12, color: C.muted, marginTop: 16 }}>\n          No credit card · Free plan forever · Cancel anytime\n        </p>\n      </motion.div>\n    </section>\n  );\n}\n\n// ─── Footer ───────────────────────────────────────────────────────────────────\nfunction Footer() {\n  return (\n    <footer style={{\n      borderTop: `1px solid ${C.border}`, padding: \"40px 24px\",\n      background: \"#fff\",\n    }}>\n      <div style={{ maxWidth: 960, margin: \"0 auto\", display: \"flex\", flexWrap: \"wrap\", alignItems: \"center\", justifyContent: \"space-between\", gap: 16 }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n          <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg,#2D1B69,#0D0625)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <span style={{ fontSize: 14, fontWeight: 800, color: C.navy, letterSpacing: \"-0.02em\" }}>DropOS</span>\n          <span style={{ fontSize: 12, color: C.muted }}>© 2026</span>\n        </div>\n        <div style={{ display: \"flex\", gap: 20 }}>\n          {[\"Pricing\", \"Features\", \"Privacy\", \"Terms\"].map(l => (\n            <Link key={l} href={`/${l.toLowerCase()}`}\n              style={{ fontSize: 12, color: C.muted, textDecoration: \"none\", fontWeight: 500 }}>\n              {l}\n            </Link>\n          ))}\n        </div>\n      </div>\n    </footer>\n  );\n}\n\n// ─── Main ─────────────────────────────────────────────────────────────────────\nexport default function HomePage() {\n  return (\n    <div style={{ background: C.bg, fontFamily: \"'Plus Jakarta Sans', -apple-system, system-ui, sans-serif\", overflowX: \"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700;1,800;1,900&display=swap');\n        *{box-sizing:border-box;margin:0;padding:0;}\n        html{scroll-behavior:smooth;}\n      `}</style>\n      <Nav />\n      <Hero />\n      <SocialProof />\n      <Features />\n      <PricingPreview />\n      <FinalCTA />\n      <Footer />\n    </div>\n  );\n}\n","frontend/src/components/kai/KIROChat.tsx":"\"use client\";\n/**\n * KIROChat — DropOS Commerce AI\n * Fresh build. No legacy. Clean design system.\n *\n * DESIGN: \"Warm Precision\"\n * Light default: Linen #F7F6F3 → Ink #111827, Violet #7C3AED accent\n * Dark:          Obsidian #0D0D14 → Snow #F9F8FF, same accent\n * Font: Geist (display) + Inter (body) — loaded from CDN\n *\n * LAYOUT: Column flex, height:100%, minHeight:0 everywhere.\n * No absolute positioning in the main flow.\n * KIRO_ACTION: buffered server-side, stripped client-side.\n */\n\nimport React, { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api, uploadAPI } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\n\n// ── constants ──────────────────────────────────────────────────────────────────\nconst BASE   = process.env.NEXT_PUBLIC_API_URL || \"\";\nconst ACCENT = \"#7C3AED\";\nconst ACCENT_D = \"#5B21B6\";\n\n\n// ── Suggestion card icon — monochrome SVG ─────────────────────\nconst SUGGESTION_ICONS: Record<string,string> = {\n  pulse:  \"M3 12h4l3-9 4 18 3-9h4\",\n  trend:  \"M22 7l-9.5 9.5-5-5L1 17\",\n  import: \"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3\",\n  flash:  \"M13 2L3 14h9l-1 8 10-12h-9z\",\n  ad:     \"M12 20h9M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\",\n  growth: \"M18 20V10M12 20V4M6 20v-6\",\n  default:\"M12 5v14M5 12h14\",\n};\nfunction SuggestionIcon({ id, color }: { id: string; color: string }) {\n  const d = SUGGESTION_ICONS[id] || SUGGESTION_ICONS.default;\n  const isFill = id === \"flash\";\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill={isFill ? color : \"none\"}\n      stroke={isFill ? \"none\" : color} strokeWidth=\"1.75\" strokeLinecap=\"round\" strokeLinejoin=\"round\"\n      style={{ display:\"block\", marginBottom:6, opacity:0.65 }}>\n      <path d={d}/>\n    </svg>\n  );\n}\n\n// ── types ──────────────────────────────────────────────────────────────────────\ntype Mode = \"light\" | \"dark\";\ninterface Msg {\n  id:         string;\n  role:       \"user\" | \"assistant\";\n  content:    string;\n  streaming?: boolean;\n  imageUrl?:  string;\n  actions?:   Action[];\n  ts?:        string;\n  thumbs?:    \"up\" | \"down\";\n}\ninterface Action {\n  type:     string;\n  payload:  Record<string,unknown>;\n  approved?: boolean;\n}\n\n// ── theme tokens ───────────────────────────────────────────────────────────────\nconst T = {\n  light: {\n    bg:       \"#F7F6F3\",\n    surface:  \"#FFFFFF\",\n    elevated: \"#F0EFE9\",\n    border:   \"rgba(0,0,0,0.08)\",\n    borderFocus: ACCENT + \"60\",\n    text:     \"#111827\",\n    sub:      \"#6B7280\",\n    muted:    \"#9CA3AF\",\n    accent:   ACCENT,\n    accentD:  ACCENT_D,\n    accentBg: ACCENT + \"12\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.06), 0 4px 20px rgba(0,0,0,0.04)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.10)\",\n    green:    \"#059669\",\n    amber:    \"#D97706\",\n    red:      \"#DC2626\",\n    scrollbar: \"rgba(0,0,0,0.12)\",\n  },\n  dark: {\n    bg:       \"#0D0D14\",\n    surface:  \"#13131F\",\n    elevated: \"#1A1A2A\",\n    border:   \"rgba(255,255,255,0.07)\",\n    borderFocus: ACCENT + \"70\",\n    text:     \"#F9F8FF\",\n    sub:      \"#A0A0C0\",\n    muted:    \"#606080\",\n    accent:   \"#9061F9\",\n    accentD:  ACCENT,\n    accentBg: ACCENT + \"18\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.4)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.5)\",\n    green:    \"#10B981\",\n    amber:    \"#F59E0B\",\n    red:      \"#F87171\",\n    scrollbar: \"rgba(255,255,255,0.1)\",\n  },\n};\n\n// ── clean KIRO_ACTION from text ────────────────────────────────────────────────\nfunction cleanText(raw: string): string {\n  if (!raw) return \"\";\n  let result = \"\";\n  let i = 0;\n  while (i < raw.length) {\n    const markerIdx = raw.indexOf(\"KIRO_ACTION\", i);\n    if (markerIdx === -1) { result += raw.slice(i); break; }\n    result += raw.slice(i, markerIdx);\n    let j = markerIdx + 11;\n    while (j < raw.length && /[\\s:`]/.test(raw[j])) j++;\n    if (j < raw.length && raw[j] === \"{\") {\n      let depth = 0;\n      while (j < raw.length) {\n        if (raw[j] === \"{\") depth++;\n        else if (raw[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n        j++;\n      }\n      while (j < raw.length && (raw[j] === \"\\n\" || raw[j] === \"`\" || raw[j] === \" \")) j++;\n    }\n    i = j;\n  }\n  return result\n    .replace(/```json[\\s\\S]*?```/gi, \"\")\n    .replace(/```[\\s\\S]*?```/g, \"\")\n    .replace(/\\*\\*([^*]+)\\*\\*/g, \"$1\")\n    .replace(/\\*([^*\\n]+)\\*/g, \"$1\")\n    .replace(/^#{1,6}\\s/gm, \"\")\n    .replace(/━+/g, \"\").replace(/^[-=]{3,}\\s*$/gm, \"\")\n    .replace(/\\n{3,}/g, \"\\n\\n\").trim();\n}\n\n// ── parse actions from text ────────────────────────────────────────────────────\nfunction parseActions(text: string): Action[] {\n  const actions: Action[] = [];\n  const re = /KIRO_ACTION\\s*:?\\s*/g;\n  let match: RegExpExecArray | null;\n  while ((match = re.exec(text)) !== null) {\n    const start = text.indexOf(\"{\", match.index + match[0].length);\n    if (start === -1) continue;\n    let depth = 0, j = start;\n    while (j < text.length) {\n      if (text[j] === \"{\") depth++;\n      else if (text[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n      j++;\n    }\n    try {\n      const obj = JSON.parse(text.slice(start, j));\n      if (obj.type) actions.push({ type: obj.type, payload: obj.payload || obj });\n    } catch {}\n  }\n  return actions;\n}\n\n// ── action card labels ─────────────────────────────────────────────────────────\nconst ACTION_META: Record<string, { icon: string; label: string; cta: string }> = {\n  add_product:           { icon:\"\", label:\"Add product\",         cta:\"Add to store\"    },\n  import_from_url:       { icon:\"\", label:\"Import product\",      cta:\"Import\"          },\n  update_price:          { icon:\"\", label:\"Update price\",        cta:\"Update\"          },\n  update_stock:          { icon:\"\", label:\"Update stock\",        cta:\"Update\"          },\n  create_coupon:         { icon:\"\", label:\"Create coupon\",       cta:\"Create\"          },\n  create_coupon_v2:      { icon:\"\", label:\"Create coupon\",       cta:\"Create\"          },\n  fulfill_order:         { icon:\"\", label:\"Fulfill order\",       cta:\"Fulfill\"         },\n  update_order_status:   { icon:\"\", label:\"Update order\",        cta:\"Update\"          },\n  create_flash_sale:     { icon:\"\", label:\"Flash sale\",          cta:\"Launch\"          },\n  archive_product:       { icon:\"\", label:\"Archive product\",     cta:\"Archive\"         },\n  delete_product:        { icon:\"\", label:\"Delete product\",      cta:\"Delete\"          },\n  duplicate_product:     { icon:\"\", label:\"Duplicate product\",   cta:\"Duplicate\"       },\n  add_tracking:          { icon:\"\", label:\"Add tracking\",        cta:\"Add\"             },\n  process_refund:        { icon:\"\", label:\"Process refund\",      cta:\"Refund\"          },\n  send_email:            { icon:\"\", label:\"Send email\",          cta:\"Send\"            },\n  send_whatsapp:         { icon:\"\", label:\"Send WhatsApp\",       cta:\"Send\"            },\n  bulk_update_prices:    { icon:\"\", label:\"Bulk price update\",   cta:\"Update all\"      },\n  update_store_description:{ icon:\"\", label:\"Update store\",     cta:\"Update\"          },\n  update_product:        { icon:\"\", label:\"Update product\",      cta:\"Save\"            },\n};\n\n// ── Time greeting ──────────────────────────────────────────────────────────────\nfunction getGreeting(name: string) {\n  const h = new Date().getHours();\n  const firstName = name.split(\" \")[0];\n  if (h < 5)  return `Still up, ${firstName}?`;\n  if (h < 12) return `Good morning, ${firstName}.`;\n  if (h < 17) return `Good afternoon, ${firstName}.`;\n  if (h < 21) return `Good evening, ${firstName}.`;\n  return `Late night, ${firstName}.`;\n}\n\n// ── KIRO Logo ──────────────────────────────────────────────────────────────────\nfunction KIROLogo({ size = 28 }: { size?: number }) {\n  return (\n    <div style={{\n      width: size, height: size, borderRadius: Math.round(size * 0.27),\n      background: `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n      display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0,\n      boxShadow: `0 2px 8px ${ACCENT}40`,\n    }}>\n      <svg width={size * 0.44} height={size * 0.44} viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\" fillOpacity={0.95}/>\n      </svg>\n    </div>\n  );\n}\n\n// ── Spinner ────────────────────────────────────────────────────────────────────\nfunction Spinner({ size = 16, color = ACCENT }: { size?: number; color?: string }) {\n  return <div style={{ width: size, height: size, borderRadius: \"50%\", border: `2px solid ${color}30`, borderTopColor: color, animation: \"ks 0.7s linear infinite\", flexShrink: 0 }}/>;\n}\n\n// ── Action card ────────────────────────────────────────────────────────────────\nfunction ActionCard({ action, onApprove, onDismiss, t }: { action: Action; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void; t: typeof T.light }) {\n  const [loading, setLoading] = useState(false);\n  const [done,    setDone]    = useState(false);\n  const meta = ACTION_META[action.type] || { icon:\"\", label: action.type.replace(/_/g,\" \"), cta:\"Run\" };\n  if (done) return null;\n\n  const p = action.payload as any;\n  const summary = p?.name || p?.url?.slice(0,35) || p?.code || p?.trackingNumber || p?.message?.slice(0,40) || p?.status || \"\";\n\n  return (\n    <motion.div initial={{ opacity:0, y:4 }} animate={{ opacity:1, y:0 }}\n      style={{ marginTop: 10, borderRadius: 12, border: `1px solid ${t.border}`, background: t.surface, overflow: \"hidden\" }}>\n      <div style={{ padding: \"10px 14px 8px\", display: \"flex\", alignItems: \"flex-start\", gap: 8 }}>\n        <span style={{ fontSize: 18, flexShrink: 0, lineHeight: 1 }}>{meta.icon}</span>\n        <div style={{ flex: 1, minWidth: 0 }}>\n          <p style={{ fontSize: 12, fontWeight: 600, color: t.text, margin: 0 }}>{meta.label}</p>\n          {summary && <p style={{ fontSize: 11, color: t.sub, margin: \"2px 0 0\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{summary}</p>}\n        </div>\n      </div>\n      <div style={{ padding: \"0 14px 12px\", display: \"flex\", gap: 8 }}>\n        <button\n          onClick={async () => { setLoading(true); await onApprove(action); setDone(true); setLoading(false); }}\n          disabled={loading}\n          style={{ padding: \"6px 16px\", borderRadius: 8, border: \"none\", background: t.accent, color: \"#fff\", fontSize: 12, fontWeight: 600, cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 5 }}>\n          {loading ? <Spinner size={12} color=\"#fff\"/> : meta.cta}\n        </button>\n        <button onClick={() => { onDismiss(action); setDone(true); }}\n          style={{ padding: \"6px 12px\", borderRadius: 8, border: `1px solid ${t.border}`, background: \"transparent\", color: t.sub, fontSize: 12, cursor: \"pointer\" }}>\n          Dismiss\n        </button>\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Message bubble ─────────────────────────────────────────────────────────────\nfunction MsgBubble({ msg, onApprove, onDismiss, onRate, onRegen, onPin, isPinned, onEdit, t }: {\n  msg: Msg; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void;\n  onRate:(id:string,v:\"up\"|\"down\")=>void; onRegen:(id:string)=>void;\n  onPin:(id:string)=>void; isPinned:boolean; onEdit:(id:string,txt:string)=>void;\n  t: typeof T.light;\n}) {\n  const [show, setShow] = useState(false);\n  const isUser = msg.role === \"user\";\n  const text   = cleanText(msg.content || \"\");\n\n  return (\n    <motion.div\n      initial={{ opacity: 0, y: 6 }}\n      animate={{ opacity: 1, y: 0 }}\n      transition={{ duration: 0.2 }}\n      onMouseEnter={() => setShow(true)}\n      onMouseLeave={() => setShow(false)}\n      style={{ display: \"flex\", flexDirection: isUser ? \"row-reverse\" : \"row\", gap: 8, alignItems: \"flex-end\", marginBottom: 20, position: \"relative\" }}>\n\n      {!isUser && <KIROLogo size={26}/>}\n\n      <div style={{ maxWidth: \"80%\", minWidth: 0 }}>\n        {/* Image */}\n        {msg.imageUrl && (\n          <img src={msg.imageUrl} alt=\"\" style={{ maxWidth: \"100%\", maxHeight: 200, borderRadius: 10, marginBottom: 6, display: \"block\", objectFit: \"cover\" }} onError={e=>(e.currentTarget.style.display=\"none\")}/>\n        )}\n\n        {/* Text bubble */}\n        <div style={{\n          padding: isUser ? \"10px 15px\" : \"0\",\n          borderRadius: isUser ? \"18px 18px 4px 18px\" : \"0\",\n          background: isUser ? t.userBg : \"transparent\",\n          color: isUser ? t.userText : t.text,\n          fontSize: 14, lineHeight: 1.7,\n          boxShadow: isUser ? `0 2px 10px ${ACCENT}30` : \"none\",\n        }}>\n          {msg.streaming && !msg.content ? (\n            <div style={{ display:\"flex\", gap:4, alignItems:\"center\", padding:\"3px 0\" }}>\n              {[0,1,2].map(i=>(\n                <motion.div key={i} style={{ width:5, height:5, borderRadius:\"50%\", background: t.muted }}\n                  animate={{ y:[0,-4,0], opacity:[0.4,1,0.4] }}\n                  transition={{ duration:0.6, repeat:Infinity, delay:i*0.13 }}/>\n              ))}\n              <span style={{ fontSize:12, color: t.muted, marginLeft:6 }}>KIRO is thinking</span>\n            </div>\n          ) : (\n            <span style={{ whiteSpace: \"pre-wrap\", wordBreak: \"break-word\" }}>\n              {text}\n              {msg.streaming && <motion.span animate={{ opacity:[1,0] }} transition={{ duration:0.5, repeat:Infinity }} style={{ display:\"inline-block\", marginLeft:1 }}>▋</motion.span>}\n            </span>\n          )}\n\n          {/* Action cards */}\n          {!isUser && msg.actions?.map((a,i) => (\n            <ActionCard key={i} action={a} onApprove={onApprove} onDismiss={onDismiss} t={t}/>\n          ))}\n        </div>\n\n        {/* Toolbar */}\n        <AnimatePresence>\n          {show && !msg.streaming && (\n            <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n              style={{ display:\"flex\", gap:3, marginTop:5, padding:\"0 2px\" }}>\n              {[\"📋\",\"👍\",\"👎\",\"↻\",\"🔊\"].map((icon, i) => (\n                <button key={i} title={[\"Copy\",\"Helpful\",\"Not helpful\",\"Retry\",\"Listen\"][i]}\n                  onClick={() => {\n                    if (i===0) navigator.clipboard.writeText(text);\n                    if (i===1) onRate(msg.id,\"up\");\n                    if (i===2) onRate(msg.id,\"down\");\n                    if (i===3) onRegen(msg.id);\n                    if (i===4) { const u = new SpeechSynthesisUtterance(text.slice(0,500)); u.lang=\"en-NG\"; window.speechSynthesis.speak(u); }\n                  }}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color: t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {icon}\n                </button>\n              ))}\n              {/* Pin */}\n              <button title={isPinned?\"Unpin\":\"Pin message\"} onClick={()=>onPin(msg.id)}\n                style={{ width:24, height:24, borderRadius:6, border:`1px solid ${isPinned?t.accent:t.border}`, background:isPinned?`${t.accent}18`:t.surface, color:isPinned?t.accent:t.sub, cursor:\"pointer\", fontSize:11, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                📌\n              </button>\n              {/* Edit (user messages only) */}\n              {isUser && (\n                <button title=\"Edit message\" onClick={()=>onEdit(msg.id,text)}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background:t.surface, color:t.sub, cursor:\"pointer\", fontSize:11, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  ✏️\n                </button>\n              )}\n              {!isUser && (\n                <button title=\"Share to WhatsApp\"\n                  onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(text.slice(0,500))}`, \"_blank\")}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color:\"#25D366\", cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📤\n                </button>\n              )}\n            </motion.div>\n          )}\n        </AnimatePresence>\n\n        {/* Timestamp */}\n        {msg.ts && !msg.streaming && (\n          <p style={{ fontSize:10, color: t.muted, margin:\"3px 0 0\", textAlign: isUser?\"right\":\"left\" }}>\n            {new Date(msg.ts).toLocaleTimeString([],{hour:\"2-digit\",minute:\"2-digit\"})}\n            {msg.thumbs && (msg.thumbs===\"up\"?\" · 👍\":\" · 👎\")}\n          </p>\n        )}\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Welcome screen ─────────────────────────────────────────────────────────────\nfunction Welcome({ name, storeData, onSend, t }: { name:string; storeData:any; onSend:(m:string)=>void; t: typeof T.light }) {\n  const greeting = getGreeting(name || \"there\");\n  const sym      = storeData?.currencySymbol || \"₦\";\n\n  const QUICK = [\n    { svg:\"M3 3h18v2H3zm0 4h12v2H3zm0 4h18v2H3zm0 4h12v2H3z\", title:\"Store pulse\",       sub:\"Revenue · Health · What needs action\",  prompt:\"Give me my full store summary — revenue, orders, health score, and what I should focus on today.\" },\n    { svg:\"M2 20h20M6 20V10l6-6 6 6v10M9 20v-5h6v5\", title:\"Trending products\", sub:\"Live market research\",                   prompt:\"What products are trending right now in my market this week?\" },\n    { svg:\"M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-4v4l3 3\", title:\"Import product\",    sub:\"Any URL — AliExpress, Temu, Amazon\",     prompt:\"I want to import a product. Paste a link and I'll handle everything.\" },\n    { svg:\"M13 2L3 14h9l-1 8 10-12h-9z\", title:\"Flash sale\",        sub:\"Drive sales right now\",                  prompt:\"Help me set up a flash sale on my best products today.\" },\n    { svg:\"M12 20h9M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z\", title:\"Write ad copy\",     sub:\"TikTok · WhatsApp · Instagram\",          prompt:\"Write high-converting ad copy for my top product across TikTok, WhatsApp, and Instagram.\" },\n    { svg:\"M22 12h-4l-3 9L9 3l-3 9H2\", title:\"Growth plan\",       sub:\"Specific 5-step plan\",                   prompt:\"Give me a specific 5-step plan to grow my store revenue this month based on my current data.\" },\n  ];\n\n  return (\n    <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:\"28px 20px 20px\", overflowY:\"auto\", minHeight:0 }}>\n\n      {/* Orb */}\n      <motion.div initial={{ opacity:0, scale:0.7 }} animate={{ opacity:1, scale:1 }}\n        transition={{ type:\"spring\", stiffness:200, damping:18 }}\n        style={{ marginBottom:22, position:\"relative\" }}>\n        <motion.div animate={{ scale:[1,1.08,1] }} transition={{ duration:3, repeat:Infinity, ease:\"easeInOut\" }}>\n          <KIROLogo size={64}/>\n        </motion.div>\n        <motion.div animate={{ rotate:360 }} transition={{ duration:7, repeat:Infinity, ease:\"linear\" }}\n          style={{ position:\"absolute\", inset:-8, borderRadius:\"50%\", border:`1px dashed ${ACCENT}30` }}>\n          <div style={{ position:\"absolute\", top:-3, left:\"50%\", width:7, height:7, borderRadius:\"50%\", background: ACCENT, boxShadow:`0 0 6px ${ACCENT}`, transform:\"translateX(-50%)\" }}/>\n        </motion.div>\n      </motion.div>\n\n      {/* Greeting */}\n      <motion.div initial={{ opacity:0, y:10 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.1 }}\n        style={{ textAlign:\"center\", marginBottom:24 }}>\n        <h2 style={{ fontSize:22, fontWeight:700, color: t.text, margin:\"0 0 5px\", letterSpacing:\"-0.4px\" }}>\n          {greeting}\n        </h2>\n        <p style={{ fontSize:13, color: t.sub, margin:0 }}>Your commerce AI is ready.</p>\n      </motion.div>\n\n      {/* Store metrics */}\n      {storeData && (\n        <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.15 }}\n          style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", justifyContent:\"center\", marginBottom:24 }}>\n          {[\n            { label:\"Today\", value: storeData.revenueToday > 0 ? `${sym}${storeData.revenueToday.toLocaleString()}` : `${sym}0`, alert: false },\n            { label:\"Pending\", value: String(storeData.pendingOrders||0), alert: storeData.pendingOrders > 0 },\n            { label:\"Health\",  value: storeData.healthScore ? `${storeData.healthScore}/100` : \"–\", alert: false },\n          ].map(m => (\n            <div key={m.label} style={{ padding:\"7px 14px\", borderRadius:9, background: t.surface, border:`1px solid ${m.alert ? t.amber+\"40\" : t.border}`, boxShadow: m.alert ? `0 0 10px ${t.amber}18` : \"none\" }}>\n              <p style={{ fontSize:13, fontWeight:700, color: m.alert ? t.amber : t.accent, margin:0 }}>{m.value}</p>\n              <p style={{ fontSize:9, color: t.muted, margin:0, textTransform:\"uppercase\", letterSpacing:\"0.08em\", fontWeight:600 }}>{m.label}</p>\n            </div>\n          ))}\n        </motion.div>\n      )}\n\n      {/* Quick actions */}\n      <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.2 }}\n        style={{ width:\"100%\", maxWidth:480 }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:8, marginBottom:12 }}>\n          {QUICK.map((q,i) => (\n            <motion.button key={q.title}\n              initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.22+i*0.05 }}\n              whileHover={{ y:-2, transition:{ duration:0.12 } }} whileTap={{ scale:0.97 }}\n              onClick={() => onSend(q.prompt)}\n              style={{ padding:\"11px 10px\", borderRadius:11, border:`1px solid ${t.border}`, background: t.surface, cursor:\"pointer\", textAlign:\"left\", boxShadow: t.shadow }}>\n              <SuggestionIcon id={q.icon} color={t.sub}/>\n              <span style={{ fontSize:11, fontWeight:600, color: t.text, display:\"block\", lineHeight:1.3 }}>{q.title}</span>\n              <span style={{ fontSize:10, color: t.sub, display:\"block\", lineHeight:1.4, marginTop:1 }}>{q.sub}</span>\n            </motion.button>\n          ))}\n        </div>\n      </motion.div>\n\n      {/* Pending orders urgent card */}\n      {storeData?.pendingOrders > 0 && (\n        <motion.button initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.6 }}\n          whileHover={{ y:-1 }} whileTap={{ scale:0.98 }}\n          onClick={() => onSend(`Help me fulfill my ${storeData.pendingOrders} pending orders right now.`)}\n          style={{ width:\"100%\", maxWidth:480, padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.amber}35`, background:`${t.amber}0A`, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", gap:10 }}>\n          <span style={{ fontSize:18 }}>📬</span>\n          <div style={{ flex:1, textAlign:\"left\" }}>\n            <p style={{ fontSize:13, fontWeight:600, color: t.amber, margin:0 }}>{storeData.pendingOrders} unfulfilled order{storeData.pendingOrders>1?\"s\":\"\"}</p>\n            <p style={{ fontSize:11, color:`${t.amber}90`, margin:0 }}>Customers are waiting — tap to act now</p>\n          </div>\n          <span style={{ color: t.amber, opacity:0.6 }}>→</span>\n        </motion.button>\n      )}\n\n      <p style={{ fontSize:11, color: t.muted, margin:\"14px 0 0\", textAlign:\"center\" }}>\n        Paste any product URL · Upload image or PDF · ⌘K\n      </p>\n    </div>\n  );\n}\n\n// ── Props ──────────────────────────────────────────────────────────────────────\ninterface KIROChatProps {\n  storeId?:               string;\n  conversationId?:        string;\n  briefMessage?:          string;\n  className?:             string;\n  onConversationCreated?: (id: string) => void;\n  onFirstMessage?:        (text: string) => void;\n}\n\n// ── Main component ─────────────────────────────────────────────────────────────\nexport default function KIROChat({ storeId: propStoreId, conversationId: initConvId, onConversationCreated, onFirstMessage }: KIROChatProps) {\n  const user    = useAuthStore(s => s.user);\n  const token   = useAuthStore(s => s.accessToken);\n  const storeId = propStoreId || user?.stores?.[0]?.id || \"\";\n\n  // ── state ──────────────────────────────────────────────────────────────────\n  const [mode,      setMode]      = useState<Mode>(\"light\");\n  const [messages,  setMessages]  = useState<Msg[]>([]);\n  const [input,     setInput]     = useState(\"\");\n  const [loading,   setLoading]   = useState(false);\n  const [convId,    setConvId]    = useState(initConvId || \"\");\n  const [storeData, setStoreData] = useState<any>(null);\n  const [attach,    setAttach]    = useState<any>(null);\n  const [uploading, setUploading] = useState(false);\n  const [listening, setListening] = useState(false);\n  const [voiceInterim, setVoiceInterim] = useState(\"\");\n  const [rateLimit,    setRateLimit]    = useState(false);\n  const [showSearch,   setShowSearch]   = useState(false);\n  const [searchQuery,  setSearchQuery]  = useState(\"\");\n  const [pinnedMsgs,   setPinnedMsgs]   = useState<string[]>([]);\n  const [showPinned,   setShowPinned]   = useState(false);\n  const [showScrollBtn,setShowScrollBtn]= useState(false);\n  const [editingId,    setEditingId]    = useState<string|null>(null);\n  const [editText,     setEditText]     = useState(\"\");\n  const [slashMenu,    setSlashMenu]    = useState(false);\n  const [suggestions,  setSuggestions]  = useState<string[]>([]);\n\n  const bottomRef = useRef<HTMLDivElement>(null);\n  const inputRef  = useRef<HTMLTextAreaElement>(null);\n  const abortRef  = useRef<AbortController | null>(null);\n  const fileRef   = useRef<HTMLInputElement>(null);\n  const recogRef   = useRef<any>(null);\n  const msgListRef  = useRef<HTMLDivElement>(null);\n  const searchRef   = useRef<HTMLInputElement>(null);\n\n  const t = T[mode];\n\n  // ── sync mode from localStorage ────────────────────────────────────────────\n  useEffect(() => {\n    const saved = localStorage.getItem(\"kiro-mode\") as Mode | null;\n    if (saved) setMode(saved);\n    const handler = () => { const m = localStorage.getItem(\"kiro-mode\") as Mode|null; if (m) setMode(m); };\n    window.addEventListener(\"storage\", handler);\n    return () => window.removeEventListener(\"storage\", handler);\n  }, []);\n\n  // ── auto scroll ────────────────────────────────────────────────────────────\n  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior:\"smooth\" }); }, [messages]);\n\n  // ── load store greeting ────────────────────────────────────────────────────\n  useEffect(() => {\n    if (!storeId) return;\n    api.get(`/kai/greeting?storeId=${storeId}`)\n      .then(r => setStoreData(r.data?.data?.storeContext || r.data?.data))\n      .catch(() => {});\n  }, [storeId]);\n\n  // ── load conversation history ──────────────────────────────────────────────\n  useEffect(() => {\n    if (!initConvId) return;\n    api.get(`/kai/conversation/${initConvId}`)\n      .then(r => {\n        const msgs = (r.data?.data?.messages || []).map((m: any) => ({\n          id: m.id, role: m.role === \"user\" ? \"user\" : \"assistant\",\n          content: m.content, ts: m.createdAt, actions: m.actions || [],\n        }));\n        if (msgs.length) setMessages(msgs);\n      }).catch(() => {});\n  }, [initConvId]);\n\n  // ── keyboard shortcuts ─────────────────────────────────────────────────────\n  useEffect(() => {\n    const handler = (e: KeyboardEvent) => {\n      if ((e.metaKey||e.ctrlKey) && e.key===\"k\") { e.preventDefault(); setShowSearch(s=>!s); setTimeout(()=>searchRef.current?.focus(),80); }\n      if (e.key===\"Escape\") { setShowSearch(false); setSlashMenu(false); setEditingId(null); }\n    };\n    window.addEventListener(\"keydown\", handler);\n    return () => window.removeEventListener(\"keydown\", handler);\n  }, []);\n\n  // ── scroll-to-bottom detector ──────────────────────────────────────────────\n  useEffect(() => {\n    const el = msgListRef.current;\n    if (!el) return;\n    const handler = () => setShowScrollBtn(el.scrollHeight - el.scrollTop - el.clientHeight > 120);\n    el.addEventListener(\"scroll\", handler);\n    return () => el.removeEventListener(\"scroll\", handler);\n  }, []);\n\n  // ── smart follow-up suggestions after KIRO responds ───────────────────────\n  useEffect(() => {\n    const last = messages[messages.length-1];\n    if (!last || last.role !== \"assistant\" || last.streaming) { setSuggestions([]); return; }\n    const t = last.content.toLowerCase();\n    if (t.includes(\"product\") || t.includes(\"import\"))\n      setSuggestions([\"Write ad copy for this\",\"Set a price for it\",\"Find similar products\"]);\n    else if (t.includes(\"order\") || t.includes(\"fulfill\"))\n      setSuggestions([\"How do I contact the supplier?\",\"Mark as fulfilled\",\"Show pending orders\"]);\n    else if (t.includes(\"revenue\") || t.includes(\"sales\") || t.includes(\"analytics\"))\n      setSuggestions([\"What should I focus on today?\",\"Which products are top sellers?\",\"Create a flash sale\"]);\n    else if (t.includes(\"ad\") || t.includes(\"copy\") || t.includes(\"tiktok\"))\n      setSuggestions([\"Make a WhatsApp version\",\"Make it shorter\",\"Generate an image for it\"]);\n    else\n      setSuggestions([]);\n  }, [messages]);\n\n  // ── voice ──────────────────────────────────────────────────────────────────\n  const handleVoice = () => {\n    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SR) { toast.error(\"Voice works best in Chrome or Edge\"); return; }\n    if (listening) {\n      recogRef.current?.stop();\n      setListening(false);\n      setVoiceInterim(\"\");\n      return;\n    }\n    const r = new SR();\n    r.lang = \"en-NG\";\n    r.interimResults = true;\n    r.continuous = true;\n    r.onresult = (e: any) => {\n      let interim = \"\";\n      let final   = \"\";\n      for (let i = e.resultIndex; i < e.results.length; i++) {\n        const t = e.results[i][0].transcript;\n        if (e.results[i].isFinal) final += t;\n        else interim += t;\n      }\n      // Show live interim in the bubble\n      setVoiceInterim(interim);\n      // Append final text to input\n      if (final) setInput(prev => (prev ? prev + \" \" + final : final).trim());\n    };\n    r.onerror = (e: any) => {\n      if (e.error !== \"aborted\") toast.error(\"Voice error — try again\");\n      setListening(false);\n      setVoiceInterim(\"\");\n    };\n    r.onend = () => { setListening(false); setVoiceInterim(\"\"); };\n    r.start();\n    recogRef.current = r;\n    setListening(true);\n  };\n\n  // ── slash commands ────────────────────────────────────────────────────────\n  const SLASH_CMDS = [\n    // SALES\n    { cmd:\"/flash-sale\",  label:\"⚡ Run Flash Sale\",     prompt:\"Help me launch a flash sale right now. Suggest which products to discount based on inventory and sales velocity, then create the flash sale with optimal pricing.\" },\n    { cmd:\"/discount\",    label:\"🏷️ Create Discount\",    prompt:\"Create a smart discount code. Suggest a code name and discount percentage based on my margins.\" },\n    { cmd:\"/bogo\",        label:\"🎁 BOGO Offer\",          prompt:\"Set up a buy-one-get-one offer. Recommend which products to include for highest profit retention.\" },\n\n    // PRODUCTS\n    { cmd:\"/import\",      label:\"📥 Import Product\",      prompt:\"I want to import a product. Paste the URL:\" },\n    { cmd:\"/audit\",       label:\"🔍 Product Audit\",       prompt:\"Audit all my products. Find: 1) products with no images 2) products with no description 3) products with prices that look wrong 4) products with low inventory. Suggest fixes.\" },\n    { cmd:\"/rewrite\",     label:\"✏️ Rewrite Descriptions\", prompt:\"Review my products and identify which descriptions need improvement. For each, write a better version that converts Nigerian buyers.\" },\n    { cmd:\"/price-check\", label:\"💰 Price Audit\",         prompt:\"Audit my product prices. For each, tell me if it's too high, too low, or just right for the Nigerian market. Suggest specific price changes.\" },\n\n    // MARKETING\n    { cmd:\"/whatsapp\",    label:\"💬 WhatsApp Broadcast\",  prompt:\"Help me write a WhatsApp broadcast. Suggest the best message type right now (promo, restock, abandoned cart, win-back).\" },\n    { cmd:\"/email\",       label:\"📧 Email Campaign\",      prompt:\"Create an email campaign for my customers. Pick the best campaign type for right now and write the full email.\" },\n    { cmd:\"/abandoned\",   label:\"🛒 Recover Carts\",       prompt:\"Check my abandoned carts. Show how many, total value at risk, and send recovery messages.\" },\n    { cmd:\"/instagram\",   label:\"📸 Instagram Caption\",   prompt:\"Write me an Instagram caption with Nigerian hashtags for:\" },\n    { cmd:\"/tiktok\",      label:\"🎬 TikTok Script\",       prompt:\"Write a viral TikTok script for Nigerian audience. Hook in 3 seconds, fast cuts, CTA. Product:\" },\n    { cmd:\"/ad\",          label:\"📢 Ad Copy\",             prompt:\"Write high-converting Facebook/Instagram ad copy for my top product.\" },\n\n    // ANALYTICS\n    { cmd:\"/insights\",    label:\"📊 Store Insights\",      prompt:\"Give me a complete insights report on my store right now: top performers, what needs attention, what's growing, what's dying, and 3 specific actions I should take today.\" },\n    { cmd:\"/trending\",    label:\"🔥 Trending Products\",   prompt:\"Show me what's trending in Nigeria right now. Categories with high demand, products selling fast on Jumia/Konga/TikTok Shop, seasonal opportunities.\" },\n    { cmd:\"/forecast\",    label:\"📈 Sales Forecast\",      prompt:\"Forecast my sales for the next 30 days. Predicted revenue, predicted orders, what's likely to drive growth, what could slow it down.\" },\n    { cmd:\"/plan\",        label:\"🚀 Growth Plan\",         prompt:\"Give me a 5-step plan to grow my store this month, specific to my current situation.\" },\n\n    // OPERATIONS\n    { cmd:\"/fulfill\",     label:\"📦 Fulfill Orders\",      prompt:\"Show me all unfulfilled orders. For each, prepare the fulfillment. I'll approve and you process.\" },\n    { cmd:\"/refund\",      label:\"↩️ Process Refund\",     prompt:\"Help me process a refund. Order ID or customer name:\" },\n    { cmd:\"/stock\",       label:\"📋 Stock Check\",         prompt:\"Check my inventory. Show low stock, items needing reorder, and overstocked items. Suggest restock actions.\" },\n    { cmd:\"/orders\",      label:\"📑 Pending Orders\",      prompt:\"Show me all pending orders that need action.\" },\n    { cmd:\"/research\",    label:\"🌍 Market Research\",     prompt:\"What products are trending in my market this week?\" },\n  ];\n\n  // ── file upload ────────────────────────────────────────────────────────────\n  const handleFile = async (file: File) => {\n    if (file.size > 20 * 1024 * 1024) { toast.error(\"Max 20MB\"); return; }\n    setUploading(true);\n    try {\n      const dataUrl = await new Promise<string>((res, rej) => {\n        const r = new FileReader(); r.onload=()=>res(r.result as string); r.onerror=rej; r.readAsDataURL(file);\n      });\n      const isImage = file.type.startsWith(\"image/\");\n      const isPDF   = file.type === \"application/pdf\";\n      setAttach({ url: isImage ? dataUrl : undefined, base64: isPDF ? dataUrl.split(\",\")[1] : undefined, type: isImage ? \"image\" : isPDF ? \"pdf\" : \"csv\", name: file.name, size: file.size });\n    } catch { toast.error(\"Upload failed\"); } finally { setUploading(false); }\n  };\n\n  // ── image generation ───────────────────────────────────────────────────────\n  const generateImage = useCallback((prompt: string) => {\n    const kid = `k${Date.now()}`;\n    const clean = prompt.replace(/^(generate|create|make|draw)\\s+(a[n]?\\s+)?(image|photo|picture|visual)\\s+(of\\s+|for\\s+)?/i,\"\").trim();\n    const encoded = encodeURIComponent(`${clean}, product photography, clean background, professional, high quality`);\n    const url = `https://image.pollinations.ai/prompt/${encoded}?width=768&height=768&seed=${Math.random()*9999|0}&nologo=true&model=flux`;\n    setMessages(p => [...p, { id:kid, role:\"assistant\", content:`Generating image for \"${clean}\"…`, streaming:true, ts:new Date().toISOString() }]);\n    const img = new Image();\n    img.onload  = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:`Here's your image.`, imageUrl:url } : m));\n    img.onerror = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:\"Image generation unavailable. Try describing the product to me instead.\" } : m));\n    img.src = url;\n  }, []);\n\n  // ── send ───────────────────────────────────────────────────────────────────\n  const send = useCallback(async (override?: string) => {\n    const text = (override || input).trim();\n    if ((!text && !attach) || loading || !storeId) return;\n\n    // Image gen intercept\n    if (text && /^(generate|create|make|draw|show)\\s+(a[n]?\\s+)?(image|photo|picture|visual)/i.test(text) && !attach) {\n      setMessages(p => [...p, { id:`u${Date.now()}`, role:\"user\", content:text, ts:new Date().toISOString() }]);\n      if (!override) setInput(\"\");\n      generateImage(text);\n      return;\n    }\n\n    const userMsg: Msg = { id:`u${Date.now()}`, role:\"user\", content: text || (attach ? `📎 ${attach.name}` : \"\"), imageUrl: attach?.type===\"image\" ? attach.url : undefined, ts:new Date().toISOString() };\n    const kiroId = `k${Date.now()}`;\n    const kiroMsg: Msg = { id:kiroId, role:\"assistant\", content:\"\", streaming:true, ts:new Date().toISOString() };\n\n    // Fire onFirstMessage so parent can title the session properly\n    if (messages.length === 0 && onFirstMessage) {\n      onFirstMessage(text || (attach?.name ? `📎 ${attach.name}` : 'New conversation'));\n    }\n\n    setMessages(p => [...p, userMsg, kiroMsg]);\n    if (!override) setInput(\"\");\n    setAttach(null);\n    setLoading(true);\n\n    abortRef.current?.abort();\n    abortRef.current = new AbortController();\n\n    try {\n      const body: any = { message: text || \"\", storeId, conversationId: convId || undefined };\n      if (attach?.type === \"image\" && attach.url?.startsWith(\"data:\")) {\n        body.imageBase64    = attach.url.split(\",\")[1];\n        body.imageMediaType = attach.url.split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n        body.imageUrl       = attach.url;\n      } else if (attach?.url) body.imageUrl = attach.url;\n      if (attach?.base64) { body.fileBase64 = attach.base64; body.fileType = attach.type; }\n      if (attach?.name)   body.fileName = attach.name;\n\n      const res = await fetch(`${BASE}/kai/smart-chat`, {\n        method: \"POST\",\n        headers: { \"Content-Type\":\"application/json\", ...(token ? { Authorization:`Bearer ${token}` } : {}) },\n        body: JSON.stringify(body),\n        signal: abortRef.current.signal,\n      });\n\n      if (!res.ok) {\n        const d = await res.json().catch(()=>({}));\n        if (res.status === 429 || d?.code === \"RATE_LIMIT\") { setRateLimit(true); return; }\n        throw new Error(d?.message || \"Request failed\");\n      }\n\n      const reader = res.body!.getReader();\n      const dec = new TextDecoder();\n      let full = \"\";\n      let newConvId = \"\";\n\n      while (true) {\n        const { done, value } = await reader.read();\n        if (done) break;\n        for (const line of dec.decode(value,{stream:true}).split(\"\\n\").filter(l=>l.startsWith(\"data: \"))) {\n          try {\n            const p = JSON.parse(line.slice(6));\n            if (p.token) { full += p.token; setMessages(m => m.map(x => x.id===kiroId ? {...x,content:full} : x)); }\n            if (p.conversationId && !convId) newConvId = p.conversationId;\n            if (p.actions?.length) setMessages(m => m.map(x => x.id===kiroId ? {...x, actions:[...(x.actions||[]),...p.actions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i)} : x));\n            if (p.done) {\n              if (newConvId) { setConvId(newConvId); onConversationCreated?.(newConvId); }\n              // Parse any inline actions from text\n              const inlineActions = parseActions(full);\n              setMessages(m => m.map(x => x.id===kiroId ? {\n                ...x, streaming:false,\n                actions: [...(x.actions||[]), ...inlineActions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i),\n              } : x));\n            }\n          } catch {}\n        }\n      }\n    } catch (err: any) {\n      if (err.name === \"AbortError\") return;\n      setMessages(m => m.map(x => x.id===kiroId ? {...x, streaming:false, content:\"Something went wrong. Check your connection and try again.\" } : x));\n    } finally { setLoading(false); }\n  }, [input, attach, loading, storeId, convId, token, generateImage, onConversationCreated]);\n\n  // ── action handlers ────────────────────────────────────────────────────────\n  const handleApprove = async (action: Action) => {\n    try {\n      const r = await api.post(\"/kai/action\", { storeId, actions:[{...action,approved:true}] });\n      const result = r.data?.results?.[0];\n      if (result?.success) toast.success(result.message || \"Done!\");\n      else if (result?.healedAction) {\n        toast.loading(\"Auto-fixing…\", {id:\"heal\"});\n        const r2 = await api.post(\"/kai/action\",{storeId,actions:[{...result.healedAction,approved:true}]});\n        const r2res = r2.data?.results?.[0];\n        if (r2res?.success) toast.success(r2res.message||\"Fixed and done!\",{id:\"heal\"});\n        else toast.error(result?.message||\"Action failed\",{id:\"heal\"});\n      } else toast.error(result?.message||\"Action failed\");\n    } catch (e: any) { toast.error(e.response?.data?.message||\"Failed\"); }\n  };\n\n  const handleRate = (id: string, v: \"up\"|\"down\") => {\n    setMessages(m => m.map(x => x.id===id ? {...x,thumbs:v} : x));\n  };\n\n  const handleRegen = async (id: string) => {\n    const idx = messages.findIndex(m => m.id===id);\n    if (idx < 1) return;\n    const prev = messages.slice(0,idx).reverse().find(m=>m.role===\"user\");\n    if (prev) { setMessages(m=>m.filter((_,i)=>i<idx)); send(prev.content); }\n  };\n\n  // ── render ─────────────────────────────────────────────────────────────────\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", minHeight:0, background: t.bg, fontFamily:\"'Inter',system-ui,sans-serif\", overflow:\"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n        @keyframes ks { to { transform: rotate(360deg); } }\n        @keyframes voiceBar { 0%,100%{transform:scaleY(1);opacity:.5} 50%{transform:scaleY(2);opacity:1} }\n        * { box-sizing: border-box; }\n        ::-webkit-scrollbar { width: 4px; }\n        ::-webkit-scrollbar-thumb { background: ${t.scrollbar}; border-radius: 2px; }\n      `}</style>\n\n      {/* Rate limit screen */}\n      {rateLimit ? (\n        <div style={{ flex:1, minHeight:0, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:32, textAlign:\"center\" }}>\n          <div style={{ fontSize:48, marginBottom:16 }}>🔥</div>\n          <h2 style={{ fontSize:20, fontWeight:700, color:t.text, margin:\"0 0 8px\" }}>You've hit your limit</h2>\n          <p style={{ fontSize:14, color:t.sub, margin:\"0 0 20px\", maxWidth:280, lineHeight:1.6 }}>\n            Free accounts get 5 KIRO sessions per month. Upgrade to keep going.\n          </p>\n          <button onClick={()=>window.open(\"/dashboard/billing\",\"_blank\")}\n            style={{ padding:\"11px 24px\", borderRadius:10, border:\"none\", background:`linear-gradient(135deg,${t.accent},${t.accentD})`, color:\"#fff\", fontSize:14, fontWeight:600, cursor:\"pointer\" }}>\n            Unlock more sessions\n          </button>\n          <p style={{ fontSize:11, color:t.muted, margin:\"12px 0 0\" }}>Resets on the 1st of every month</p>\n        </div>\n      ) : (\n        <>\n          {/* ── Search bar ── */}\n          {showSearch && (\n            <div style={{ padding:\"8px 14px\", borderBottom:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={t.muted} strokeWidth=\"2\" strokeLinecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n              <input ref={searchRef} value={searchQuery} onChange={e=>setSearchQuery(e.target.value)}\n                placeholder=\"Search conversation…\"\n                style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", fontSize:13, color:t.text, fontFamily:\"inherit\" }}/>\n              {searchQuery && <button onClick={()=>setSearchQuery(\"\")} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:12 }}>✕</button>}\n              <button onClick={()=>{setShowSearch(false);setSearchQuery(\"\");}} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:11 }}>Close</button>\n            </div>\n          )}\n\n          {/* ── Pinned messages panel ── */}\n          {showPinned && pinnedMsgs.length > 0 && (\n            <div style={{ padding:\"10px 14px\", borderBottom:`1px solid ${t.border}`, background:t.surface, maxHeight:140, overflowY:\"auto\", flexShrink:0 }}>\n              <p style={{ fontSize:11, fontWeight:700, color:t.muted, marginBottom:6, textTransform:\"uppercase\", letterSpacing:\"0.07em\" }}>📌 Pinned</p>\n              {messages.filter(m=>pinnedMsgs.includes(m.id)).map(m=>(\n                <div key={m.id} style={{ fontSize:12, color:t.text, padding:\"5px 0\", borderBottom:`1px solid ${t.border}`, lineHeight:1.5 }}>\n                  {cleanText(m.content).slice(0,120)}{m.content.length>120?\"…\":\"\"}\n                </div>\n              ))}\n            </div>\n          )}\n\n          {/* Messages */}\n          <div ref={msgListRef} style={{ flex:1, overflowY:\"auto\", padding:\"20px 16px\", minHeight:0, position:\"relative\" }}>\n            {messages.length === 0 ? (\n              <Welcome name={user?.name||\"there\"} storeData={storeData} onSend={send} t={t}/>\n            ) : (\n              messages\n                .filter(m => !searchQuery || m.content.toLowerCase().includes(searchQuery.toLowerCase()))\n                .map(msg => (\n                <MsgBubble key={msg.id} msg={msg} onApprove={handleApprove}\n                  onDismiss={a=>setMessages(m=>m.map(x=>({...x,actions:(x.actions||[]).filter(b=>b!==a)})))}\n                  onRate={handleRate} onRegen={handleRegen}\n                  onPin={(id)=>setPinnedMsgs(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id])}\n                  isPinned={pinnedMsgs.includes(msg.id)}\n                  onEdit={(id,txt)=>{setEditingId(id);setEditText(txt);inputRef.current?.focus();}}\n                  t={t}/>\n              ))\n            )}\n            <div ref={bottomRef}/>\n          </div>\n\n          {/* ── Scroll to bottom ── */}\n          {showScrollBtn && (\n            <button onClick={()=>bottomRef.current?.scrollIntoView({behavior:\"smooth\"})}\n              style={{ position:\"absolute\", bottom:80, right:18, width:32, height:32, borderRadius:\"50%\", border:`1px solid ${t.border}`, background:t.surface, boxShadow:\"0 2px 10px rgba(0,0,0,0.12)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", zIndex:10, color:t.sub }}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M12 5v14M5 12l7 7 7-7\"/></svg>\n            </button>\n          )}\n\n          {/* ── Smart follow-up suggestions ── */}\n          {suggestions.length > 0 && !loading && (\n            <div style={{ padding:\"8px 14px 4px\", display:\"flex\", gap:6, flexWrap:\"wrap\", flexShrink:0 }}>\n              {suggestions.map(s=>(\n                <button key={s} onClick={()=>{setInput(s);inputRef.current?.focus();}}\n                  style={{ padding:\"5px 11px\", borderRadius:99, border:`1px solid ${t.border}`, background:t.surface, color:t.sub, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\", transition:\"all 0.15s\", whiteSpace:\"nowrap\" }}\n                  onMouseEnter={e=>{e.currentTarget.style.borderColor=t.accent;e.currentTarget.style.color=t.accent;}}\n                  onMouseLeave={e=>{e.currentTarget.style.borderColor=t.border;e.currentTarget.style.color=t.sub;}}>\n                  {s}\n                </button>\n              ))}\n            </div>\n          )}\n\n          {/* Stop bar */}\n          {loading && (\n            <div style={{ padding:\"8px 16px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:10, flexShrink:0 }}>\n              <Spinner size={14} color={t.accent}/>\n              <span style={{ fontSize:12, color:t.sub, flex:1 }}>KIRO is thinking</span>\n              <button onClick={()=>abortRef.current?.abort()}\n                style={{ padding:\"4px 12px\", borderRadius:7, border:`1px solid ${t.border}`, background:\"transparent\", color:t.red, fontSize:12, cursor:\"pointer\" }}>\n                ⏹ Stop\n              </button>\n            </div>\n          )}\n\n          {/* Attachment chip */}\n          <AnimatePresence>\n            {attach && (\n              <motion.div initial={{height:0,opacity:0}} animate={{height:\"auto\",opacity:1}} exit={{height:0,opacity:0}}\n                style={{ padding:\"6px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n                {attach.type===\"image\" && attach.url && (\n                  <img src={attach.url} alt=\"\" style={{ width:32, height:32, borderRadius:6, objectFit:\"cover\" }}/>\n                )}\n                {attach.type!==\"image\" && <span style={{ fontSize:18 }}>{attach.type===\"pdf\"?\"📄\":\"📊\"}</span>}\n                <span style={{ fontSize:12, color:t.sub, flex:1, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{attach.name}</span>\n                <button onClick={()=>setAttach(null)} style={{ width:20, height:20, borderRadius:\"50%\", border:\"none\", background:t.elevated, color:t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>×</button>\n              </motion.div>\n            )}\n          </AnimatePresence>\n\n          {/* ── Slash command menu ── */}\n          {slashMenu && (\n            <div style={{ padding:\"6px 10px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", flexDirection:\"column\", gap:2, flexShrink:0 }}>\n              {SLASH_CMDS.filter(c=>input===\"/\" || c.cmd.includes(input)).map(c=>(\n                <button key={c.cmd} onClick={()=>{setInput(c.prompt);setSlashMenu(false);inputRef.current?.focus();}}\n                  style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"7px 10px\", borderRadius:8, border:\"none\", background:\"transparent\", cursor:\"pointer\", textAlign:\"left\", fontFamily:\"inherit\" }}\n                  onMouseEnter={e=>(e.currentTarget.style.background=t.elevated)}\n                  onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n                  <span style={{ fontSize:11, fontWeight:700, color:t.accent, minWidth:80, fontFamily:\"monospace\" }}>{c.cmd}</span>\n                  <span style={{ fontSize:12, color:t.sub }}>{c.label}</span>\n                </button>\n              ))}\n            </div>\n          )}\n\n          {/* ── Edit mode banner ── */}\n          {editingId && (\n            <div style={{ padding:\"6px 14px\", borderTop:`1px solid ${t.border}`, background:`${t.accent}10`, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={t.accent} strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n              <span style={{ fontSize:12, color:t.accent, flex:1 }}>Editing message</span>\n              <button onClick={()=>{setEditingId(null);setEditText(\"\");setInput(\"\");}} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:11 }}>Cancel</button>\n              <button onClick={()=>{\n                setMessages(m=>m.map(x=>x.id===editingId?{...x,content:input}:x));\n                setEditingId(null); setEditText(\"\"); setInput(\"\");\n              }} style={{ background:t.accent, border:\"none\", color:\"#fff\", cursor:\"pointer\", fontSize:11, padding:\"3px 10px\", borderRadius:6, fontFamily:\"inherit\" }}>Save</button>\n            </div>\n          )}\n\n          {/* Input */}\n          <div style={{ padding:\"10px 14px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, flexShrink:0 }}>\n            <div style={{ borderRadius:14, border:`1px solid ${t.border}`, background:t.bg, overflow:\"hidden\", boxShadow:t.shadow, transition:\"border-color 0.15s, box-shadow 0.15s\" }}\n              onFocusCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.accent;(e.currentTarget as HTMLDivElement).style.boxShadow=`0 0 0 3px ${t.accentBg}`;}}\n              onBlurCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.border;(e.currentTarget as HTMLDivElement).style.boxShadow=t.shadow;}}>\n\n              <textarea ref={inputRef} value={input}\n                onChange={e=>{\n                  const v = e.target.value;\n                  setInput(v);\n                  e.target.style.height=\"auto\";\n                  e.target.style.height=Math.min(e.target.scrollHeight,160)+\"px\";\n                  setSlashMenu(v.startsWith(\"/\") && v.length <= 12);\n                  if (editingId) setEditText(v);\n                }}\n                onKeyDown={e=>{ if(e.key===\"Enter\"&&!e.shiftKey){e.preventDefault();send();} }}\n                onPaste={e=>{ const f=e.clipboardData.files?.[0]; if(f){handleFile(f);} }}\n                placeholder=\"Message KIRO… paste a URL, describe a product, or ask anything\"\n                rows={1} style={{ width:\"100%\", background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:14, lineHeight:1.6, resize:\"none\", padding:\"12px 14px 4px\", maxHeight:160, overflowY:\"auto\" }}/>\n\n              {/* Toolbar row */}\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:4, padding:\"4px 10px 8px\" }}>\n                {/* Image upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*\"; fileRef.current?.click(); }} disabled={uploading} title=\"Upload image\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {uploading ? <Spinner size={12} color={t.accent}/> : \"🖼\"}\n                </button>\n                {/* File upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*,.pdf,.csv\"; fileRef.current?.click(); }} disabled={uploading} title=\"Attach file\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📎\n                </button>\n                {/* Voice — animated bars + live transcript */}\n                <div style={{ position:\"relative\", display:\"flex\", alignItems:\"center\", gap:4 }}>\n                  {listening && voiceInterim && (\n                    <div style={{ position:\"absolute\", bottom:\"calc(100% + 8px)\", right:0, background:t.surface, border:`1px solid ${t.border}`, borderRadius:10, padding:\"7px 12px\", fontSize:12, color:t.text, whiteSpace:\"nowrap\", maxWidth:220, overflow:\"hidden\", textOverflow:\"ellipsis\", boxShadow:t.shadow, zIndex:20, pointerEvents:\"none\" }}>\n                      <span style={{ color:t.muted, fontSize:10, display:\"block\", marginBottom:2 }}>Listening…</span>\n                      {voiceInterim}\n                    </div>\n                  )}\n                  {listening && (\n                    <div style={{ display:\"flex\", alignItems:\"center\", gap:2 }}>\n                      {[0,1,2,3,4].map(i => (\n                        <div key={i} style={{ width:3, height:14, borderRadius:99, background:t.red, animation:`voiceBar 0.6s ease-in-out ${i*0.1}s infinite`, opacity:0.85 }}/>\n                      ))}\n                    </div>\n                  )}\n                  <button onClick={handleVoice} title={listening ? \"Stop recording\" : \"Voice input\"}\n                    style={{ width:30, height:30, borderRadius:8, border:`1px solid ${listening ? t.red : t.border}`, background:listening ? `${t.red}15` : \"transparent\", color:listening ? t.red : t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.2s\", flexShrink:0 }}>\n                    {listening\n                      ? <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/></svg>\n                      : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"/><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"/><line x1=\"8\" y1=\"23\" x2=\"16\" y2=\"23\"/></svg>\n                    }\n                  </button>\n                </div>\n                {/* Search */}\n                <button onClick={()=>{setShowSearch(s=>!s);setTimeout(()=>searchRef.current?.focus(),80);}} title=\"Search chat (⌘K)\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:showSearch?`${t.accent}15`:\"transparent\", color:showSearch?t.accent:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n                </button>\n                {/* Pinned */}\n                {pinnedMsgs.length > 0 && (\n                  <button onClick={()=>setShowPinned(p=>!p)} title=\"Pinned messages\"\n                    style={{ width:28, height:28, borderRadius:7, border:\"none\", background:showPinned?`${t.accent}15`:\"transparent\", color:showPinned?t.accent:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", position:\"relative\" }}>\n                    <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                    <span style={{ position:\"absolute\", top:2, right:2, width:7, height:7, borderRadius:\"50%\", background:t.accent, fontSize:8, color:\"#fff\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>{pinnedMsgs.length}</span>\n                  </button>\n                )}\n                {/* Export */}\n                <button title=\"Export conversation\"\n                  onClick={()=>{\n                    const txt = messages.map(m=>`${m.role===\"user\"?\"You\":\"KIRO\"}: ${cleanText(m.content)}`).join(\"\\n\\n\");\n                    const blob = new Blob([txt],{type:\"text/plain\"});\n                    const a = document.createElement(\"a\"); a.href=URL.createObjectURL(blob); a.download=\"kiro-chat.txt\"; a.click();\n                  }}\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n                </button>\n                {/* Generate image */}\n                <button onClick={()=>input.trim()?generateImage(input.trim()):toast.error(\"Describe what to generate\")} title=\"Generate AI image\"\n                  style={{ padding:\"3px 8px\", borderRadius:6, border:`1px solid ${t.border}`, background:\"transparent\", color:t.accent, cursor:\"pointer\", fontSize:11, fontWeight:600 }}>\n                  ✨ Image\n                </button>\n\n                <div style={{ flex:1 }}/>\n\n                {input.length > 300 && (\n                  <span style={{ fontSize:10, color:t.muted }}>{input.length}</span>\n                )}\n\n                {/* Send / stop */}\n                <motion.button onClick={()=>loading?abortRef.current?.abort():send()} whileTap={{scale:0.9}}\n                  style={{ width:32, height:32, borderRadius:9, border:\"none\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.18s\",\n                    background:loading?\"rgba(220,38,38,0.12)\":(input.trim()||attach)?`linear-gradient(135deg,${t.accent},${t.accentD})`:`${t.accent}18`,\n                    boxShadow:(input.trim()||attach)&&!loading?`0 2px 10px ${t.accent}35`:\"none\" }}>\n                  {loading\n                    ? <Spinner size={12} color={t.red}/>\n                    : <svg width={13} height={13} viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z\" stroke={(input.trim()||attach)?\"#fff\":t.accent} strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>}\n                </motion.button>\n              </div>\n            </div>\n\n            <p style={{ fontSize:10, color:t.muted, textAlign:\"center\", margin:\"6px 0 0\" }}>\n              Powered by DropOS\n            </p>\n          </div>\n        </>\n      )}\n\n      <input ref={fileRef} type=\"file\" accept=\"image/*,.pdf,.csv\" style={{ display:\"none\" }}\n        onChange={e=>{ if(e.target.files?.[0]) handleFile(e.target.files[0]); e.target.value=\"\"; }}/>\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('  ✓',rel.split('/').slice(-2).join('/'));}
try{execSync('git add .',{stdio:'inherit'});const st=execSync('git status --short',{encoding:'utf8'}).trim();if(st){execSync('git commit -m "fix: all technical details removed from merchant-facing UI"',{stdio:'inherit'});}execSync('git push origin main',{stdio:'inherit'});console.log('\n✅ Pushed!');process.chdir('frontend');execSync('vercel --prod --force',{stdio:'inherit'});console.log('\n🚀 LIVE');}catch(e){console.log(e.message);}